//! Minimal terminal size query (original implementation).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of_fd(libc::STDOUT_FILENO)
        .or_else(|| terminal_size_of_fd(libc::STDERR_FILENO))
        .or_else(|| terminal_size_of_fd(libc::STDIN_FILENO))
}

fn terminal_size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}
