//! Command line interface definitions.

pub mod build;
pub mod clean;
pub mod completions;
pub mod init;
pub mod serve;
pub mod test;
pub mod watch;

use clap::{Arg, ArgAction, ArgMatches, Command};
use std::path::PathBuf;

const VERSION: &str = concat!("v", env!("CARGO_PKG_VERSION"));

pub fn create_clap_command() -> Command {
    Command::new("mdbook")
        .about("Creates a book from markdown files")
        .author("Mathieu David <mathieudavid@mathieudavid.org>")
        .version(VERSION)
        .propagate_version(true)
        .arg_required_else_help(true)
        .after_help(
            "For more information about a specific command, try `mdbook <command> --help`\n\
             The source code for mdBook is available at: https://github.com/rust-lang/mdBook",
        )
        .subcommand(init::make_subcommand())
        .subcommand(build::make_subcommand())
        .subcommand(test::make_subcommand())
        .subcommand(clean::make_subcommand())
        .subcommand(completions::make_subcommand())
        .subcommand(watch::make_subcommand())
        .subcommand(serve::make_subcommand())
}

pub fn dir_arg(help: &'static str) -> Arg {
    Arg::new("dir")
        .help(help)
        .value_parser(clap::value_parser!(PathBuf))
}

pub fn dest_dir_arg() -> Arg {
    Arg::new("dest-dir")
        .short('d')
        .long("dest-dir")
        .value_name("dest-dir")
        .value_parser(clap::value_parser!(PathBuf))
        .help(
            "Output directory for the book\n\
             Relative paths are interpreted relative to the book's root directory.\n\
             If omitted, mdBook uses build.build-dir from book.toml or defaults to `./book`.",
        )
}

pub fn open_arg() -> Arg {
    Arg::new("open")
        .short('o')
        .long("open")
        .action(ArgAction::SetTrue)
        .help("Opens the compiled book in a web browser")
}

pub fn watcher_arg() -> Arg {
    Arg::new("watcher")
        .long("watcher")
        .value_name("watcher")
        .value_parser(["poll", "native"])
        .default_value("poll")
        .help("The filesystem watching technique")
}

/// Resolve the book root directory from the matches (defaults to cwd).
pub fn get_book_dir(args: &ArgMatches) -> PathBuf {
    if let Some(p) = args.get_one::<PathBuf>("dir") {
        if p.is_relative() {
            std::env::current_dir().unwrap().join(p)
        } else {
            p.clone()
        }
    } else {
        std::env::current_dir().expect("Unable to determine the current directory")
    }
}
