//! Miscellaneous utilities shared across the crate.

use crate::errors::*;
use log::{error, trace};
use std::borrow::Cow;
use std::fs::{self, File};
use std::io::Write;
use std::path::{Component, Path, PathBuf};

/// Log an error and all of its causes, like mdBook does.
pub fn log_backtrace(e: &Error) {
    error!("Error: {}", e);
    for cause in e.chain().skip(1) {
        error!("\tCaused By: {}", cause);
    }
}

/// Normalize a path: resolve `.` and `..` lexically.
pub fn normalize_path(path: &Path) -> PathBuf {
    let mut ret = PathBuf::new();
    for component in path.components() {
        match component {
            Component::Prefix(..) => unreachable!(),
            Component::RootDir => {
                ret.push(component.as_os_str());
            }
            Component::CurDir => {}
            Component::ParentDir => {
                ret.pop();
            }
            Component::Normal(c) => {
                ret.push(c);
            }
        }
    }
    ret
}

/// Write some content to a file, creating parent directories as needed.
pub fn write_file<P: AsRef<Path>>(build_dir: &Path, filename: P, content: &[u8]) -> Result<()> {
    let path = build_dir.join(filename);
    create_file(&path)?.write_all(content).map_err(Into::into)
}

/// Create a file (and its parent directories).
pub fn create_file(path: &Path) -> Result<File> {
    log::debug!("Creating {}", path.display());
    if let Some(p) = path.parent() {
        trace!("Parent directory is: {:?}", p);
        fs::create_dir_all(p)?;
    }
    File::create(path).map_err(Into::into)
}

/// Compute `../` repeated for every directory component of the path.
pub fn path_to_root<P: Into<PathBuf>>(path: P) -> String {
    let path = path.into();
    path.parent()
        .map(|p| {
            p.components()
                .fold(String::new(), |mut s, c| {
                    match c {
                        Component::Normal(_) => s.push_str("../"),
                        _ => {
                            log::debug!("Other path component... {:?}", c);
                        }
                    }
                    s
                })
        })
        .unwrap_or_default()
}

/// Remove everything inside a directory (but keep the directory itself).
pub fn remove_dir_content(dir: &Path) -> Result<()> {
    for item in fs::read_dir(dir)? {
        if let Ok(item) = item {
            let item = item.path();
            if item.is_dir() {
                fs::remove_dir_all(item)?;
            } else {
                fs::remove_file(item)?;
            }
        }
    }
    Ok(())
}

/// Copy everything in `from` to `to`, optionally recursively, with filters.
pub fn copy_files_except_ext(
    from: &Path,
    to: &Path,
    recursive: bool,
    avoid_dir: Option<&PathBuf>,
    ext_blacklist: &[&str],
) -> Result<()> {
    log::debug!(
        "Copying all files from {} to {} (blacklist: {:?}), avoiding {:?}",
        from.display(),
        to.display(),
        ext_blacklist,
        avoid_dir
    );

    if !from.is_dir() {
        return Ok(());
    }
    let mut entries: Vec<_> = fs::read_dir(from)?.filter_map(|e| e.ok()).collect();
    entries.sort_by_key(|e| e.file_name());

    for entry in entries {
        let path = entry.path();
        let metadata = path.metadata().with_context(|| format!("{path:?} does not exist"))?;

        let entry_file_name = match path.file_name() {
            Some(f) => f.to_os_string(),
            None => continue,
        };
        let target_file_path = to.join(&entry_file_name);

        if metadata.is_dir() {
            if path == to.to_path_buf() {
                continue;
            }
            if let Some(avoid) = avoid_dir {
                if &path == avoid {
                    continue;
                }
            }
            if !recursive {
                continue;
            }
            if !target_file_path.exists() {
                fs::create_dir(&target_file_path)?;
            }
            copy_files_except_ext(&path, &target_file_path, true, avoid_dir, ext_blacklist)?;
        } else if metadata.is_file() {
            if let Some(ext) = path.extension() {
                if ext_blacklist.contains(&ext.to_str().unwrap_or("")) {
                    continue;
                }
            }
            log::debug!(
                "creating path for file: {:?}",
                &to.join(entry.path().file_name().expect("a file should have a file name..."))
            );
            log::debug!("Copying {:?} to {:?}", path, target_file_path);
            copy(&path, &target_file_path)?;
        }
    }
    Ok(())
}

fn copy(from: &Path, to: &Path) -> Result<()> {
    if let Some(parent) = to.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::copy(from, to)
        .with_context(|| format!("failed to copy `{}` to `{}`", from.display(), to.display()))?;
    Ok(())
}

/// Replace all characters that aren't safe in an id.
pub fn normalize_id(content: &str) -> String {
    content
        .chars()
        .filter_map(|ch| {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                Some(ch.to_ascii_lowercase())
            } else if ch.is_whitespace() {
                Some('-')
            } else {
                None
            }
        })
        .collect::<String>()
}

/// Generate a unique id from content, remembering already used ids.
pub fn unique_id_from_content(content: &str, id_counter: &mut std::collections::HashMap<String, usize>) -> String {
    let id = {
        let id = normalize_id(content);
        if id.is_empty() {
            "".to_string()
        } else {
            id
        }
    };

    // If we have headers with the same normalized id, append an incrementing counter
    let id_count = id_counter.entry(id.clone()).or_insert(0);
    let unique_id = match *id_count {
        0 => id,
        id_count => format!("{id}-{id_count}"),
    };
    *id_count += 1;
    unique_id
}

/// Escape HTML special characters.
pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

/// Escape only `&`, `<`, `>` and `"` (pulldown-cmark style).
pub fn escape_html_body(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Take a string and make it a (lossy) string, replacing CRLF with LF.
pub fn normalize_newlines(s: &str) -> Cow<'_, str> {
    if s.contains('\r') {
        Cow::Owned(s.replace("\r\n", "\n").replace('\r', "\n"))
    } else {
        Cow::Borrowed(s)
    }
}

/// Get the absolute path of a given path, relative to a base directory when not absolute.
pub fn absolute_from(base: &Path, p: &Path) -> PathBuf {
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        base.join(p)
    }
}

/// Convert a path to a string using forward slashes.
pub fn path_to_slash(p: &Path) -> String {
    let s = p.to_string_lossy();
    s.replace('\\', "/")
}
