    let mut last_space = false;
    for c in label.trim().chars() {
        if c.is_whitespace() {
            if !last_space {
                out.push(' ');
            }
            last_space = true;
        } else {
            last_space = false;
            // Unicode case fold approximation
            for lc in c.to_lowercase() {
                out.push(lc);
            }
            // Special-case the few characters whose case fold differs from lowercase.
        }
    }
    // Handle ß -> ss style folding
    out.replace('ß', "ss").replace('ſ', "s")
