/// Try to parse an entity reference at the start of `s` (which starts with `&`).
/// Returns the decoded string and the number of bytes consumed.
pub fn parse_entity(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'&') {
        return None;
    }
    if bytes.get(1) == Some(&b'#') {
        // numeric
        let (hex, start) = match bytes.get(2) {
            Some(b'x') | Some(b'X') => (true, 3),
            _ => (false, 2),
        };
        let mut i = start;
        let max_digits = if hex { 6 } else { 7 };
        while i < bytes.len() && i - start < max_digits {
            let b = bytes[i];
            let ok = if hex { b.is_ascii_hexdigit() } else { b.is_ascii_digit() };
            if !ok {
                break;
            }
            i += 1;
        }
        if i == start {
            return None;
        }
        if bytes.get(i) != Some(&b';') {
            return None;
        }
        let digits = &s[start..i];
        let code = if hex {
            u32::from_str_radix(digits, 16).ok()?
        } else {
            digits.parse::<u32>().ok()?
        };
        let c = if code == 0 {
            '\u{FFFD}'
        } else {
            char::from_u32(code).unwrap_or('\u{FFFD}')
        };
        return Some((c.to_string(), i + 1));
    }
    // named
    let mut i = 1;
    while i < bytes.len() && i < 40 && bytes[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i == 1 || bytes.get(i) != Some(&b';') {
        return None;
    }
    let name = &s[1..i];
    entities::lookup(name).map(|v| (v.to_string(), i + 1))
}

/// Process backslash escapes and entity references in a string (used for
/// link destinations, titles, info strings and so on).
pub fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        match c {
            '\\' => {
                if let Some(&(_, next)) = chars.peek() {
                    if next.is_ascii_punctuation() {
                        out.push(next);
                        chars.next();
                        continue;
                    }
                }
                out.push('\\');
            }
            '&' => {
                if let Some((decoded, len)) = parse_entity(&s[i..]) {
                    out.push_str(&decoded);
                    // skip consumed chars
                    let end = i + len;
                    while let Some(&(j, _)) = chars.peek() {
                        if j < end {
                            chars.next();
                        } else {
                            break;
                        }
                    }
                } else {
                    out.push('&');
                }
            }
            _ => out.push(c),
        }
    }
    out
}

fn is_tag_name_start(b: u8) -> bool {
    b.is_ascii_alphabetic()
}

fn is_tag_name_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'-'
}

/// Scan an HTML tag name starting at `s[0]`. Returns its length.
pub fn scan_tag_name(s: &[u8]) -> Option<usize> {
    if s.is_empty() || !is_tag_name_start(s[0]) {
        return None;
    }
    let mut i = 1;
    while i < s.len() && is_tag_name_char(s[i]) {
        i += 1;
    }
    Some(i)
}

fn is_attr_name_start(b: u8) -> bool {
    b.is_ascii_alphabetic() || b == b'_' || b == b':'
}

fn is_attr_name_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_' || b == b':' || b == b'.' || b == b'-'
}

/// Skip whitespace (including at most... any newlines). Returns new index.
fn skip_ws(s: &[u8], mut i: usize) -> usize {
    while i < s.len() && matches!(s[i], b' ' | b'\t' | b'\n' | b'\r' | b'\x0C') {
        i += 1;
    }
    i
}

/// Scan an inline HTML open tag `<tag attr=value ... /?>`. `s` starts with `<`.
/// Returns the length of the tag.
pub fn scan_html_open_tag(s: &[u8]) -> Option<usize> {
    if s.first() != Some(&b'<') {
        return None;
    }
    let name_len = scan_tag_name(&s[1..])?;
    let mut i = 1 + name_len;
    loop {
        let ws_start = i;
        i = skip_ws(s, i);
        if i >= s.len() {
            return None;
        }
        match s[i] {
            b'/' => {
                if s.get(i + 1) == Some(&b'>') {
                    return Some(i + 2);
                }
                return None;
            }
            b'>' => return Some(i + 1),
            _ => {
                // attribute needs preceding whitespace
                if i == ws_start {
                    return None;
                }
                if !is_attr_name_start(s[i]) {
                    return None;
                }
                i += 1;
                while i < s.len() && is_attr_name_char(s[i]) {
                    i += 1;
                }
                // optional value spec
                let j = skip_ws(s, i);
                if j < s.len() && s[j] == b'=' {
                    let mut k = skip_ws(s, j + 1);
                    if k >= s.len() {
                        return None;
                    }
                    match s[k] {
                        b'\'' => {
                            k += 1;
                            while k < s.len() && s[k] != b'\'' {
                                k += 1;
                            }
                            if k >= s.len() {
                                return None;
                            }
                            i = k + 1;
                        }
                        b'"' => {
                            k += 1;
                            while k < s.len() && s[k] != b'"' {
                                k += 1;
                            }
                            if k >= s.len() {
                                return None;
                            }
                            i = k + 1;
                        }
                        _ => {
                            let start = k;
                            while k < s.len()
                                && !matches!(
                                    s[k],
                                    b' ' | b'\t' | b'\n' | b'\r' | b'\x0C' | b'"' | b'\'' | b'=' | b'<' | b'>' | b'`'
                                )
                            {
                                k += 1;
                            }
                            if k == start {
                                return None;
                            }
                            i = k;
                        }
                    }
                }
            }
        }
    }
}

/// Scan an HTML closing tag `</tag >`.
pub fn scan_html_closing_tag(s: &[u8]) -> Option<usize> {
    if s.len() < 2 || s[0] != b'<' || s[1] != b'/' {
        return None;
    }
    let name_len = scan_tag_name(&s[2..])?;
    let i = skip_ws(s, 2 + name_len);
    if i < s.len() && s[i] == b'>' {
        Some(i + 1)
    } else {
        None
    }
}

/// Scan any kind of inline raw HTML construct starting at `s` (which begins with `<`).
pub fn scan_inline_html(s: &[u8]) -> Option<usize> {
    if s.first() != Some(&b'<') {
        return None;
    }
    if let Some(n) = scan_html_open_tag(s) {
        return Some(n);
    }
    if let Some(n) = scan_html_closing_tag(s) {
        return Some(n);
    }
    if s.starts_with(b"<!--") {
        // comment: <!-->, <!--->, or <!-- text -->
        if s.starts_with(b"<!-->") {
            return Some(5);
        }
        if s.starts_with(b"<!--->") {
            return Some(6);
        }
        let mut i = 4;
        while i + 2 < s.len() + 0 {
            if s[i] == b'-' && s.get(i + 1) == Some(&b'-') && s.get(i + 2) == Some(&b'>') {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if s.starts_with(b"<?") {
        let mut i = 2;
        while i + 1 < s.len() {
            if s[i] == b'?' && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            i += 1;
        }
        return None;
    }
    if s.starts_with(b"<![CDATA[") {
        let mut i = 9;
        while i + 2 < s.len() {
            if s[i] == b']' && s[i + 1] == b']' && s[i + 2] == b'>' {
                return Some(i + 3);
            }
            i += 1;
        }
        return None;
    }
    if s.starts_with(b"<!") && s.len() > 2 && s[2].is_ascii_alphabetic() {
        let mut i = 3;
        while i < s.len() {
            if s[i] == b'>' {
                return Some(i + 1);
            }
            i += 1;
        }
        return None;
    }
    None
}

/// Scan an autolink `<scheme:...>` or `<email>`. Returns (len, url, is_email).
pub fn scan_autolink(s: &str) -> Option<(usize, String, bool)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'<') {
        return None;
    }
    // URI autolink
    if let Some(end) = bytes.iter().position(|&b| b == b'>') {
        let inner = &s[1..end];
        if is_uri_autolink(inner) {
            return Some((end + 1, inner.to_string(), false));
        }
        if is_email_autolink(inner) {
            return Some((end + 1, inner.to_string(), true));
        }
    }
    None
}

fn is_uri_autolink(s: &str) -> bool {
    let bytes = s.as_bytes();
    // scheme: [a-zA-Z][a-zA-Z0-9+.-]{1,31}:
    if bytes.is_empty() || !bytes[0].is_ascii_alphabetic() {
        return false;
    }
    let mut i = 1;
    while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || matches!(bytes[i], b'+' | b'.' | b'-')) {
        i += 1;
    }
    if i < 2 || i > 32 {
        return false;
    }
    if bytes.get(i) != Some(&b':') {
        return false;
    }
    for &b in &bytes[i + 1..] {
        if b <= b' ' || b == b'<' || b == b'>' || b == 0x7F {
            return false;
        }
    }
    true
}

fn is_email_autolink(s: &str) -> bool {
    let bytes = s.as_bytes();
    let at = match bytes.iter().position(|&b| b == b'@') {
        Some(p) => p,
        None => return false,
    };
    if at == 0 {
        return false;
    }
    for &b in &bytes[..at] {
        if !(b.is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&b)) {
            return false;
        }
    }
    let domain = &bytes[at + 1..];
    if domain.is_empty() {
        return false;
    }
    for label in domain.split(|&b| b == b'.') {
        if label.is_empty() || label.len() > 63 {
            return false;
        }
        if !label[0].is_ascii_alphanumeric() || !label[label.len() - 1].is_ascii_alphanumeric() {
            return false;
        }
        for &b in label {
            if !(b.is_ascii_alphanumeric() || b == b'-') {
                return false;
            }
        }
    }
    true
}

/// Scan a link destination starting at `s`. Returns (raw destination, bytes consumed).
pub fn scan_link_destination(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    if bytes[0] == b'<' {
        let mut i = 1;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
                b'>' => return Some((unescape(&s[1..i]), i + 1)),
                b'<' | b'\n' => return None,
                _ => i += 1,
            }
        }
        return None;
    }
    let mut i = 0;
    let mut depth = 0i32;
    while i < bytes.len() {
        let b = bytes[i];
        match b {
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
            b'(' => {
                depth += 1;
                if depth > 32 {
                    return None;
                }
                i += 1;
            }
            b')' => {
                if depth == 0 {
                    break;
                }
                depth -= 1;
                i += 1;
            }
            _ if b <= b' ' || b == 0x7F => break,
            _ => i += 1,
        }
    }
    if depth != 0 {
        return None;
    }
    Some((unescape(&s[..i]), i))
}

/// Scan a link title. Returns (title, bytes consumed).
pub fn scan_link_title(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    let open = *bytes.first()?;
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut i = 1;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'\\' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() {
            i += 2;
            continue;
        }
        if b == close {
            return Some((unescape(&s[1..i]), i + 1));
        }
        if open == b'(' && b == b'(' {
            return None;
        }
        i += 1;
    }
    None
}

/// Scan a link label `[...]` (including brackets). Returns (raw label, consumed).
/// Label must be non-empty (contain a non-whitespace char) and at most 999 chars.
pub fn scan_link_label(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    if bytes.first() != Some(&b'[') {
        return None;
    }
    let mut i = 1;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
            b'[' => return None,
            b']' => {
                let label = &s[1..i];
                if i - 1 > 999 || label.trim().is_empty() {
                    return None;
                }
                return Some((label.to_string(), i + 1));
            }
            _ => i += 1,
        }
    }
    None
}

