//! Block structure parser (CommonMark container/leaf block algorithm).

use super::inline::{parse_inlines, InlineContext};
use super::scan::{self, unescape};
use super::*;

#[derive(Debug, Clone, PartialEq)]
pub(crate) enum Kind {
    Document,
    BlockQuote,
    List(ListData),
    Item(ListData),
    Paragraph,
    Heading {
        level: u8,
        setext: bool,
    },
    ThematicBreak,
    IndentedCode,
    FencedCode {
        fence_char: u8,
        fence_len: usize,
        fence_offset: usize,
    },
    HtmlBlock {
        kind: u8,
    },
    FootnoteDef {
        label: String,
    },
    Table {
        alignments: Vec<Alignment>,
        header: Vec<String>,
        rows: Vec<Vec<String>>,
    },
}

#[derive(Debug, Clone, PartialEq)]
pub(crate) struct ListData {
    ordered: bool,
    bullet_char: u8,
    start: u64,
    delimiter: u8,
    tight: bool,
    marker_offset: usize,
    padding: usize,
}

#[derive(Debug)]
pub(crate) struct Node {
    kind: Kind,
    parent: Option<usize>,
    children: Vec<usize>,
    open: bool,
    last_line_blank: bool,
    last_line_checked: bool,
    lines: Vec<String>,
    start_line: usize,
    /// For fenced code blocks: the raw info string.
    info: String,
    /// Heading attributes (raw inside of `{...}`).
    attr_block: Option<String>,
}

impl Node {
    fn new(kind: Kind, start_line: usize) -> Node {
        Node {
            kind,
            parent: None,
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            last_line_checked: false,
            lines: Vec::new(),
            start_line,
            info: String::new(),
            attr_block: None,
        }
    }

    fn accepts_lines(&self) -> bool {
        matches!(
            self.kind,
            Kind::Paragraph | Kind::IndentedCode | Kind::FencedCode { .. } | Kind::HtmlBlock { .. } | Kind::Table { .. }
        )
    }

    fn is_code_or_html(&self) -> bool {
        matches!(
            self.kind,
            Kind::IndentedCode | Kind::FencedCode { .. } | Kind::HtmlBlock { .. }
        )
    }
}

pub(crate) struct BlockParser<'a> {
    nodes: Vec<Node>,
    tip: usize,
    old_tip: usize,
    last_matched_container: usize,
    line: &'a str,
    line_number: usize,
    offset: usize,
    column: usize,
    next_nonspace: usize,
    next_nonspace_column: usize,
    indent: usize,
    indented: bool,
    blank: bool,
    partially_consumed_tab: bool,
    all_closed: bool,
    options: Options,
    pub refmap: RefMap,
    pub footnote_labels: std::collections::HashSet<String>,
}

const CODE_INDENT: usize = 4;

fn is_space_or_tab(b: Option<u8>) -> bool {
    matches!(b, Some(b' ') | Some(b'\t'))
}

impl<'a> BlockParser<'a> {
    fn new(options: Options) -> Self {
        let mut nodes = Vec::new();
        nodes.push(Node::new(Kind::Document, 1));
        BlockParser {
            nodes,
            tip: 0,
            old_tip: 0,
            last_matched_container: 0,
            line: "",
            line_number: 0,
            offset: 0,
            column: 0,
            next_nonspace: 0,
            next_nonspace_column: 0,
            indent: 0,
            indented: false,
            blank: false,
            partially_consumed_tab: false,
            all_closed: true,
            options,
            refmap: RefMap::new(),
            footnote_labels: Default::default(),
        }
    }

    fn peek(&self, pos: usize) -> Option<u8> {
        self.line.as_bytes().get(pos).copied()
    }

    fn rest_from(&self, pos: usize) -> &'a str {
        if pos >= self.line.len() {
            ""
        } else {
            &self.line[pos..]
        }
    }

    fn add_child(&mut self, kind: Kind) -> usize {
        // close any blocks that cannot contain this kind
        while !self.can_contain(self.tip, &kind) {
            self.finalize(self.tip, self.line_number - 1);
        }
        let mut node = Node::new(kind, self.line_number);
        node.parent = Some(self.tip);
        let idx = self.nodes.len();
        self.nodes.push(node);
        self.nodes[self.tip].children.push(idx);
        self.tip = idx;
        idx
    }

    fn can_contain(&self, idx: usize, kind: &Kind) -> bool {
        match &self.nodes[idx].kind {
            Kind::Document | Kind::BlockQuote | Kind::Item(_) | Kind::FootnoteDef { .. } => {
                !matches!(kind, Kind::Item(_))
            }
            Kind::List(_) => matches!(kind, Kind::Item(_)),
            _ => false,
        }
    }

    fn find_next_nonspace(&mut self) {
        let mut i = self.offset;
        let mut cols = self.column;
        let bytes = self.line.as_bytes();
        loop {
            match bytes.get(i) {
                Some(b' ') => {
                    i += 1;
                    cols += 1;
                }
                Some(b'\t') => {
                    i += 1;
                    cols += 4 - (cols % 4);
                }
                _ => break,
            }
        }
        self.blank = match bytes.get(i) {
            None => true,
            Some(b'\n') | Some(b'\r') => true,
            _ => false,
        };
        self.next_nonspace = i;
        self.next_nonspace_column = cols;
        self.indent = self.next_nonspace_column - self.column;
        self.indented = self.indent >= CODE_INDENT;
    }

    fn advance_next_nonspace(&mut self) {
        self.offset = self.next_nonspace;
        self.column = self.next_nonspace_column;
        self.partially_consumed_tab = false;
    }

    fn advance_offset(&mut self, mut count: usize, columns: bool) {
        let bytes = self.line.as_bytes();
        while count > 0 {
            match bytes.get(self.offset) {
                None => break,
                Some(b'\t') => {
                    let chars_to_tab = 4 - (self.column % 4);
                    if columns {
                        self.partially_consumed_tab = chars_to_tab > count;
                        let chars_to_advance = chars_to_tab.min(count);
                        self.column += chars_to_advance;
                        if !self.partially_consumed_tab {
                            self.offset += 1;
                        }
                        count -= chars_to_advance;
                    } else {
                        self.partially_consumed_tab = false;
                        self.column += chars_to_tab;
                        self.offset += 1;
                        count -= 1;
                    }
                }
                Some(_) => {
                    self.partially_consumed_tab = false;
                    self.offset += 1;
                    self.column += 1;
                    count -= 1;
                }
            }
        }
    }

    fn add_line(&mut self) {
        let mut s = String::new();
        if self.partially_consumed_tab {
            self.offset += 1; // skip over tab
            let chars_to_tab = 4 - (self.column % 4);
            for _ in 0..chars_to_tab {
                s.push(' ');
            }
        }
        s.push_str(self.rest_from(self.offset));
        let tip = self.tip;
        self.nodes[tip].lines.push(s);
    }

    fn close_unmatched_blocks(&mut self) {
        if !self.all_closed {
            while self.old_tip != self.last_matched_container {
                let parent = self.nodes[self.old_tip].parent.unwrap();
                self.finalize(self.old_tip, self.line_number - 1);
                self.old_tip = parent;
            }
            self.all_closed = true;
        }
    }

    fn finalize(&mut self, idx: usize, _line_number: usize) {
        let parent = self.nodes[idx].parent;
        self.nodes[idx].open = false;

        match self.nodes[idx].kind.clone() {
            Kind::Paragraph => {
                // Extract link reference definitions.
                let content = self.nodes[idx].lines.join("\n");
                let mut rest: &str = &content;
                let mut consumed = 0;
                while rest.starts_with('[') {
                    match parse_reference_definition(rest) {
                        Some((label, def, len)) => {
                            let key = normalize_label(&label);
                            self.refmap.entry(key).or_insert(def);
                            rest = &rest[len..];
                            consumed += len;
                        }
                        None => break,
                    }
                }
                if consumed > 0 {
                    let remaining = content[consumed..].to_string();
                    if remaining.trim().is_empty() {
                        // remove the paragraph entirely
                        self.nodes[idx].lines.clear();
                        if let Some(p) = parent {
                            self.nodes[p].children.retain(|&c| c != idx);
                        }
                    } else {
                        self.nodes[idx].lines = remaining.split('\n').map(|s| s.to_string()).collect();
                    }
                }
            }
            Kind::IndentedCode => {
                // strip trailing blank lines
                while let Some(last) = self.nodes[idx].lines.last() {
                    if last.trim().is_empty() {
                        self.nodes[idx].lines.pop();
                    } else {
                        break;
                    }
                }
            }
            Kind::FencedCode { .. } => {
                // first line is the info string
                if !self.nodes[idx].lines.is_empty() {
                    let first = self.nodes[idx].lines.remove(0);
                    self.nodes[idx].info = unescape(first.trim());
                }
            }
            Kind::List(_) => {
                let items = self.nodes[idx].children.clone();
                let mut tight = true;
                let n = items.len();
                'outer: for (i, &item) in items.iter().enumerate() {
                    // check for non-final list item ending with blank line
                    if self.ends_with_blank_line(item) && i + 1 < n {
                        tight = false;
                        break;
                    }
                    // recurse into children of list item, to see if there are
                    // spaces between any of them
                    let subitems = self.nodes[item].children.clone();
                    let m = subitems.len();
                    for (j, &sub) in subitems.iter().enumerate() {
                        if self.ends_with_blank_line(sub) && (i + 1 < n || j + 1 < m) {
                            tight = false;
                            break 'outer;
                        }
                    }
                }
                if let Kind::List(ref mut data) = self.nodes[idx].kind {
                    data.tight = tight;
                }
            }
            _ => {}
        }

        if let Some(p) = parent {
            self.tip = p;
        }
    }

    fn ends_with_blank_line(&mut self, mut idx: usize) -> bool {
        loop {
            if self.nodes[idx].last_line_blank {
                return true;
            }
            let is_list_like = matches!(self.nodes[idx].kind, Kind::List(_) | Kind::Item(_));
            if !self.nodes[idx].last_line_checked && is_list_like {
                self.nodes[idx].last_line_checked = true;
                match self.nodes[idx].children.last() {
                    Some(&last) => idx = last,
                    None => return false,
                }
            } else {
                self.nodes[idx].last_line_checked = true;
                return false;
            }
        }
    }

    // ---------------------------------------------------------------------
    // Continuation checks. Return 0 = matched, 1 = not matched, 2 = line consumed.
    fn try_continue(&mut self, idx: usize) -> u8 {
        let kind = self.nodes[idx].kind.clone();
        match kind {
            Kind::Document | Kind::List(_) => 0,
            Kind::BlockQuote => {
                if !self.indented && self.peek(self.next_nonspace) == Some(b'>') {
                    self.advance_next_nonspace();
                    self.advance_offset(1, false);
                    if is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                    0
                } else {
                    1
                }
            }
            Kind::Item(data) => {
                if self.blank {
                    if self.nodes[idx].children.is_empty() {
                        1
                    } else {
                        self.advance_next_nonspace();
                        0
                    }
                } else if self.indent >= data.marker_offset + data.padding {
                    self.advance_offset(data.marker_offset + data.padding, true);
                    0
                } else {
                    1
                }
            }
            Kind::FootnoteDef { .. } => {
                if self.blank {
                    if self.nodes[idx].children.is_empty() {
                        1
                    } else {
                        self.advance_next_nonspace();
                        0
                    }
                } else if self.indent >= 4 {
                    self.advance_offset(4, true);
                    0
                } else {
                    1
                }
            }
            Kind::Heading { .. } | Kind::ThematicBreak => 1,
            Kind::FencedCode {
                fence_char,
                fence_len,
                fence_offset,
            } => {
                // closing fence?
                if self.indent <= 3 && self.peek(self.next_nonspace) == Some(fence_char) {
                    let rest = self.rest_from(self.next_nonspace);
                    let n = rest.bytes().take_while(|&b| b == fence_char).count();
                    if n >= fence_len && rest[n..].trim_matches(|c| c == ' ' || c == '\t').is_empty() {
                        // closing fence - we're at end of line, so we can return
                        self.finalize(idx, self.line_number);
                        return 2;
                    }
                }
                // skip optional spaces of fence offset
                let mut i = fence_offset;
                while i > 0 && is_space_or_tab(self.peek(self.offset)) {
                    self.advance_offset(1, true);
                    i -= 1;
                }
                0
            }
            Kind::IndentedCode => {
                if self.indent >= CODE_INDENT {
                    self.advance_offset(CODE_INDENT, true);
                    0
                } else if self.blank {
                    self.advance_next_nonspace();
                    0
                } else {
                    1
                }
            }
            Kind::HtmlBlock { kind } => {
                if self.blank && (kind == 6 || kind == 7) {
                    1
                } else {
                    0
                }
            }
            Kind::Paragraph => {
                if self.blank {
                    1
                } else {
                    0
                }
            }
            Kind::Table { .. } => {
                if self.blank {
                    return 1;
                }
                // Does this line start another block?
                if self.line_starts_block() {
                    1
                } else {
                    0
                }
            }
        }
    }

    /// Check whether the current line (at next_nonspace) would start a new block
    /// that can interrupt a table.
    fn line_starts_block(&self) -> bool {
        let rest = self.rest_from(self.next_nonspace);
        if self.indented {
            return false;
        }
        let b = rest.as_bytes().first().copied();
        match b {
            Some(b'>') => true,
            Some(b'#') => scan_atx_heading(rest).is_some(),
            Some(b'`') | Some(b'~') => scan_fence_open(rest).is_some(),
            Some(b'<') => scan_html_block_start(rest, false).is_some(),
            Some(b'*') | Some(b'-') | Some(b'_') if scan_thematic_break(rest) => true,
            Some(b'*') | Some(b'-') | Some(b'+') => {
                // bullet list marker followed by space/eol
                rest.len() == 1 || is_space_or_tab(rest.as_bytes().get(1).copied())
            }
            Some(b'0'..=b'9') => {
                let n = rest.bytes().take_while(|b| b.is_ascii_digit()).count();
                if n <= 9 {
                    let after = rest.as_bytes().get(n).copied();
                    if matches!(after, Some(b'.') | Some(b')')) {
                        let after2 = rest.as_bytes().get(n + 1).copied();
                        return after2.is_none() || is_space_or_tab(after2);
                    }
                }
                false
            }
            Some(b'[') if self.options.footnotes => scan_footnote_def(rest).is_some(),
            _ => false,
        }
    }

    // ---------------------------------------------------------------------
    // Block starts. Return 0 = no match, 1 = container matched, 2 = leaf matched.
    fn try_block_starts(&mut self, container: usize) -> u8 {
        // block quote
        if !self.indented && self.peek(self.next_nonspace) == Some(b'>') {
            self.advance_next_nonspace();
            self.advance_offset(1, false);
            if is_space_or_tab(self.peek(self.offset)) {
                self.advance_offset(1, true);
            }
            self.close_unmatched_blocks();
            self.add_child(Kind::BlockQuote);
            return 1;
        }
        // ATX heading
        if !self.indented {
            let rest = self.rest_from(self.next_nonspace);
            if let Some((level, marker_len)) = scan_atx_heading(rest) {
                self.advance_next_nonspace();
                self.advance_offset(marker_len, false);
                self.close_unmatched_blocks();
                let idx = self.add_child(Kind::Heading { level, setext: false });
                let content = self.rest_from(self.offset);
                let content = strip_atx_closing(content);
                let (content, attrs) = if self.options.heading_attributes {
                    extract_heading_attrs(content)
                } else {
                    (content.to_string(), None)
                };
                self.nodes[idx].lines.push(content);
                self.nodes[idx].attr_block = attrs;
                self.offset = self.line.len();
                return 2;
            }
        }
        // fenced code block
        if !self.indented {
            let rest = self.rest_from(self.next_nonspace);
            if let Some((fence_char, fence_len)) = scan_fence_open(rest) {
                let fence_offset = self.indent;
                self.close_unmatched_blocks();
                self.add_child(Kind::FencedCode {
                    fence_char,
                    fence_len,
                    fence_offset,
                });
                self.advance_next_nonspace();
                self.advance_offset(fence_len, false);
                return 2;
            }
        }
        // HTML block
        if !self.indented && self.peek(self.next_nonspace) == Some(b'<') {
            let rest = self.rest_from(self.next_nonspace);
            let in_paragraph = matches!(self.nodes[container].kind, Kind::Paragraph)
                || (!self.all_closed && !self.blank && matches!(self.nodes[self.tip].kind, Kind::Paragraph));
            if let Some(kind) = scan_html_block_start(rest, in_paragraph) {
                self.close_unmatched_blocks();
                // We don't adjust offset; spaces are part of the HTML block.
                self.add_child(Kind::HtmlBlock { kind });
                return 2;
            }
        }
        // Setext heading
        if !self.indented && matches!(self.nodes[container].kind, Kind::Paragraph) {
            let rest = self.rest_from(self.next_nonspace);
            if let Some(level) = scan_setext_underline(rest) {
                self.close_unmatched_blocks();
                // resolve reference link definitions
                let content = self.nodes[container].lines.join("\n");
                let mut remaining: &str = &content;
                while remaining.starts_with('[') {
                    match parse_reference_definition(remaining) {
                        Some((label, def, len)) => {
                            let key = normalize_label(&label);
                            self.refmap.entry(key).or_insert(def);
                            remaining = &remaining[len..];
                        }
                        None => break,
                    }
                }
                if !remaining.is_empty() {
                    let (text, attrs) = if self.options.heading_attributes {
                        extract_heading_attrs(remaining)
                    } else {
                        (remaining.to_string(), None)
                    };
                    let node = &mut self.nodes[container];
                    node.kind = Kind::Heading { level, setext: true };
                    node.lines = text.split('\n').map(|s| s.to_string()).collect();
                    node.attr_block = attrs;
                    self.offset = self.line.len();
                    return 2;
                } else {
                    // paragraph consisted only of reference definitions; remove it
                    self.nodes[container].lines.clear();
                    let parent = self.nodes[container].parent.unwrap();
                    self.nodes[parent].children.retain(|&c| c != container);
                    self.nodes[container].open = false;
                    self.tip = parent;
                    // fall through to other block starts with the parent as container
                    return self.try_block_starts_no_setext(parent);
                }
            }
        }
        self.try_block_starts_rest(container)
    }

    fn try_block_starts_no_setext(&mut self, container: usize) -> u8 {
        self.try_block_starts_rest(container)
    }

    fn try_block_starts_rest(&mut self, container: usize) -> u8 {
        // thematic break
        if !self.indented {
            let rest = self.rest_from(self.next_nonspace);
            if scan_thematic_break(rest) {
                self.close_unmatched_blocks();
                self.add_child(Kind::ThematicBreak);
                self.offset = self.line.len();
                return 2;
            }
        }
        // footnote definition
        if self.options.footnotes && !self.indented && self.peek(self.next_nonspace) == Some(b'[') {
            let rest = self.rest_from(self.next_nonspace);
            if let Some((label, len)) = scan_footnote_def(rest) {
                let in_paragraph = matches!(self.nodes[container].kind, Kind::Paragraph);
                if !in_paragraph {
                    self.close_unmatched_blocks();
                    self.advance_next_nonspace();
                    self.advance_offset(len, false);
                    // skip following whitespace
                    while is_space_or_tab(self.peek(self.offset)) {
                        self.advance_offset(1, true);
                    }
                    self.footnote_labels.insert(label.clone());
                    self.add_child(Kind::FootnoteDef { label });
                    return 1;
                }
            }
        }
        // list item
        let is_list = matches!(self.nodes[container].kind, Kind::List(_));
        if !self.indented || is_list {
            if let Some(data) = self.parse_list_marker(container) {
                self.close_unmatched_blocks();
                // add the list if needed
                let tip_is_matching_list = match &self.nodes[self.tip].kind {
                    Kind::List(existing) => lists_match(existing, &data),
                    _ => false,
                };
                if !tip_is_matching_list {
                    self.add_child(Kind::List(data.clone()));
                }
                self.add_child(Kind::Item(data));
                return 1;
            }
        }
        // indented code block
        if self.indented && !matches!(self.nodes[self.tip].kind, Kind::Paragraph) && !self.blank {
            self.advance_offset(CODE_INDENT, true);
            self.close_unmatched_blocks();
            self.add_child(Kind::IndentedCode);
            return 2;
        }
        0
    }

    fn parse_list_marker(&mut self, container: usize) -> Option<ListData> {
        let rest = self.rest_from(self.next_nonspace);
        let bytes = rest.as_bytes();
        if self.indent >= 4 {
            return None;
        }
        let in_paragraph = matches!(self.nodes[container].kind, Kind::Paragraph);
        let (ordered, bullet_char, start, delimiter, marker_len) = match bytes.first() {
            Some(&c @ (b'*' | b'+' | b'-')) => (false, c, 1u64, 0u8, 1usize),
            Some(b'0'..=b'9') => {
                let n = bytes.iter().take_while(|b| b.is_ascii_digit()).count();
                if n > 9 {
                    return None;
                }
                let delim = *bytes.get(n)?;
                if delim != b'.' && delim != b')' {
                    return None;
                }
                let start: u64 = rest[..n].parse().ok()?;
                if in_paragraph && start != 1 {
                    return None;
                }
                (true, 0u8, start, delim, n + 1)
            }
            _ => return None,
        };
        // make sure we have spaces after
        let nextc = bytes.get(marker_len).copied();
        if !(nextc.is_none() || nextc == Some(b'\t') || nextc == Some(b' ')) {
            return None;
        }
        // if it interrupts paragraph, make sure first line isn't blank
        if in_paragraph && rest[marker_len..].trim().is_empty() {
            return None;
        }
        // we've got a match! advance offset and calculate padding
        self.advance_next_nonspace();
        self.advance_offset(marker_len, true);
        let spaces_start_col = self.column;
        let spaces_start_offset = self.offset;
        let spaces_start_ptab = self.partially_consumed_tab;
        loop {
            self.advance_offset(1, true);
            if !(self.column - spaces_start_col < 5 && is_space_or_tab(self.peek(self.offset))) {
                break;
            }
        }
        let blank_item = self.peek(self.offset).is_none();
        let spaces_after_marker = self.column - spaces_start_col;
        let padding;
        if spaces_after_marker >= 5 || spaces_after_marker < 1 || blank_item {
            padding = marker_len + 1;
            self.column = spaces_start_col;
            self.offset = spaces_start_offset;
            self.partially_consumed_tab = spaces_start_ptab;
            if is_space_or_tab(self.peek(self.offset)) {
                self.advance_offset(1, true);
            }
        } else {
            padding = marker_len + spaces_after_marker;
        }
        Some(ListData {
            ordered,
            bullet_char,
            start,
            delimiter,
            tight: true,
            marker_offset: self.indent,
            padding,
        })
    }

    // ---------------------------------------------------------------------
    fn incorporate_line(&mut self, line: &'a str) {
        self.line = line;
        self.line_number += 1;
        self.offset = 0;
        self.column = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.old_tip = self.tip;

        let mut container = 0usize;
        let mut all_matched = true;

        // 1. match continuation of open blocks
        loop {
            let last_child = match self.nodes[container].children.last() {
                Some(&c) if self.nodes[c].open => c,
                _ => break,
            };
            container = last_child;
            self.find_next_nonspace();
            match self.try_continue(container) {
                0 => {}
                1 => {
                    container = self.nodes[container].parent.unwrap();
                    all_matched = false;
                    break;
                }
                _ => {
                    // line consumed (closing fence)
                    return;
                }
            }
        }
        let _ = all_matched;

        self.all_closed = container == self.old_tip;
        self.last_matched_container = container;

        // 2. table detection: a paragraph followed by a delimiter row
        if self.options.tables && matches!(self.nodes[container].kind, Kind::Paragraph) {
            self.find_next_nonspace();
            if !self.blank && !self.indented {
                let rest = self.rest_from(self.next_nonspace);
                if let Some(alignments) = scan_table_delimiter_row(rest) {
                    let header_line = self.nodes[container].lines.last().cloned();
                    if let Some(header_line) = header_line {
                        let header_cells = split_table_row(&header_line);
                        if header_cells.len() == alignments.len() && header_line.contains('|') {
                            self.close_unmatched_blocks();
                            // remove header line from paragraph
                            self.nodes[container].lines.pop();
                            let parent = self.nodes[container].parent.unwrap();
                            if self.nodes[container].lines.is_empty() {
                                // replace paragraph with table
                                self.nodes[container].kind = Kind::Table {
                                    alignments,
                                    header: header_cells,
                                    rows: Vec::new(),
                                };
                                self.tip = container;
                            } else {
                                self.finalize(container, self.line_number - 1);
                                self.tip = parent;
                                self.add_child(Kind::Table {
                                    alignments,
                                    header: header_cells,
                                    rows: Vec::new(),
                                });
                            }
                            self.offset = self.line.len();
                            return;
                        }
                    }
                }
            }
        }

        // 3. try new block starts
        let mut matched_leaf = !matches!(self.nodes[container].kind, Kind::Paragraph)
            && self.nodes[container].accepts_lines();
        while !matched_leaf {
            self.find_next_nonspace();
            // performance optimization: nothing special on this line
            if !self.indented && !maybe_special(self.rest_from(self.next_nonspace)) {
                self.advance_next_nonspace();
                break;
            }
            match self.try_block_starts(container) {
                1 => {
                    container = self.tip;
                }
                2 => {
                    container = self.tip;
                    matched_leaf = true;
                }
                _ => {
                    self.advance_next_nonspace();
                    break;
                }
            }
        }

        // 4. add text to the appropriate container
        if !self.all_closed && !self.blank && matches!(self.nodes[self.tip].kind, Kind::Paragraph) {
            // lazy paragraph continuation
            self.add_line();
        } else {
            // not a lazy continuation; finalize any blocks not matched
            self.close_unmatched_blocks();
            if self.blank {
                if let Some(&last) = self.nodes[container].children.last() {
                    self.nodes[last].last_line_blank = true;
                }
            }
            let t = &self.nodes[container].kind;
            let last_line_blank = self.blank
                && !(matches!(t, Kind::BlockQuote)
                    || matches!(t, Kind::FencedCode { .. })
                    || (matches!(t, Kind::Item(_))
                        && self.nodes[container].children.is_empty()
                        && self.nodes[container].start_line == self.line_number));
            // propagate last_line_blank up through parents
            let mut cont = Some(container);
            while let Some(c) = cont {
                self.nodes[c].last_line_blank = last_line_blank;
                cont = self.nodes[c].parent;
            }

            if self.nodes[container].accepts_lines() {
                if let Kind::Table { .. } = self.nodes[container].kind {
                    let row_text = self.rest_from(self.offset).to_string();
                    let cells = split_table_row(&row_text);
                    if let Kind::Table { ref mut rows, .. } = self.nodes[container].kind {
                        rows.push(cells);
                    }
                } else {
                    self.tip = container;
                    self.add_line();
                    // if HtmlBlock, check for end condition
                    if let Kind::HtmlBlock { kind } = self.nodes[container].kind {
                        if (1..=5).contains(&kind) {
                            let rest = self.rest_from(self.offset);
                            if html_block_end(kind, rest) {
                                self.finalize(container, self.line_number);
                            }
                        }
                    }
                }
            } else if self.offset < self.line.len() && !self.blank {
                // create paragraph container for line
                self.add_child(Kind::Paragraph);
                self.advance_next_nonspace();
                self.add_line();
            }
        }
    }

    fn finish(&mut self) {
        while self.tip != 0 {
            self.finalize(self.tip, self.line_number);
        }
        self.finalize(0, self.line_number);
    }
}

fn lists_match(a: &ListData, b: &ListData) -> bool {
    a.ordered == b.ordered && a.delimiter == b.delimiter && a.bullet_char == b.bullet_char
}

fn maybe_special(rest: &str) -> bool {
    match rest.as_bytes().first() {
        Some(b'#') | Some(b'`') | Some(b'~') | Some(b'*') | Some(b'+') | Some(b'_') | Some(b'=')
        | Some(b'<') | Some(b'>') | Some(b'-') | Some(b'[') => true,
        Some(b'0'..=b'9') => true,
        _ => false,
    }
}

/// Scan `#{1,6}` followed by space/tab/eol. Returns (level, marker length incl. trailing ws char).
fn scan_atx_heading(rest: &str) -> Option<(u8, usize)> {
    let bytes = rest.as_bytes();
    let n = bytes.iter().take_while(|&&b| b == b'#').count();
    if n == 0 || n > 6 {
        return None;
    }
    match bytes.get(n) {
        None => Some((n as u8, n)),
        Some(b' ') | Some(b'\t') => {
            let mut i = n;
            while is_space_or_tab(bytes.get(i).copied()) {
                i += 1;
            }
            Some((n as u8, i))
        }
        _ => None,
    }
}

fn strip_atx_closing(content: &str) -> &str {
    // remove trailing #s preceded by space (or whole content of #s)
    let trimmed = content.trim_end_matches(|c| c == ' ' || c == '\t');
    let without_hashes = trimmed.trim_end_matches('#');
    if without_hashes.len() == trimmed.len() {
        return trimmed.trim_start_matches(|c| c == ' ' || c == '\t');
    }
    if without_hashes.is_empty() {
        return "";
    }
    if without_hashes.ends_with(' ') || without_hashes.ends_with('\t') {
        without_hashes.trim_matches(|c| c == ' ' || c == '\t')
    } else {
        trimmed.trim_start_matches(|c| c == ' ' || c == '\t')
    }
}

/// Extract a trailing `{...}` heading attribute block.
pub(crate) fn extract_heading_attrs(content: &str) -> (String, Option<String>) {
    let trimmed = content.trim_end_matches(|c| c == ' ' || c == '\t');
    if !trimmed.ends_with('}') {
        return (content.to_string(), None);
    }
    // find the last '{' that is not inside... simply the last '{'
    if let Some(open) = trimmed.rfind('{') {
        let inner = &trimmed[open + 1..trimmed.len() - 1];
        if inner.contains('{') || inner.contains('}') || inner.contains('\n') {
            return (content.to_string(), None);
        }
        let before = trimmed[..open].trim_end_matches(|c| c == ' ' || c == '\t');
        return (before.to_string(), Some(inner.to_string()));
    }
    (content.to_string(), None)
}

fn scan_fence_open(rest: &str) -> Option<(u8, usize)> {
    let bytes = rest.as_bytes();
    let c = *bytes.first()?;
    if c != b'`' && c != b'~' {
        return None;
    }
    let n = bytes.iter().take_while(|&&b| b == c).count();
    if n < 3 {
        return None;
    }
    if c == b'`' && rest[n..].contains('`') {
        return None;
    }
    Some((c, n))
}

fn scan_setext_underline(rest: &str) -> Option<u8> {
    let bytes = rest.as_bytes();
    let c = *bytes.first()?;
    if c != b'=' && c != b'-' {
        return None;
    }
    let n = bytes.iter().take_while(|&&b| b == c).count();
    if rest[n..].trim_matches(|ch| ch == ' ' || ch == '\t').is_empty() {
        Some(if c == b'=' { 1 } else { 2 })
    } else {
        None
    }
}

fn scan_thematic_break(rest: &str) -> bool {
    let bytes = rest.as_bytes();
    let c = match bytes.first() {
        Some(&c @ (b'*' | b'-' | b'_')) => c,
        _ => return false,
    };
    let mut count = 0;
    for &b in bytes {
        if b == c {
            count += 1;
        } else if b == b' ' || b == b'\t' {
        } else if b == b'\n' || b == b'\r' {
            break;
        } else {
            return false;
        }
    }
    count >= 3
}

/// Scan `[^label]:` at the start of `rest`. Returns (label, length consumed).
fn scan_footnote_def(rest: &str) -> Option<(String, usize)> {
    let bytes = rest.as_bytes();
    if !rest.starts_with("[^") {
        return None;
    }
    let mut i = 2;
    while i < bytes.len() {
        match bytes[i] {
            b']' => break,
            b'[' | b'\n' | b'\r' => return None,
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
            _ => i += 1,
        }
    }
    if i >= bytes.len() || i == 2 {
        return None;
    }
    if bytes.get(i + 1) != Some(&b':') {
        return None;
    }
    let label = &rest[2..i];
    if label.trim().is_empty() || label.len() > 999 {
        return None;
    }
    Some((label.to_string(), i + 2))
}

/// HTML block start detection. Returns the block kind (1-7).
fn scan_html_block_start(rest: &str, in_paragraph: bool) -> Option<u8> {
    let bytes = rest.as_bytes();
    if bytes.first() != Some(&b'<') {
        return None;
    }
    let lower = rest.to_ascii_lowercase();
    // kind 1
    for tag in ["<script", "<pre", "<style", "<textarea"] {
        if lower.starts_with(tag) {
            match lower.as_bytes().get(tag.len()) {
                None | Some(b' ') | Some(b'\t') | Some(b'>') | Some(b'\n') | Some(b'\r') => return Some(1),
                _ => {}
            }
        }
    }
    if rest.starts_with("<!--") {
        return Some(2);
    }
    if rest.starts_with("<?") {
        return Some(3);
    }
    if rest.starts_with("<![CDATA[") {
        return Some(5);
    }
    if rest.starts_with("<!") && bytes.len() > 2 && bytes[2].is_ascii_alphabetic() {
        return Some(4);
    }
    // kind 6
    {
        let mut i = 1;
        if bytes.get(1) == Some(&b'/') {
            i = 2;
        }
        if let Some(n) = scan::scan_tag_name(&bytes[i..]) {
            let name = lower[i..i + n].to_string();
            if scan::BLOCK_TAGS.contains(&name.as_str()) {
                match bytes.get(i + n) {
                    None | Some(b' ') | Some(b'\t') | Some(b'>') | Some(b'\n') | Some(b'\r') => return Some(6),
                    Some(b'/') if bytes.get(i + n + 1) == Some(&b'>') => return Some(6),
                    _ => {}
                }
            }
        }
    }
    // kind 7: complete open or closing tag followed only by whitespace
    if !in_paragraph {
        let tag_len = if bytes.get(1) == Some(&b'/') {
            scan::scan_html_closing_tag(bytes)
        } else {
            // must not be script/style/pre/textarea
            let name_len = scan::scan_tag_name(&bytes[1..])?;
            let name = lower[1..1 + name_len].to_string();
            if matches!(name.as_str(), "script" | "style" | "pre" | "textarea") {
                return None;
            }
            scan_open_tag_single_line(bytes)
        };
        if let Some(len) = tag_len {
            if rest[len..].trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty() {
                return Some(7);
            }
        }
    }
    None
}

/// Like scan_html_open_tag but attribute values can't span lines (single line context).
fn scan_open_tag_single_line(s: &[u8]) -> Option<usize> {
    let n = scan::scan_html_open_tag(s)?;
    if s[..n].contains(&b'\n') {
        return None;
    }
    Some(n)
}

fn html_block_end(kind: u8, line: &str) -> bool {
    match kind {
        1 => {
            let lower = line.to_ascii_lowercase();
            lower.contains("</script>") || lower.contains("</pre>") || lower.contains("</style>") || lower.contains("</textarea>")
        }
        2 => line.contains("-->"),
        3 => line.contains("?>"),
        4 => line.contains('>'),
        5 => line.contains("]]>"),
        _ => false,
    }
}

/// Parse a GFM table delimiter row. Returns alignments if valid.
fn scan_table_delimiter_row(line: &str) -> Option<Vec<Alignment>> {
    let trimmed = line.trim_matches(|c| c == ' ' | c == '\t' || c == '\n' || c == '\r');
    if trimmed.is_empty() {
        return None;
    }
    if !trimmed.contains('-') {
        return None;
    }
    let mut cells = split_table_row(trimmed);
    if cells.is_empty() {
        return None;
    }
    // A delimiter row must contain a pipe or be more than one cell... (a lone "---" is a setext/hr)
    if !trimmed.contains('|') {
        return None;
    }
    let mut alignments = Vec::new();
    for cell in cells.drain(..) {
        let c = cell.trim();
        if c.is_empty() {
            return None;
        }
        let bytes = c.as_bytes();
        let left = bytes[0] == b':';
        let right = bytes[bytes.len() - 1] == b':';
        let inner = &c[if left { 1 } else { 0 }..c.len() - if right { 1 } else { 0 }];
        if inner.is_empty() || !inner.bytes().all(|b| b == b'-') {
            return None;
        }
        alignments.push(match (left, right) {
            (true, true) => Alignment::Center,
            (true, false) => Alignment::Left,
            (false, true) => Alignment::Right,
            (false, false) => Alignment::None,
        });
    }
    Some(alignments)
}

/// Split a table row into cells (handling `\|` escapes). Leading/trailing pipes removed.
pub(crate) fn split_table_row(line: &str) -> Vec<String> {
    let line = line.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    let bytes = line.as_bytes();
    let mut start = 0;
    let mut end = bytes.len();
    if bytes.first() == Some(&b'|') {
        start = 1;
    }
    if end > start && bytes[end - 1] == b'|' && !(end >= 2 && bytes[end - 2] == b'\\') {
        end -= 1;
    }
    let inner = &line[start..end];
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut chars = inner.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if chars.peek() == Some(&'|') {
                cur.push('|');
                chars.next();
                continue;
            }
            cur.push('\\');
        } else if c == '|' {
            cells.push(cur.trim().to_string());
            cur = String::new();
        } else {
            cur.push(c);
        }
    }
    cells.push(cur.trim().to_string());
    if cells.len() == 1 && cells[0].is_empty() && inner.trim().is_empty() {
        return Vec::new();
    }
    cells
}

/// Parse a link reference definition at the start of `s`. Returns (label, def, bytes consumed).
pub(crate) fn parse_reference_definition(s: &str) -> Option<(String, LinkDef, usize)> {
    let (label, mut i) = scan::scan_link_label(s)?;
    if s.as_bytes().get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    // skip whitespace including up to one newline
    i = skip_spaces_one_newline(s, i)?;
    let (dest, dlen) = scan::scan_link_destination(&s[i..])?;
    if dlen == 0 && !s[i..].starts_with("<>") {
        return None;
    }
    i += dlen;
    let before_title = i;
    // optional title
    let mut title = None;
    let j = skip_spaces_one_newline_opt(s, i);
    let had_ws = j > i;
    if had_ws {
        if let Some((t, tlen)) = scan::scan_link_title(&s[j..]) {
            // after the title there must be only whitespace till end of line
            let k = j + tlen;
            let rest_line_end = s[k..].find('\n').map(|p| k + p).unwrap_or(s.len());
            if s[k..rest_line_end].trim().is_empty() {
                title = Some(t);
                i = rest_line_end;
                let consumed = if i < s.len() { i + 1 } else { i };
                return Some((label, LinkDef { dest, title }, consumed));
            }
        }
    }
    // no valid title: the rest of the line after dest must be blank
    let line_end = s[before_title..].find('\n').map(|p| before_title + p).unwrap_or(s.len());
    if !s[before_title..line_end].trim().is_empty() {
        return None;
    }
    let consumed = if line_end < s.len() { line_end + 1 } else { line_end };
    Some((label, LinkDef { dest, title }, consumed))
}

fn skip_spaces_one_newline(s: &str, mut i: usize) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut newlines = 0;
    while i < bytes.len() {
        match bytes[i] {
            b' ' | b'\t' => i += 1,
            b'\n' => {
                newlines += 1;
                if newlines > 1 {
                    return None;
                }
                i += 1;
            }
            _ => break,
        }
    }
    Some(i)
}

fn skip_spaces_one_newline_opt(s: &str, mut i: usize) -> usize {
    let bytes = s.as_bytes();
    let mut newlines = 0;
    while i < bytes.len() {
        match bytes[i] {
            b' ' | b'\t' => i += 1,
            b'\n' => {
                newlines += 1;
                if newlines > 1 {
                    return i;
                }
                i += 1;
            }
            _ => break,
        }
    }
    i
}

// -------------------------------------------------------------------------
// Event generation

pub fn parse_document(text: &str, options: Options) -> Vec<Event> {
    let mut parser = BlockParser::new(options);
    let normalized: String;
    let text = if text.contains('\r') {
        normalized = text.replace("\r\n", "\n").replace('\r', "\n");
        &normalized
    } else {
        text
    };
    // Replace NUL characters
    let text_owned: String;
    let text = if text.contains('\0') {
        text_owned = text.replace('\0', "\u{FFFD}");
        &text_owned
    } else {
        text
    };
    let mut lines: Vec<&str> = text.split('\n').collect();
    // if text ends with newline, the last empty piece is not a line
    if text.ends_with('\n') {
        lines.pop();
    }
    for line in lines {
        parser.incorporate_line(line);
    }
    parser.finish();

    let mut events = Vec::new();
    let ctx = InlineContext {
        refmap: &parser.refmap,
        footnote_labels: &parser.footnote_labels,
        options,
    };
    emit_children(&parser.nodes, 0, &ctx, &mut events, false);
    events
}

fn emit_children(nodes: &[Node], idx: usize, ctx: &InlineContext, events: &mut Vec<Event>, tight: bool) {
    for &child in &nodes[idx].children {
        emit_node(nodes, child, ctx, events, tight);
    }
}

fn emit_node(nodes: &[Node], idx: usize, ctx: &InlineContext, events: &mut Vec<Event>, tight: bool) {
    let node = &nodes[idx];
    match &node.kind {
        Kind::Document => emit_children(nodes, idx, ctx, events, false),
        Kind::BlockQuote => {
            events.push(Event::Start(Tag::BlockQuote));
            emit_children(nodes, idx, ctx, events, false);
            events.push(Event::End(TagEnd::BlockQuote));
        }
        Kind::List(data) => {
            let start = if data.ordered { Some(data.start) } else { None };
            events.push(Event::Start(Tag::List(start)));
            for &child in &node.children {
                emit_node(nodes, child, ctx, events, data.tight);
            }
            events.push(Event::End(TagEnd::List(data.ordered)));
        }
        Kind::Item(_) => {
            events.push(Event::Start(Tag::Item));
            let mut first = true;
            for &child in &node.children {
                let cnode = &nodes[child];
                if tight && matches!(cnode.kind, Kind::Paragraph) {
                    // tight list: paragraph contents inline without <p>
                    let text = cnode.lines.join("\n");
                    parse_inlines(&text, ctx, events, first && ctx.options.tasklists);
                } else {
                    emit_node(nodes, child, ctx, events, false);
                }
                first = false;
            }
            events.push(Event::End(TagEnd::Item));
        }
        Kind::FootnoteDef { label } => {
            events.push(Event::Start(Tag::FootnoteDefinition(label.clone())));
            emit_children(nodes, idx, ctx, events, false);
            events.push(Event::End(TagEnd::FootnoteDefinition));
        }
        Kind::Paragraph => {
            let text = node.lines.join("\n");
            events.push(Event::Start(Tag::Paragraph));
            parse_inlines(&text, ctx, events, false);
            events.push(Event::End(TagEnd::Paragraph));
        }
        Kind::Heading { level, .. } => {
            let text = node.lines.join("\n");
            let (id, classes, attrs) = match &node.attr_block {
                Some(block) => parse_heading_attr_block(block),
                None => (None, Vec::new(), Vec::new()),
            };
            let level = HeadingLevel::from_u8(*level);
            events.push(Event::Start(Tag::Heading {
                level,
                id,
                classes,
                attrs,
            }));
            parse_inlines(text.trim(), ctx, events, false);
            events.push(Event::End(TagEnd::Heading(level)));
        }
        Kind::ThematicBreak => events.push(Event::Rule),
        Kind::IndentedCode => {
            let mut content = String::new();
            for l in &node.lines {
                content.push_str(l);
                content.push('\n');
            }
            events.push(Event::Start(Tag::CodeBlock(CodeBlockKind::Indented)));
            events.push(Event::Text(content));
            events.push(Event::End(TagEnd::CodeBlock));
        }
        Kind::FencedCode { .. } => {
            let mut content = String::new();
            for l in &node.lines {
                content.push_str(l);
                content.push('\n');
            }
            events.push(Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(node.info.clone()))));
            if !content.is_empty() {
                events.push(Event::Text(content));
            }
            events.push(Event::End(TagEnd::CodeBlock));
        }
        Kind::HtmlBlock { .. } => {
            events.push(Event::Start(Tag::HtmlBlock));
            for l in &node.lines {
                let mut s = l.clone();
                s.push('\n');
                events.push(Event::Html(s));
            }
            events.push(Event::End(TagEnd::HtmlBlock));
        }
        Kind::Table {
            alignments,
            header,
            rows,
        } => {
            let ncols = alignments.len();
            events.push(Event::Start(Tag::Table(alignments.clone())));
            events.push(Event::Start(Tag::TableHead));
            for i in 0..ncols {
                events.push(Event::Start(Tag::TableCell));
                if let Some(cell) = header.get(i) {
                    parse_inlines(cell, ctx, events, false);
                }
                events.push(Event::End(TagEnd::TableCell));
            }
            events.push(Event::End(TagEnd::TableHead));
            for row in rows {
                events.push(Event::Start(Tag::TableRow));
                for i in 0..ncols {
                    events.push(Event::Start(Tag::TableCell));
                    if let Some(cell) = row.get(i) {
                        parse_inlines(cell, ctx, events, false);
                    }
                    events.push(Event::End(TagEnd::TableCell));
                }
                events.push(Event::End(TagEnd::TableRow));
            }
            events.push(Event::End(TagEnd::Table));
        }
    }
}

fn parse_heading_attr_block(block: &str) -> (Option<String>, Vec<String>, Vec<(String, Option<String>)>) {
    let mut id = None;
    let mut classes = Vec::new();
    let mut attrs = Vec::new();
    for attr in block.split_ascii_whitespace() {
        if attr.len() > 1 {
            let first = attr.as_bytes()[0];
            if first == b'#' {
                id = Some(attr[1..].to_string());
            } else if first == b'.' {
                classes.push(attr[1..].to_string());
            } else if let Some((k, v)) = attr.split_once('=') {
                attrs.push((k.to_string(), Some(v.to_string())));
            } else {
                attrs.push((attr.to_string(), None));
            }
        }
    }
    (id, classes, attrs)
}
