//! Inline parser: emphasis, links, code spans, raw HTML, entities, etc.

use super::scan::{self, is_punctuation, is_unicode_whitespace, parse_entity};
use super::*;
use std::collections::HashSet;

pub struct InlineContext<'a> {
    pub refmap: &'a RefMap,
    pub footnote_labels: &'a HashSet<String>,
    pub options: Options,
}

#[derive(Debug, Clone)]
enum Item {
    Ev(Event),
    Delim {
        ch: u8,
        count: usize,
        orig_count: usize,
        can_open: bool,
        can_close: bool,
    },
    Bracket {
        image: bool,
        active: bool,
        /// byte offset in the source right after the bracket
        src_pos: usize,
    },
}

/// Parse inline content and append events.
pub fn parse_inlines(text: &str, ctx: &InlineContext, events: &mut Vec<Event>, allow_task: bool) {
    let mut p = InlineParser {
        text,
        ctx,
        items: Vec::new(),
        bracket_stack: Vec::new(),
    };
    p.run(allow_task);
    let mut items = p.items;
    process_emphasis(&mut items, 0);
    flush_items(items, events);
}

fn flush_items(items: Vec<Item>, events: &mut Vec<Event>) {
    let mut pending_text = String::new();
    for item in items {
        match item {
            Item::Ev(Event::Text(t)) => pending_text.push_str(&t),
            Item::Ev(ev) => {
                if !pending_text.is_empty() {
                    events.push(Event::Text(std::mem::take(&mut pending_text)));
                }
                events.push(ev);
            }
            Item::Delim { ch, count, .. } => {
                pending_text.push_str(&delim_text(ch, count));
            }
            Item::Bracket { image, .. } => {
                pending_text.push_str(if image { "![" } else { "[" });
            }
        }
    }
    if !pending_text.is_empty() {
        events.push(Event::Text(pending_text));
    }
}

fn delim_text(ch: u8, count: usize) -> String {
    match ch {
        b'"' => "\u{201C}".repeat(count),
        b'\'' => "\u{2019}".repeat(count),
        _ => std::iter::repeat(ch as char).take(count).collect(),
    }
}

struct InlineParser<'a, 'b> {
    text: &'a str,
    ctx: &'b InlineContext<'b>,
    items: Vec<Item>,
    bracket_stack: Vec<usize>,
}

impl<'a, 'b> InlineParser<'a, 'b> {
    fn push_text(&mut self, s: &str) {
        if s.is_empty() {
            return;
        }
        if let Some(Item::Ev(Event::Text(t))) = self.items.last_mut() {
            t.push_str(s);
        } else {
            self.items.push(Item::Ev(Event::Text(s.to_string())));
        }
    }

    fn run(&mut self, allow_task: bool) {
        let text = self.text;
        let bytes = text.as_bytes();
        let mut i = 0;

        // Task list marker at the very start.
        if allow_task {
            let b = bytes;
            if b.len() >= 3 && b[0] == b'[' && b[2] == b']' && (b[1] == b' ' || b[1] == b'x' || b[1] == b'X') {
                let after = b.get(3).copied();
                if after.is_none() || after == Some(b' ') || after == Some(b'\t') || after == Some(b'\n') {
                    if after.is_some() {
                        self.items.push(Item::Ev(Event::TaskListMarker(b[1] != b' ')));
                        i = 3;
                        // skip following whitespace
                        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
                            i += 1;
                        }
                    }
                }
            }
        }

        let mut text_start = i;
        while i < bytes.len() {
            let c = bytes[i];
            match c {
                b'\\' => {
                    self.push_text(&text[text_start..i]);
                    if i + 1 < bytes.len() {
                        let n = bytes[i + 1];
                        if n == b'\n' {
                            self.items.push(Item::Ev(Event::HardBreak));
                            i += 2;
                            i = self.skip_line_start_ws(i);
                            text_start = i;
                            continue;
                        } else if n.is_ascii_punctuation() {
                            self.push_text(&text[i + 1..i + 2]);
                            i += 2;
                            text_start = i;
                            continue;
                        }
                    }
                    self.push_text("\\");
                    i += 1;
                    text_start = i;
                }
                b'\n' => {
                    // trailing spaces before newline?
                    let seg = &text[text_start..i];
                    let trimmed = seg.trim_end_matches(' ');
                    let nspaces = seg.len() - trimmed.len();
                    self.push_text(trimmed);
                    if nspaces >= 2 {
                        self.items.push(Item::Ev(Event::HardBreak));
                    } else {
                        self.items.push(Item::Ev(Event::SoftBreak));
                    }
                    i += 1;
                    i = self.skip_line_start_ws(i);
                    text_start = i;
                }
                b'`' => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == b'`').count();
                    // find closing run of exactly n backticks
                    let mut j = i + n;
                    let mut found = None;
                    while j < bytes.len() {
                        if bytes[j] == b'`' {
                            let m = bytes[j..].iter().take_while(|&&b| b == b'`').count();
                            if m == n {
                                found = Some(j);
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                    match found {
                        Some(close) => {
                            let inner = &text[i + n..close];
                            let mut content = inner.replace('\n', " ");
                            if content.len() >= 2
                                && content.starts_with(' ')
                                && content.ends_with(' ')
                                && !content.trim().is_empty()
                            {
                                content = content[1..content.len() - 1].to_string();
                            }
                            self.items.push(Item::Ev(Event::Code(content)));
                            i = close + n;
                        }
                        None => {
                            self.push_text(&text[i..i + n]);
                            i += n;
                        }
                    }
                    text_start = i;
                }
                b'*' | b'_' => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == c).count();
                    let (can_open, can_close) = self.flanking(i, n, c == b'_');
                    self.items.push(Item::Delim {
                        ch: c,
                        count: n,
                        orig_count: n,
                        can_open,
                        can_close,
                    });
                    i += n;
                    text_start = i;
                }
                b'~' if self.ctx.options.strikethrough => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == b'~').count();
                    if n <= 2 {
                        let (can_open, can_close) = self.flanking(i, n, false);
                        self.items.push(Item::Delim {
                            ch: b'~',
                            count: n,
                            orig_count: n,
                            can_open,
                            can_close,
                        });
                    } else {
                        self.push_text(&text[i..i + n]);
                    }
                    i += n;
                    text_start = i;
                }
                b'"' | b'\'' if self.ctx.options.smart_punctuation => {
                    self.push_text(&text[text_start..i]);
                    let (can_open, can_close) = self.flanking(i, 1, true);
                    self.items.push(Item::Delim {
                        ch: c,
                        count: 1,
                        orig_count: 1,
                        can_open,
                        can_close,
                    });
                    i += 1;
                    text_start = i;
                }
