//! Inline parser: emphasis, links, code spans, raw HTML, entities, etc.

use super::scan::{self, is_punctuation, is_unicode_whitespace, parse_entity};
use super::*;
use std::collections::HashSet;

pub struct InlineContext<'a> {
    pub refmap: &'a RefMap,
    pub footnote_labels: &'a HashSet<String>,
    pub options: Options,
}

#[derive(Debug, Clone)]
enum Item {
    Ev(Event),
    Delim {
        ch: u8,
        count: usize,
        orig_count: usize,
        can_open: bool,
        can_close: bool,
    },
    Bracket {
        image: bool,
        active: bool,
        /// byte offset in the source right after the bracket
        src_pos: usize,
    },
}

/// Parse inline content and append events.
pub fn parse_inlines(text: &str, ctx: &InlineContext, events: &mut Vec<Event>, allow_task: bool) {
    let mut p = InlineParser {
        text,
        ctx,
        items: Vec::new(),
        bracket_stack: Vec::new(),
    };
    p.run(allow_task);
    let mut items = p.items;
    process_emphasis(&mut items, 0);
    flush_items(items, events);
}

fn flush_items(items: Vec<Item>, events: &mut Vec<Event>) {
    let mut pending_text = String::new();
    for item in items {
        match item {
            Item::Ev(Event::Text(t)) => pending_text.push_str(&t),
            Item::Ev(ev) => {
                if !pending_text.is_empty() {
                    events.push(Event::Text(std::mem::take(&mut pending_text)));
                }
                events.push(ev);
            }
            Item::Delim { ch, count, .. } => {
                pending_text.push_str(&delim_text(ch, count));
            }
            Item::Bracket { image, .. } => {
                pending_text.push_str(if image { "![" } else { "[" });
            }
        }
    }
    if !pending_text.is_empty() {
        events.push(Event::Text(pending_text));
    }
}

fn delim_text(ch: u8, count: usize) -> String {
    match ch {
        b'"' => "\u{201C}".repeat(count),
        b'\'' => "\u{2019}".repeat(count),
        _ => std::iter::repeat(ch as char).take(count).collect(),
    }
}

struct InlineParser<'a, 'b> {
    text: &'a str,
    ctx: &'b InlineContext<'b>,
    items: Vec<Item>,
    bracket_stack: Vec<usize>,
}

impl<'a, 'b> InlineParser<'a, 'b> {
    fn push_text(&mut self, s: &str) {
        if s.is_empty() {
            return;
        }
        if let Some(Item::Ev(Event::Text(t))) = self.items.last_mut() {
            t.push_str(s);
        } else {
            self.items.push(Item::Ev(Event::Text(s.to_string())));
        }
    }

    fn run(&mut self, allow_task: bool) {
        let text = self.text;
        let bytes = text.as_bytes();
        let mut i = 0;

        // Task list marker at the very start.
        if allow_task {
            let b = bytes;
            if b.len() >= 3 && b[0] == b'[' && b[2] == b']' && (b[1] == b' ' || b[1] == b'x' || b[1] == b'X') {
                let after = b.get(3).copied();
                if after.is_none() || after == Some(b' ') || after == Some(b'\t') || after == Some(b'\n') {
                    if after.is_some() {
                        self.items.push(Item::Ev(Event::TaskListMarker(b[1] != b' ')));
                        i = 3;
                        // skip following whitespace
                        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
                            i += 1;
                        }
                    }
                }
            }
        }

        let mut text_start = i;
        while i < bytes.len() {
            let c = bytes[i];
            match c {
                b'\\' => {
                    self.push_text(&text[text_start..i]);
                    if i + 1 < bytes.len() {
                        let n = bytes[i + 1];
                        if n == b'\n' {
                            self.items.push(Item::Ev(Event::HardBreak));
                            i += 2;
                            i = self.skip_line_start_ws(i);
                            text_start = i;
                            continue;
                        } else if n.is_ascii_punctuation() {
                            self.push_text(&text[i + 1..i + 2]);
                            i += 2;
                            text_start = i;
                            continue;
                        }
                    }
                    self.push_text("\\");
                    i += 1;
                    text_start = i;
                }
                b'\n' => {
                    // trailing spaces before newline?
                    let seg = &text[text_start..i];
                    let trimmed = seg.trim_end_matches(' ');
                    let nspaces = seg.len() - trimmed.len();
                    self.push_text(trimmed);
                    if nspaces >= 2 {
                        self.items.push(Item::Ev(Event::HardBreak));
                    } else {
                        self.items.push(Item::Ev(Event::SoftBreak));
                    }
                    i += 1;
                    i = self.skip_line_start_ws(i);
                    text_start = i;
                }
                b'`' => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == b'`').count();
                    // find closing run of exactly n backticks
                    let mut j = i + n;
                    let mut found = None;
                    while j < bytes.len() {
                        if bytes[j] == b'`' {
                            let m = bytes[j..].iter().take_while(|&&b| b == b'`').count();
                            if m == n {
                                found = Some(j);
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                    match found {
                        Some(close) => {
                            let inner = &text[i + n..close];
                            let mut content = inner.replace('\n', " ");
                            if content.len() >= 2
                                && content.starts_with(' ')
                                && content.ends_with(' ')
                                && !content.trim().is_empty()
                            {
                                content = content[1..content.len() - 1].to_string();
                            }
                            self.items.push(Item::Ev(Event::Code(content)));
                            i = close + n;
                        }
                        None => {
                            self.push_text(&text[i..i + n]);
                            i += n;
                        }
                    }
                    text_start = i;
                }
                b'*' | b'_' => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == c).count();
                    let (can_open, can_close) = self.flanking(i, n, c == b'_');
                    self.items.push(Item::Delim {
                        ch: c,
                        count: n,
                        orig_count: n,
                        can_open,
                        can_close,
                    });
                    i += n;
                    text_start = i;
                }
                b'~' if self.ctx.options.strikethrough => {
                    self.push_text(&text[text_start..i]);
                    let n = bytes[i..].iter().take_while(|&&b| b == b'~').count();
                    if n <= 2 {
                        let (can_open, can_close) = self.flanking(i, n, false);
                        self.items.push(Item::Delim {
                            ch: b'~',
                            count: n,
                            orig_count: n,
                            can_open,
                            can_close,
                        });
                    } else {
                        self.push_text(&text[i..i + n]);
                    }
                    i += n;
                    text_start = i;
                }
                b'"' | b'\'' if self.ctx.options.smart_punctuation => {
                    self.push_text(&text[text_start..i]);
                    let (can_open, can_close) = self.flanking(i, 1, true);
                    self.items.push(Item::Delim {
                        ch: c,
                        count: 1,
                        orig_count: 1,
                        can_open,
                        can_close,
                    });
                    i += 1;
                    text_start = i;
                }
                b'-' if self.ctx.options.smart_punctuation => {
                    let n = bytes[i..].iter().take_while(|&&b| b == b'-').count();
                    if n >= 2 {
                        self.push_text(&text[text_start..i]);
                        let (ens, ems) = if n % 3 == 0 {
                            (0, n / 3)
                        } else if n % 2 == 0 {
                            (n / 2, 0)
                        } else if n % 3 == 2 {
                            (1, (n - 2) / 3)
                        } else {
                            (2, (n - 4) / 3)
                        };
                        let mut s = String::new();
                        for _ in 0..ems {
                            s.push('\u{2014}');
                        }
                        for _ in 0..ens {
                            s.push('\u{2013}');
                        }
                        self.push_text(&s);
                        i += n;
                        text_start = i;
                    } else {
                        i += 1;
                    }
                }
                b'.' if self.ctx.options.smart_punctuation && text[i..].starts_with("...") => {
                    self.push_text(&text[text_start..i]);
                    self.push_text("\u{2026}");
                    i += 3;
                    text_start = i;
                }
                b'&' => {
                    if let Some((decoded, len)) = parse_entity(&text[i..]) {
                        self.push_text(&text[text_start..i]);
                        self.push_text(&decoded);
                        i += len;
                        text_start = i;
                    } else {
                        i += 1;
                    }
                }
                b'<' => {
                    if let Some((len, url, is_email)) = scan::scan_autolink(&text[i..]) {
                        self.push_text(&text[text_start..i]);
                        let dest = if is_email { format!("mailto:{url}") } else { url.clone() };
                        let _ = dest;
                        self.items.push(Item::Ev(Event::Start(Tag::Link {
                            link_type: if is_email { LinkType::Email } else { LinkType::Autolink },
                            dest_url: url.clone(),
                            title: String::new(),
                            id: String::new(),
                        })));
                        self.items.push(Item::Ev(Event::Text(url)));
                        self.items.push(Item::Ev(Event::End(TagEnd::Link)));
                        i += len;
                        text_start = i;
                    } else if let Some(len) = scan::scan_inline_html(&bytes[i..]) {
                        self.push_text(&text[text_start..i]);
                        self.items.push(Item::Ev(Event::InlineHtml(text[i..i + len].to_string())));
                        i += len;
                        text_start = i;
                    } else {
                        i += 1;
                    }
                }
                b'!' if bytes.get(i + 1) == Some(&b'[') => {
                    self.push_text(&text[text_start..i]);
                    self.items.push(Item::Bracket {
                        image: true,
                        active: true,
                        src_pos: i + 2,
                    });
                    self.bracket_stack.push(self.items.len() - 1);
                    i += 2;
                    text_start = i;
                }
                b'[' => {
                    self.push_text(&text[text_start..i]);
                    // footnote reference?
                    if self.ctx.options.footnotes && bytes.get(i + 1) == Some(&b'^') {
                        if let Some((label, len)) = scan_footnote_ref(&text[i..]) {
                            if self.ctx.footnote_labels.contains(&label) {
                                self.items.push(Item::Ev(Event::FootnoteReference(label)));
                                i += len;
                                text_start = i;
                                continue;
                            }
                        }
                    }
                    self.items.push(Item::Bracket {
                        image: false,
                        active: true,
                        src_pos: i + 1,
                    });
                    self.bracket_stack.push(self.items.len() - 1);
                    i += 1;
                    text_start = i;
                }
                b']' => {
                    self.push_text(&text[text_start..i]);
                    i = self.handle_close_bracket(i);
                    text_start = i;
                }
                _ => {
                    i += 1;
                }
            }
        }
        // trailing text (strip trailing spaces at end of paragraph)
        let seg = &text[text_start..];
        self.push_text(seg.trim_end_matches(|c| c == ' ' || c == '\t'));
    }

    fn skip_line_start_ws(&self, mut i: usize) -> usize {
        let bytes = self.text.as_bytes();
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
            i += 1;
        }
        i
    }

    /// Compute (can_open, can_close) for a delimiter run at byte `pos` of length `n`.
    fn flanking(&self, pos: usize, n: usize, underscore_rules: bool) -> (bool, bool) {
        let before = self.text[..pos].chars().next_back();
        let after = self.text[pos + n..].chars().next();
        let before_ws = before.map_or(true, is_unicode_whitespace);
        let after_ws = after.map_or(true, is_unicode_whitespace);
        let before_punct = before.map_or(false, is_punctuation);
        let after_punct = after.map_or(false, is_punctuation);

        let left_flanking = !after_ws && (!after_punct || before_ws || before_punct);
        let right_flanking = !before_ws && (!before_punct || after_ws || after_punct);

        if underscore_rules {
            let can_open = left_flanking && (!right_flanking || before_punct);
            let can_close = right_flanking && (!left_flanking || after_punct);
            (can_open, can_close)
        } else {
            (left_flanking, right_flanking)
        }
    }

    /// Handle a `]` at byte position `pos`. Returns the new position.
    fn handle_close_bracket(&mut self, pos: usize) -> usize {
        let text = self.text;
        let bytes = text.as_bytes();
        let opener_item = match self.bracket_stack.pop() {
            Some(o) => o,
            None => {
                self.push_text("]");
                return pos + 1;
            }
        };
        let (image, active, src_pos) = match &self.items[opener_item] {
            Item::Bracket {
                image,
                active,
                src_pos,
            } => (*image, *active, *src_pos),
            _ => unreachable!(),
        };
        if !active {
            self.items[opener_item] = Item::Ev(Event::Text(if image { "![".into() } else { "[".into() }));
            self.push_text("]");
            return pos + 1;
        }

        let raw_label = &text[src_pos..pos];
        let mut link: Option<(LinkType, String, String, String, usize)> = None; // type, dest, title, id, end pos

        // Inline link?
        if bytes.get(pos + 1) == Some(&b'(') {
            if let Some((dest, title, end)) = scan_inline_link(text, pos + 2) {
                link = Some((LinkType::Inline, dest, title, String::new(), end));
            }
        }
        if link.is_none() {
            // Reference link?
            let mut end = pos + 1;
            let mut label: Option<String> = None;
            let mut link_type = LinkType::Shortcut;
            if bytes.get(pos + 1) == Some(&b'[') {
                if let Some((lbl, len)) = scan::scan_link_label(&text[pos + 1..]) {
                    label = Some(lbl);
                    end = pos + 1 + len;
                    link_type = LinkType::Reference;
                } else if text[pos + 1..].starts_with("[]") {
                    end = pos + 3;
                    link_type = LinkType::Collapsed;
                }
            }
            if label.is_none() && (link_type == LinkType::Collapsed || link_type == LinkType::Shortcut) {
                // use raw label; must be a valid label
                if raw_label.len() <= 999 && !raw_label.trim().is_empty() && valid_shortcut_label(raw_label) {
                    label = Some(raw_label.to_string());
                }
            }
            if let Some(lbl) = label {
                let key = normalize_label(&lbl);
                if let Some(def) = self.ctx.refmap.get(&key) {
                    link = Some((
                        link_type,
                        def.dest.clone(),
                        def.title.clone().unwrap_or_default(),
                        lbl.clone(),
                        end,
                    ));
                }
            }
        }

        match link {
            Some((link_type, dest, title, id, end)) => {
                let tag = if image {
                    Tag::Image {
                        link_type,
                        dest_url: dest,
                        title,
                        id,
                    }
                } else {
                    Tag::Link {
                        link_type,
                        dest_url: dest,
                        title,
                        id,
                    }
                };
                self.items[opener_item] = Item::Ev(Event::Start(tag.clone()));
                // process emphasis inside the link
                let mut inner: Vec<Item> = self.items.drain(opener_item + 1..).collect();
                process_emphasis(&mut inner, 0);
                self.items.extend(inner);
                self.items.push(Item::Ev(Event::End(tag.to_end())));
                if !image {
                    // deactivate earlier link openers
                    for &b in &self.bracket_stack {
                        if let Item::Bracket { image: false, active, .. } = &mut self.items[b] {
                            *active = false;
                        }
                    }
                }
                end
            }
            None => {
                self.items[opener_item] = Item::Ev(Event::Text(if image { "![".into() } else { "[".into() }));
                self.push_text("]");
                pos + 1
            }
        }
    }
}

fn valid_shortcut_label(raw: &str) -> bool {
    // no unescaped brackets
    let bytes = raw.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
            b'[' | b']' => return false,
            _ => i += 1,
        }
    }
    true
}

/// Scan `^label]` style footnote reference at text starting with `[^`. Returns (label, len).
fn scan_footnote_ref(s: &str) -> Option<(String, usize)> {
    let bytes = s.as_bytes();
    let mut i = 2;
    while i < bytes.len() {
        match bytes[i] {
            b']' => {
                let label = &s[2..i];
                if label.is_empty() {
                    return None;
                }
                return Some((label.to_string(), i + 1));
            }
            b'[' | b'\n' => return None,
            b'\\' if i + 1 < bytes.len() && bytes[i + 1].is_ascii_punctuation() => i += 2,
            _ => i += 1,
        }
    }
    None
}

/// Scan the `(dest "title")` part of an inline link starting at `start` (just after `(`).
/// Returns (dest, title, position after `)`).
fn scan_inline_link(text: &str, start: usize) -> Option<(String, String, usize)> {
    let bytes = text.as_bytes();
    let mut i = skip_ws_nl(bytes, start);
    if i >= bytes.len() {
        return None;
    }
    if bytes[i] == b')' {
        return Some((String::new(), String::new(), i + 1));
    }
    let (dest, dlen) = scan::scan_link_destination(&text[i..])?;
    i += dlen;
    let after_dest = i;
    i = skip_ws_nl(bytes, i);
    let mut title = String::new();
    if i > after_dest && i < bytes.len() && matches!(bytes[i], b'"' | b'\'' | b'(') {
        let (t, tlen) = scan::scan_link_title(&text[i..])?;
        title = t;
        i += tlen;
        i = skip_ws_nl(bytes, i);
    }
    if i < bytes.len() && bytes[i] == b')' {
        Some((dest, title, i + 1))
    } else {
        None
    }
}

fn skip_ws_nl(bytes: &[u8], mut i: usize) -> usize {
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n') {
        i += 1;
    }
    i
}

/// The delimiter matching algorithm from the CommonMark spec, extended for
/// strikethrough and smart quotes.
fn process_emphasis(items: &mut Vec<Item>, stack_bottom: usize) {
    // openers_bottom indexed by (ch, closer orig_count % 3, can_open)
    let mut openers_bottom: std::collections::HashMap<(u8, usize, bool), usize> = Default::default();
    let mut pos = stack_bottom;
    while pos < items.len() {
        let (ch, can_close, can_open, closer_count, closer_orig) = match &items[pos] {
            Item::Delim {
                ch,
                can_close,
                can_open,
                count,
                orig_count,
            } if *can_close => (*ch, *can_close, *can_open, *count, *orig_count),
            _ => {
                pos += 1;
                continue;
            }
        };
        let _ = can_close;
        let bottom_key = (ch, if ch == b'*' || ch == b'_' { closer_orig % 3 } else { 0 }, can_open);
        let bottom = *openers_bottom.get(&bottom_key).unwrap_or(&stack_bottom);
        // look back for an opener
        let mut opener: Option<usize> = None;
        let mut j = pos;
        while j > bottom {
            j -= 1;
            if let Item::Delim {
                ch: och,
