//! HTML renderer for the event stream, compatible with pulldown-cmark's output.

use super::*;
use std::collections::HashMap;
use std::fmt::Write;

/// Escape text for HTML body/attribute contexts (`&`, `<`, `>`, `"`).
pub fn escape_html(out: &mut String, s: &str) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
}

/// Escape text for HTML body (same as escape_html for our purposes).
pub fn escape_html_body_text(out: &mut String, s: &str) {
    escape_html(out, s)
}

fn href_safe(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b"-_.!~*'();/?:@&=+$,#%".contains(&b)
}

/// Escape a URL for use in an href attribute.
pub fn escape_href(out: &mut String, s: &str) {
    for &b in s.as_bytes() {
        if b < 0x80 && href_safe(b) {
            match b {
                b'&' => out.push_str("&amp;"),
                b'\'' => out.push_str("&#x27;"),
                _ => out.push(b as char),
            }
        } else {
            let _ = write!(out, "%{:02X}", b);
        }
    }
}

#[derive(PartialEq)]
enum TableState {
    Head,
    Body,
}

pub struct HtmlWriter<'a> {
    events: std::slice::Iter<'a, Event>,
    pub out: String,
    end_newline: bool,
    table_state: TableState,
    table_alignments: Vec<Alignment>,
    table_cell_index: usize,
    numbers: HashMap<String, usize>,
}

impl<'a> HtmlWriter<'a> {
    pub fn new(events: &'a [Event]) -> Self {
        HtmlWriter {
            events: events.iter(),
            out: String::new(),
            end_newline: true,
            table_state: TableState::Body,
            table_alignments: Vec::new(),
            table_cell_index: 0,
            numbers: HashMap::new(),
        }
    }

    fn write(&mut self, s: &str) {
        self.out.push_str(s);
        if !s.is_empty() {
            self.end_newline = s.ends_with('\n');
        }
    }

    fn write_newline(&mut self) {
        self.end_newline = true;
        self.out.push('\n');
    }

    pub fn run(mut self) -> String {
        while let Some(event) = self.events.next() {
            match event {
                Event::Start(tag) => self.start_tag(tag),
                Event::End(tag) => self.end_tag(*tag),
                Event::Text(text) => {
                    escape_html_body_text(&mut self.out, text);
                    self.end_newline = text.ends_with('\n');
                }
                Event::Code(text) => {
                    self.write("<code>");
                    escape_html_body_text(&mut self.out, text);
                    self.write("</code>");
                }
                Event::Html(html) | Event::InlineHtml(html) => {
                    self.write(html);
                }
                Event::SoftBreak => self.write_newline(),
                Event::HardBreak => self.write("<br />\n"),
                Event::Rule => {
                    if self.end_newline {
                        self.write("<hr />\n");
                    } else {
                        self.write("\n<hr />\n");
                    }
                }
                Event::FootnoteReference(name) => {
                    let len = self.numbers.len() + 1;
                    self.write("<sup class=\"footnote-reference\"><a href=\"#");
                    escape_html(&mut self.out, name);
                    self.write("\">");
                    let number = *self.numbers.entry(name.clone()).or_insert(len);
                    let _ = write!(self.out, "{}", number);
                    self.write("</a></sup>");
                }
                Event::TaskListMarker(true) => {
                    self.write("<input disabled=\"\" type=\"checkbox\" checked=\"\"/>\n");
                }
                Event::TaskListMarker(false) => {
                    self.write("<input disabled=\"\" type=\"checkbox\"/>\n");
                }
            }
        }
        self.out
    }

    fn start_tag(&mut self, tag: &Tag) {
        match tag {
            Tag::HtmlBlock => {}
            Tag::Paragraph => {
                if self.end_newline {
                    self.write("<p>");
                } else {
                    self.write("\n<p>");
                }
            }
            Tag::Heading {
                level,
                id,
                classes,
                attrs,
            } => {
                if self.end_newline {
                    self.end_newline = false;
                    self.write("<");
                } else {
                    self.write("\n<");
                }
                self.write(level.tag());
                if let Some(id) = id {
                    self.write(" id=\"");
                    escape_html(&mut self.out, id);
                    self.write("\"");
                }
                let mut classes = classes.iter();
                if let Some(class) = classes.next() {
                    self.write(" class=\"");
                    escape_html(&mut self.out, class);
                    for class in classes {
                        self.write(" ");
                        escape_html(&mut self.out, class);
                    }
                    self.write("\"");
                }
                for (attr, value) in attrs {
                    self.write(" ");
                    escape_html(&mut self.out, attr);
                    if let Some(val) = value {
                        self.write("=\"");
                        escape_html(&mut self.out, val);
                        self.write("\"");
                    } else {
                        self.write("=\"\"");
                    }
                }
                self.write(">");
            }
            Tag::Table(alignments) => {
                self.table_alignments = alignments.clone();
