//! Development helper: convert markdown from stdin to HTML on stdout.
use std::io::Read;

fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let smart = std::env::args().any(|a| a == "--smart");
    let mut opts = mdbook::markdown::Options::all();
    opts.smart_punctuation = smart;
    if std::env::args().any(|a| a == "--events") {
        for ev in mdbook::markdown::parse(&s, opts) {
            println!("{:?}", ev);
        }
        return;
    }
    if std::env::args().any(|a| a == "--raw") {
        print!("{}", mdbook::markdown::to_html(&s, opts));
        return;
    }
    let mut hl = std::collections::HashMap::new();
    hl.insert("python".to_string(), "~".to_string());
    let ropts = mdbook::html::render_md::RenderOptions {
        smart_punctuation: smart,
        path: Some(std::path::Path::new("a.md")),
        playground_runnable: !std::env::args().any(|a| a == "--norun"),
        hidelines: Some(&hl),
    };
    print!("{}", mdbook::html::render_md::render_markdown(&s, &ropts));
}
