                    inner.push(e);
                }
                let inner = process_inline_events(inner, opts, &mut footnote_numbers, &mut footnote_ref_counts, &mut footnote_order);
                let text_content = heading_text(&inner);
                let id = match id {
                    Some(id) => id,
                    None => utils::unique_id_from_content(&text_content, &mut id_counter),
                };
                let has_attrs = !attrs.is_empty();
                out.push(Event::Start(Tag::Heading {
                    level,
                    id: Some(id.clone()),
                    classes,
                    attrs,
                }));
                if has_attrs {
                    out.extend(inner);
                } else {
                    let mut s = String::from("<a class=\"header\" href=\"#");
                    escape_html(&mut s, &id);
                    s.push_str("\">");
                    out.push(Event::Html(s));
                    out.extend(inner);
                    out.push(Event::Html("</a>".to_string()));
                }
                out.push(Event::End(TagEnd::Heading(level)));
            }
            Event::Start(Tag::CodeBlock(kind)) => {
                let mut code = String::new();
                for e in iter.by_ref() {
                    match e {
                        Event::Text(t) => code.push_str(&t),
                        Event::End(TagEnd::CodeBlock) => break,
                        _ => {}
                    }
                }
                out.push(Event::Html(render_code_block(&kind, &code, opts)));
            }
            Event::Start(Tag::Table(_)) => {
                out.push(Event::Html("<div class=\"table-wrapper\">".to_string()));
                out.push(ev);
            }
            Event::End(TagEnd::Table) => {
                out.push(ev);
                out.push(Event::Html("</div>".to_string()));
            }
            Event::Start(Tag::FootnoteDefinition(label)) => {
                // gather definition events
                let mut inner = Vec::new();
                let mut depth = 0;
                for e in iter.by_ref() {
                    match &e {
                        Event::Start(_) => depth += 1,
                        Event::End(TagEnd::FootnoteDefinition) if depth == 0 => break,
                        Event::End(_) => depth -= 1,
                        _ => {}
                    }
                    inner.push(e);
                }
                let inner = transform_nested(inner, opts, &mut id_counter, &mut footnote_numbers, &mut footnote_ref_counts, &mut footnote_order);
                footnote_defs.push((label, FootnoteDef { events: inner }));
            }
            other => {
                let processed = process_inline_event(other, opts, &mut footnote_numbers, &mut footnote_ref_counts, &mut footnote_order);
                out.extend(processed);
            }
        }
    }

    // Emit footnotes
    if !footnote_defs.is_empty() {
        let chapter_name = opts
            .path
            .map(|p| p.display().to_string())
            .unwrap_or_else(|| "<unknown>".to_string());
        // warn about unreferenced definitions
        let mut defs: HashMap<String, FootnoteDef> = HashMap::new();
        for (label, def) in footnote_defs {
            if !footnote_numbers.contains_key(&label) {
                log::warn!(
                    "footnote `{}` in `{}` is defined but not referenced",
                    label,
                    chapter_name
                );
            }
            defs.insert(label, def);
        }
        let mut ordered: Vec<(usize, String)> = footnote_numbers
            .iter()
            .map(|(l, n)| (*n, l.clone()))
            .collect();
        ordered.sort();
        let mut s = String::from("<hr>\n<ol class=\"footnote-definition\">");
        out.push(Event::Html(s.clone()));
        s.clear();
        for (_num, label) in ordered {
            if let Some(def) = defs.remove(&label) {
                let mut li = String::from("<li id=\"footnote-");
                escape_html(&mut li, &label);
                li.push_str("\">\n");
                out.push(Event::Html(li));
                // backlinks
                let count = *footnote_ref_counts.get(&label).unwrap_or(&1);
                let mut backlinks = String::new();
                for i in 1..=count {
                    backlinks.push_str(" <a href=\"#fr-");
                    escape_html(&mut backlinks, &label);
                    backlinks.push_str(&format!("-{i}\">↩"));
                    if i > 1 {
                        backlinks.push_str(&i.to_string());
                    }
                    backlinks.push_str("</a>");
                }
                let mut def_events = def.events;
                // If the last block is a paragraph, insert the backlinks before </p>
                if let Some(Event::End(TagEnd::Paragraph)) = def_events.last() {
                    def_events.pop();
                    def_events.push(Event::Html(backlinks));
                    def_events.push(Event::End(TagEnd::Paragraph));
                    out.extend(def_events);
                } else {
                    out.extend(def_events);
                    out.push(Event::Html(backlinks));
                }
                out.push(Event::Html("</li>\n".to_string()));
            }
        }
        out.push(Event::Html("</ol>".to_string()));
    }

    out
}

/// Transform a nested block of events (footnote definition contents).
fn transform_nested(
    events: Vec<Event>,
    opts: &RenderOptions<'_>,
    id_counter: &mut HashMap<String, usize>,
    footnote_numbers: &mut HashMap<String, usize>,
    footnote_ref_counts: &mut HashMap<String, usize>,
    footnote_order: &mut Vec<String>,
) -> Vec<Event> {
    let mut out = Vec::new();
    let mut iter = events.into_iter();
    while let Some(ev) = iter.next() {
        match ev {
            Event::Start(Tag::CodeBlock(kind)) => {
                let mut code = String::new();
                for e in iter.by_ref() {
                    match e {
                        Event::Text(t) => code.push_str(&t),
                        Event::End(TagEnd::CodeBlock) => break,
                        _ => {}
                    }
                }
                out.push(Event::Html(render_code_block(&kind, &code, opts)));
            }
            Event::Start(Tag::Heading {
                level,
                id,
                classes,
                attrs,
            }) => {
                let mut inner = Vec::new();
                let mut depth = 0;
                for e in iter.by_ref() {
                    match &e {
                        Event::Start(_) => depth += 1,
                        Event::End(TagEnd::Heading(_)) if depth == 0 => break,
                        Event::End(_) => depth -= 1,
                        _ => {}
                    }
                    inner.push(e);
                }
                let inner = process_inline_events(inner, opts, footnote_numbers, footnote_ref_counts, footnote_order);
                let text_content = heading_text(&inner);
                let id = match id {
                    Some(id) => id,
                    None => utils::unique_id_from_content(&text_content, id_counter),
                };
                let has_attrs = !attrs.is_empty();
                out.push(Event::Start(Tag::Heading {
                    level,
                    id: Some(id.clone()),
                    classes,
                    attrs,
                }));
                if has_attrs {
                    out.extend(inner);
                } else {
                    let mut s = String::from("<a class=\"header\" href=\"#");
                    escape_html(&mut s, &id);
                    s.push_str("\">");
                    out.push(Event::Html(s));
                    out.extend(inner);
                    out.push(Event::Html("</a>".to_string()));
                }
                out.push(Event::End(TagEnd::Heading(level)));
            }
            Event::Start(Tag::Table(_)) => {
                out.push(Event::Html("<div class=\"table-wrapper\">".to_string()));
                out.push(ev);
            }
            Event::End(TagEnd::Table) => {
                out.push(ev);
                out.push(Event::Html("</div>".to_string()));
            }
            other => {
                out.extend(process_inline_event(other, opts, footnote_numbers, footnote_ref_counts, footnote_order));
            }
        }
    }
    out
}

fn process_inline_events(
    events: Vec<Event>,
    opts: &RenderOptions<'_>,
    footnote_numbers: &mut HashMap<String, usize>,
    footnote_ref_counts: &mut HashMap<String, usize>,
    footnote_order: &mut Vec<String>,
) -> Vec<Event> {
    let mut out = Vec::new();
    for e in events {
        out.extend(process_inline_event(e, opts, footnote_numbers, footnote_ref_counts, footnote_order));
    }
    out
}

fn process_inline_event(
    ev: Event,
    _opts: &RenderOptions<'_>,
    footnote_numbers: &mut HashMap<String, usize>,
    footnote_ref_counts: &mut HashMap<String, usize>,
    footnote_order: &mut Vec<String>,
) -> Vec<Event> {
    match ev {
        Event::Start(Tag::Link {
            link_type,
            dest_url,
            title,
            id,
        }) => vec![Event::Start(Tag::Link {
            link_type,
            dest_url: fix_link(&dest_url),
            title,
            id,
        })],
        Event::Start(Tag::Image {
            link_type,
            dest_url,
            title,
            id,
        }) => vec![Event::Start(Tag::Image {
            link_type,
            dest_url: fix_link(&dest_url),
            title,
            id,
        })],
        Event::Html(h) => vec![Event::Html(fix_html_links(&h))],
        Event::InlineHtml(h) => vec![Event::InlineHtml(fix_html_links(&h))],
        Event::FootnoteReference(label) => {
            let next_num = footnote_numbers.len() + 1;
            let number = *footnote_numbers.entry(label.clone()).or_insert_with(|| {
                footnote_order.push(label.clone());
                next_num
            });
            let count = footnote_ref_counts.entry(label.clone()).or_insert(0);
            *count += 1;
            let mut s = String::from("<sup class=\"footnote-reference\" id=\"fr-");
            escape_html(&mut s, &label);
            s.push_str(&format!("-{}\"><a href=\"#footnote-", count));
            escape_html(&mut s, &label);
            s.push_str(&format!("\">{}</a></sup>", number));
            vec![Event::Html(s)]
        }
        other => vec![other],
    }
}

/// Collect the plain text of heading events (Text and Code events; images skipped).
fn heading_text(events: &[Event]) -> String {
    let mut s = String::new();
    let mut in_image = 0;
    for e in events {
        match e {
            Event::Start(Tag::Image { .. }) => in_image += 1,
            Event::End(TagEnd::Image) => in_image -= 1,
            Event::Text(t) | Event::Code(t) if in_image == 0 => s.push_str(t),
            _ => {}
        }
    }
    s
}

fn escape_code(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

fn render_code_block(kind: &CodeBlockKind, code: &str, opts: &RenderOptions<'_>) -> String {
    match kind {
        CodeBlockKind::Indented => {
            format!("<pre><code>{}</code></pre>\n", escape_code(code))
        }
        CodeBlockKind::Fenced(info) => {
            if info.is_empty() {
                return format!("<pre><code>{}</code></pre>\n", escape_code(code));
            }
            let class = format!("language-{}", info.replace(',', " "));
            let mut tokens = info.split(|c: char| c == ',' || c.is_whitespace()).filter(|s| !s.is_empty());
            let lang = tokens.next().unwrap_or("");
            let attrs: Vec<&str> = tokens.collect();
            let escaped_code = escape_code(code);
            if lang == "rust" {
                let ignore = attrs.contains(&"ignore");
                let noplayground = attrs.contains(&"noplayground");
                let mdbook_runnable = attrs.contains(&"mdbook-runnable");
                let playground = mdbook_runnable || (opts.playground_runnable && !ignore && !noplayground);
                let mut body = escaped_code;
                if playground && !body.contains("fn main") {
                    body = format!("#![allow(unused)]\nfn main() {{\n{}}}", body);
                }
                let body = hide_lines_rust(&body);
                let mut s = String::from("<pre>");
                if playground {
                    s.push_str("<pre class=\"playground\">");
                }
                s.push_str("<code class=\"");
                escape_html(&mut s, &class);
                s.push_str("\">");
                s.push_str(&body);
                s.push_str("</code></pre>");
                if playground {
                    s.push_str("</pre>");
                }
                s.push('\n');
                s
            } else {
                // hidelines prefix
                let mut prefix: Option<String> = None;
                for a in &attrs {
                    if let Some(p) = a.strip_prefix("hidelines=") {
                        prefix = Some(p.to_string());
                    }
                }
                if prefix.is_none() {
                    if let Some(map) = opts.hidelines {
                        if let Some(p) = map.get(lang) {
                            prefix = Some(p.clone());
                        }
                    }
                }
                let body = match prefix {
                    Some(p) if !p.is_empty() => hide_lines_with_prefix(&escaped_code, &p),
                    _ => escaped_code,
                };
                let mut s = String::from("<pre><code class=\"");
                escape_html(&mut s, &class);
                s.push_str("\">");
                s.push_str(&body);
                s.push_str("</code></pre>\n");
                s
            }
        }
    }
}

fn hide_lines_rust(content: &str) -> String {
    let mut result = String::with_capacity(content.len());
    let mut lines = content.lines().peekable();
    while let Some(line) = lines.next() {
        // Don't include newline on the last line.
        let newline = if lines.peek().is_none() { "" } else { "\n" };
        if let Some(caps) = BORING_LINE.captures(line) {
            if &caps[2] == "#" {
                result += &caps[1];
                result += "#";
                result += &caps[3];
                result += newline;
                continue;
            } else if &caps[2] == " " || caps[2].is_empty() {
                result += "<span class=\"boring\">";
                result += &caps[1];
                result += &caps[3];
                result += newline;
                result += "</span>";
                continue;
            }
        }
        result += line;
        result += newline;
    }
    result
}

fn hide_lines_with_prefix(content: &str, prefix: &str) -> String {
    let mut result = String::with_capacity(content.len());
    for line in content.lines() {
        // Allow leading whitespace before the prefix.
        let trimmed = line.trim_start();
        if let Some(rest) = trimmed.strip_prefix(prefix) {
            let leading = &line[..line.len() - trimmed.len()];
            result += "<span class=\"boring\">";
            result += leading;
            result += rest;
            result += "\n</span>";
            continue;
        }
        result += line;
        result += "\n";
    }
    result
}
