//! Markdown to HTML rendering with the mdBook specific transformations
//! (link rewriting, table wrappers, footnotes) and the HTML post-processing
//! steps (header anchors, playground code blocks, hidden lines).

use crate::config::{Code, Playground, RustEdition};
use crate::markdown::html::{escape_html, HtmlWriter};
use crate::markdown::{self, CodeBlockKind, Event, Options, Tag, TagEnd};
use crate::utils;
use once_cell::sync::Lazy;
use regex::{Captures, Regex};
use std::borrow::Cow;
use std::collections::HashMap;
use std::fmt::Write;
use std::path::Path;

static MD_LINK: Lazy<Regex> = Lazy::new(|| Regex::new(r"(?P<link>.*)\.md(?P<anchor>#.*)?").unwrap());
static SCHEME_LINK: Lazy<Regex> = Lazy::new(|| Regex::new(r"^[a-z][a-z0-9+.-]*:").unwrap());
static HTML_LINK: Lazy<Regex> =
    Lazy::new(|| Regex::new(r#"(<(?:a|img) [^>]*?(?:src|href)=")([^"]+?)""#).unwrap());

/// Fix a link destination: `.md` links become `.html`, and (for the print
/// page) relative links are made relative to the chapter's directory.
pub fn fix_link<'a>(dest: Cow<'a, str>, path: Option<&Path>) -> Cow<'a, str> {
    if dest.starts_with('#') {
        // Fragment-only link.
        if let Some(path) = path {
            let mut base = path.display().to_string();
            if base.ends_with(".md") {
                base.replace_range(base.len() - 3.., ".html");
            }
            return format!("{base}{dest}").into();
        } else {
            return dest;
        }
    }
    // Don't modify links with schemes like `https`.
    if !SCHEME_LINK.is_match(&dest) {
        // This is a relative link, adjust it as necessary.
        let mut fixed_link = String::new();
        if let Some(path) = path {
            let base = path
                .parent()
                .expect("path can't be empty")
                .to_str()
                .expect("utf-8 paths only");
            if !base.is_empty() {
                write!(fixed_link, "{base}/").unwrap();
            }
        }

        if let Some(caps) = MD_LINK.captures(&dest) {
            fixed_link.push_str(&caps["link"]);
            fixed_link.push_str(".html");
            if let Some(anchor) = caps.name("anchor") {
                fixed_link.push_str(anchor.as_str());
            }
        } else {
            fixed_link.push_str(&dest);
        };
        return Cow::Owned(fixed_link);
    }
    dest
}

fn fix_html(html: String, path: Option<&Path>) -> String {
    HTML_LINK
        .replace_all(&html, |caps: &Captures<'_>| {
            let fixed = fix_link(Cow::Borrowed(&caps[2]), path);
            format!("{}{}\"", &caps[1], fixed)
        })
        .into_owned()
}

fn adjust_links(event: Event, path: Option<&Path>) -> Event {
    match event {
        Event::Start(Tag::Link {
            link_type,
            dest_url,
            title,
            id,
        }) => Event::Start(Tag::Link {
            link_type,
            dest_url: fix_link(Cow::Owned(dest_url), path).into_owned(),
            title,
            id,
        }),
        Event::Start(Tag::Image {
            link_type,
            dest_url,
            title,
            id,
        }) => Event::Start(Tag::Image {
            link_type,
            dest_url: fix_link(Cow::Owned(dest_url), path).into_owned(),
            title,
            id,
        }),
        Event::Html(html) => Event::Html(fix_html(html, path)),
        Event::InlineHtml(html) => Event::InlineHtml(fix_html(html, path)),
        _ => event,
    }
}

fn clean_codeblock_headers(event: Event) -> Event {
    match event {
        Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info))) => {
            let info: String = info.chars().map(|x| if x == ',' { ' ' } else { x }).collect();
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info)))
        }
        _ => event,
    }
}

/// Create the parser options used by mdBook.
pub fn new_cmark_options(smart_punctuation: bool) -> Options {
    let mut opts = Options::all();
    opts.smart_punctuation = smart_punctuation;
    opts
}

/// Render markdown to HTML.
pub fn render_markdown(text: &str, smart_punctuation: bool) -> String {
    render_markdown_with_path(text, smart_punctuation, None)
}

/// Render markdown to HTML, adjusting relative links for the given chapter path
/// (used when building the print page).
pub fn render_markdown_with_path(text: &str, smart_punctuation: bool, path: Option<&Path>) -> String {
    let events = markdown::parse(text, new_cmark_options(smart_punctuation));
    let mut out: Vec<Event> = Vec::with_capacity(events.len() + 8);
    for ev in events {
        let ev = clean_codeblock_headers(ev);
        let ev = adjust_links(ev, path);
        match ev {
            Event::Start(Tag::Table(_)) => {
                out.push(Event::Html("<div class=\"table-wrapper\">".to_string()));
                out.push(ev);
            }
            Event::End(TagEnd::Table) => {
                out.push(ev);
                out.push(Event::Html("</div>".to_string()));
            }
            _ => out.push(ev),
        }
    }
    let out = handle_footnotes(out, path);
    HtmlWriter::new(&out).run()
}

struct Footnotes {
    numbers: HashMap<String, usize>,
    ref_counts: HashMap<String, usize>,
}

impl Footnotes {
    fn reference(&mut self, label: &str) -> Event {
        let next = self.numbers.len() + 1;
        let number = *self.numbers.entry(label.to_string()).or_insert(next);
        let count = self.ref_counts.entry(label.to_string()).or_insert(0);
        *count += 1;
        let mut s = String::from("<sup class=\"footnote-reference\" id=\"fr-");
        escape_html(&mut s, label);
        let _ = write!(s, "-{}\"><a href=\"#footnote-", count);
        escape_html(&mut s, label);
        let _ = write!(s, "\">{}</a></sup>", number);
        Event::Html(s)
    }
}

/// Convert footnote references and definitions into mdBook's HTML structure.
fn handle_footnotes(events: Vec<Event>, path: Option<&Path>) -> Vec<Event> {
    let has_footnotes = events
        .iter()
        .any(|e| matches!(e, Event::FootnoteReference(_) | Event::Start(Tag::FootnoteDefinition(_))));
    if !has_footnotes {
        return events;
    }

    let mut fns = Footnotes {
        numbers: HashMap::new(),
        ref_counts: HashMap::new(),
    };
    let mut out = Vec::with_capacity(events.len());
    let mut defs: Vec<(String, Vec<Event>)> = Vec::new();
    let mut iter = events.into_iter();
    while let Some(ev) = iter.next() {
        match ev {
            Event::FootnoteReference(label) => out.push(fns.reference(&label)),
            Event::Start(Tag::FootnoteDefinition(label)) => {
                let mut inner = Vec::new();
                let mut depth = 0;
                for e in iter.by_ref() {
                    match &e {
                        Event::Start(_) => depth += 1,
                        Event::End(TagEnd::FootnoteDefinition) if depth == 0 => break,
                        Event::End(_) => depth -= 1,
                        _ => {}
                    }
                    inner.push(e);
                }
                defs.push((label, inner));
            }
            other => out.push(other),
        }
    }

    // References inside definitions are processed in definition order.
    let mut processed_defs: Vec<(String, Vec<Event>)> = Vec::new();
    for (label, inner) in defs {
        let mut processed = Vec::with_capacity(inner.len());
        for e in inner {
            match e {
                Event::FootnoteReference(l) => processed.push(fns.reference(&l)),
                other => processed.push(other),
            }
        }
        processed_defs.push((label, processed));
    }

    let chapter_name = path
        .map(|p| p.display().to_string())
        .unwrap_or_else(|| "<unknown>".to_string());
    let mut def_map: HashMap<String, Vec<Event>> = HashMap::new();
    for (label, events) in processed_defs {
        if !fns.numbers.contains_key(&label) {
            log::warn!(
                "footnote `{}` in `{}` is defined but not referenced",
                label,
                chapter_name
            );
        }
        def_map.entry(label).or_insert(events);
    }

    if def_map.is_empty() && fns.numbers.is_empty() {
        return out;
    }

    let mut ordered: Vec<(usize, &String)> = fns.numbers.iter().map(|(l, n)| (*n, l)).collect();
    ordered.sort();

    out.push(Event::Html("<hr>\n<ol class=\"footnote-definition\">".to_string()));
    for (_n, label) in ordered {
        let def_events = match def_map.remove(label) {
            Some(d) => d,
            None => {
                log::warn!(
                    "footnote `{}` in `{}` is referenced but not defined",
                    label,
                    chapter_name
                );
                continue;
            }
        };
        let mut li = String::from("<li id=\"footnote-");
        escape_html(&mut li, label);
        li.push_str("\">\n");
        out.push(Event::Html(li));
        let count = *fns.ref_counts.get(label).unwrap_or(&1);
        let mut backlinks = String::new();
        for i in 1..=count {
            backlinks.push_str(" <a href=\"#fr-");
            escape_html(&mut backlinks, label);
            let _ = write!(backlinks, "-{i}\">↩");
            if i > 1 {
                let _ = write!(backlinks, "{i}");
            }
            backlinks.push_str("</a>");
        }
        let mut def_events = def_events;
        if let Some(Event::End(TagEnd::Paragraph)) = def_events.last() {
            def_events.pop();
            def_events.push(Event::Html(backlinks));
            def_events.push(Event::End(TagEnd::Paragraph));
            out.extend(def_events);
        } else {
            out.extend(def_events);
            out.push(Event::Html(backlinks));
        }
        out.push(Event::Html("</li>\n".to_string()));
    }
    out.push(Event::Html("</ol>".to_string()));
    out
}

// -------------------------------------------------------------------------
// HTML post-processing

static BUILD_HEADER_LINKS: Lazy<Regex> =
    Lazy::new(|| Regex::new(r#"<h(\d)(?: id="([^"]+)")?(?: class="([^"]+)")?>(.*?)</h\d>"#).unwrap());
static FIX_CODE_BLOCKS: Lazy<Regex> = Lazy::new(|| Regex::new(r##"<code([^>]+)class="([^"]+)"([^>]*)>"##).unwrap());
static CODE_BLOCK_RE: Lazy<Regex> =
    Lazy::new(|| Regex::new(r##"((?s)<code[^>]?class="([^"]+)".*?>(.*?)</code>)"##).unwrap());
static BORING_LINES_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"^(\s*)#(.?)(.*)$").unwrap());
static LANGUAGE_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"\blanguage-(\w+)\b").unwrap());
static HIDELINES_REGEX: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bhidelines=(\S+)").unwrap());

/// Apply all the HTML post-processing steps used for chapter content.
pub fn post_process(rendered: String, playground_config: &Playground, code_config: &Code, edition: Option<RustEdition>) -> String {
    let rendered = build_header_links(&rendered);
    let rendered = fix_code_blocks(&rendered);
    let rendered = add_playground_pre(&rendered, playground_config, edition);
    hide_lines(&rendered, code_config)
}

/// Goes through the rendered HTML, making sure all header tags have
/// an anchor respectively so people can link to sections directly.
pub fn build_header_links(html: &str) -> String {
    static IGNORE_CLASS: &[&str] = &["menu-title"];
    let mut id_counter = HashMap::new();

    BUILD_HEADER_LINKS
        .replace_all(html, |caps: &Captures<'_>| {
            let level = caps[1]
                .parse()
                .expect("Regex should ensure we only ever get numbers here");

            // Ignore .menu-title because now it's getting detected by the regex.
            if let Some(classes) = caps.get(3) {
                for class in classes.as_str().split(' ') {
                    if IGNORE_CLASS.contains(&class) {
                        return caps[0].to_string();
                    }
                }
            }

            insert_link_into_header(
                level,
                &caps[4],
                caps.get(2).map(|x| x.as_str().to_string()),
                caps.get(3).map(|x| x.as_str().to_string()),
                &mut id_counter,
            )
        })
        .into_owned()
}

fn insert_link_into_header(
    level: usize,
    content: &str,
    id: Option<String>,
    classes: Option<String>,
    id_counter: &mut HashMap<String, usize>,
) -> String {
    let id = id.unwrap_or_else(|| unique_id_from_content(content, id_counter));
    let classes = classes.map(|s| format!(" class=\"{s}\"")).unwrap_or_default();

    format!(r##"<h{level} id="{id}"{classes}><a class="header" href="#{id}">{content}</a></h{level}>"##)
}

/// Generate an ID for use with anchors which is derived from a "normalised"
/// string.
pub fn id_from_content(content: &str) -> String {
    let mut content = content.to_string();

    // Skip any tags or html-encoded stuff
    static HTML: Lazy<Regex> = Lazy::new(|| Regex::new(r"(<.*?>)").unwrap());
    content = HTML.replace_all(&content, "").into();
    const REPL_SUB: &[&str] = &["&lt;", "&gt;", "&amp;", "&#39;", "&quot;"];
    for sub in REPL_SUB {
        content = content.replace(sub, "");
    }

    // Remove spaces and hashes indicating a header
    let trimmed = content.trim().trim_start_matches('#').trim();
    utils::normalize_id(trimmed)
}

/// Generate an ID for use with anchors which is derived from a "normalised"
/// string, making sure the id is unique within the counter's scope.
pub fn unique_id_from_content(content: &str, id_counter: &mut HashMap<String, usize>) -> String {
    let id = {
        let id = id_from_content(content);
        if id.is_empty() {
            String::new()
        } else {
            id
        }
    };

    // If we have headers with the same normalized id, append an incrementing counter
    let id_count = id_counter.entry(id.clone()).or_insert(0);
    let unique_id = match *id_count {
        0 => id,
        id_count => format!("{id}-{id_count}"),
    };
    *id_count += 1;
    unique_id
}

fn fix_code_blocks(html: &str) -> String {
    FIX_CODE_BLOCKS
        .replace_all(html, |caps: &Captures<'_>| {
            let before = &caps[1];
            let classes = &caps[2].replace(',', " ");
            let after = &caps[3];

            format!(r#"<code{before}class="{classes}"{after}>"#)
        })
        .into_owned()
}

fn add_playground_pre(html: &str, playground_config: &Playground, edition: Option<RustEdition>) -> String {
    CODE_BLOCK_RE
        .replace_all(html, |caps: &Captures<'_>| {
            let text = &caps[1];
            let classes = &caps[2];
            let code = &caps[3];

            if classes.contains("language-rust")
                && ((!classes.contains("ignore")
                    && !classes.contains("noplayground")
                    && !classes.contains("noplaypen")
                    && playground_config.runnable)
                    || classes.contains("mdbook-runnable"))
            {
                let contains_e2015 = classes.contains("edition2015");
                let contains_e2018 = classes.contains("edition2018");
                let contains_e2021 = classes.contains("edition2021");
                let contains_e2024 = classes.contains("edition2024");
                let edition_class = if contains_e2015 || contains_e2018 || contains_e2021 || contains_e2024 {
                    // the user forced edition, we should not overwrite it
                    ""
                } else {
                    match edition {
                        Some(RustEdition::E2015) => " edition2015",
                        Some(RustEdition::E2018) => " edition2018",
                        Some(RustEdition::E2021) => " edition2021",
                        Some(RustEdition::E2024) => " edition2024",
                        None => "",
                    }
                };

                // wrap the contents in an external pre block
                format!(
                    "<pre class=\"playground\"><code class=\"{}{}\">{}</code></pre>",
                    classes,
                    edition_class,
                    {
                        let content: Cow<'_, str> = if playground_config.editable && classes.contains("editable")
                            || text.contains("fn main")
                            || text.contains("quick_main!")
                        {
                            code.into()
                        } else {
                            // we need to inject our own main
                            let (attrs, code) = partition_source(code);

                            format!("# #![allow(unused)]\n{attrs}# fn main() {{\n{code}# }}").into()
                        };
                        content
                    }
                )
            } else {
                // not language-rust, so no-op
                text.to_owned()
            }
        })
        .into_owned()
}

fn hide_lines(html: &str, code_config: &Code) -> String {
    CODE_BLOCK_RE
        .replace_all(html, |caps: &Captures<'_>| {
            let text = &caps[1];
            let classes = &caps[2];
            let code = &caps[3];

            if classes.contains("language-rust") {
                format!("<code class=\"{}\">{}</code>", classes, hide_lines_rust(code))
            } else {
                // First try to get the prefix from the code block attributes
                let hidelines_capture = HIDELINES_REGEX.captures(classes);
                let hidelines_prefix = match &hidelines_capture {
                    Some(capture) => Some(&capture[1]),
                    None => {
                        // Then look up the prefix by language
                        LANGUAGE_REGEX
                            .captures(classes)
                            .and_then(|capture| code_config.hidelines.get(&capture[1]).map(|p| p.as_str()))
                    }
                };

                match hidelines_prefix {
                    Some(prefix) => format!(
                        "<code class=\"{}\">{}</code>",
                        classes,
                        hide_lines_with_prefix(code, prefix)
                    ),
                    None => text.to_owned(),
                }
            }
        })
        .into_owned()
}

fn hide_lines_rust(content: &str) -> String {
    let mut result = String::with_capacity(content.len());
    let mut lines = content.lines().peekable();
    while let Some(line) = lines.next() {
        // Don't include newline on the last line.
        let newline = if lines.peek().is_none() { "" } else { "\n" };
        if let Some(caps) = BORING_LINES_REGEX.captures(line) {
            if &caps[2] == "#" {
                result += &caps[1];
                result += &caps[2];
                result += &caps[3];
                result += newline;
                continue;
            } else if &caps[2] == " " || caps[2].is_empty() {
                result += "<span class=\"boring\">";
                result += &caps[1];
                result += &caps[3];
                result += newline;
                result += "</span>";
                continue;
            }
        }
        result += line;
        result += newline;
    }
    result
}

fn hide_lines_with_prefix(content: &str, prefix: &str) -> String {
    let mut result = String::with_capacity(content.len());
    for line in content.lines() {
        if line.trim_start().starts_with(prefix) {
            let pos = line.find(prefix).unwrap();
            let (ws, rest) = (&line[..pos], &line[pos + prefix.len()..]);

            result += "<span class=\"boring\">";
            result += ws;
            result += rest;
            result += "\n";
            result += "</span>";
            continue;
        }
        result += line;
        result += "\n";
    }
    result
}

fn partition_source(s: &str) -> (String, String) {
    let mut after_header = false;
    let mut before = String::new();
    let mut after = String::new();

    for line in s.lines() {
        let trimline = line.trim();
        let header = trimline.chars().all(char::is_whitespace) || trimline.starts_with("#![");
        if !header || after_header {
            after_header = true;
            after.push_str(line);
            after.push('\n');
        } else {
            before.push_str(line);
            before.push('\n');
        }
    }

    (before, after)
}
