/// Parse a document, returning events paired with their source byte offsets.
pub fn parse_document_with_offsets(text: &str, options: Options) -> Vec<(Event, usize)> {
    // Positions are only meaningful for the original text; we assume the
    // caller passes text without CR characters (SUMMARY.md is normalised first).
    let text_owned: String;
    let text = if text.contains('\\0') {
        text_owned = text.replace('\\0', "\\u{FFFD}");
        &text_owned
    } else {
        text
    };
    let mut parser = BlockParser::new(options);
    let mut lines: Vec<&str> = text.split('\\n').collect();
    if text.ends_with('\\n') {
        lines.pop();
    }
    let mut pos = 0;
    for line in lines {
        parser.incorporate_line(line, pos);
        pos += line.len() + 1;
    }
    parser.finish();
    let mut events = Vec::new();
    let ctx = InlineContext {
        refmap: &parser.refmap,
        footnote_labels: &parser.footnote_labels,
        options,
    };
    emit_children(&parser.nodes, 0, &ctx, &mut events, false);
    events
}''')
