new='''fn emit_children(nodes: &[Node], idx: usize, ctx: &InlineContext, events: &mut Vec<(Event, usize)>, tight: bool) {
    for &child in &nodes[idx].children {
        emit_node(nodes, child, ctx, events, tight);
    }
}

fn emit_node(nodes: &[Node], idx: usize, ctx: &InlineContext, events: &mut Vec<(Event, usize)>, tight: bool) {
    let node = &nodes[idx];
    let off = node.start_offset;
    match &node.kind {
        Kind::Document => emit_children(nodes, idx, ctx, events, false),
        Kind::BlockQuote => {
            events.push((Event::Start(Tag::BlockQuote), off));
            emit_children(nodes, idx, ctx, events, false);
            events.push((Event::End(TagEnd::BlockQuote), off));
        }
        Kind::List(data) => {
            let start = if data.ordered { Some(data.start) } else { None };
            events.push((Event::Start(Tag::List(start)), off));
            for &child in &node.children {
                emit_node(nodes, child, ctx, events, data.tight);
            }
            events.push((Event::End(TagEnd::List(data.ordered)), off));
        }
        Kind::Item(_) => {
            events.push((Event::Start(Tag::Item), off));
            let mut first = true;
            for &child in &node.children {
                let cnode = &nodes[child];
                if tight && matches!(cnode.kind, Kind::Paragraph) {
                    // tight list: paragraph contents inline without <p>
                    let text = cnode.lines.join("\\n");
                    let map = LineMap::from_lines(&cnode.lines, &cnode.line_offsets);
                    parse_inlines(&text, ctx, events, first && ctx.options.tasklists, &map);
                } else {
                    emit_node(nodes, child, ctx, events, false);
                }
                first = false;
            }
            events.push((Event::End(TagEnd::Item), off));
        }
        Kind::FootnoteDef { label } => {
            events.push((Event::Start(Tag::FootnoteDefinition(label.clone())), off));
            emit_children(nodes, idx, ctx, events, false);
            events.push((Event::End(TagEnd::FootnoteDefinition), off));
        }
        Kind::Paragraph => {
            let text = node.lines.join("\\n");
            let map = LineMap::from_lines(&node.lines, &node.line_offsets);
            events.push((Event::Start(Tag::Paragraph), off));
            parse_inlines(&text, ctx, events, false, &map);
            events.push((Event::End(TagEnd::Paragraph), off));
        }
        Kind::Heading { level, .. } => {
            let text = node.lines.join("\\n");
            let (id, classes, attrs) = match &node.attr_block {
                Some(block) => parse_heading_attr_block(block),
                None => (None, Vec::new(), Vec::new()),
            };
            let level = HeadingLevel::from_u8(*level);
            events.push((
                Event::Start(Tag::Heading {
                    level,
                    id,
                    classes,
                    attrs,
                }),
                off,
            ));
            let trimmed = text.trim();
            let lead = text.len() - text.trim_start().len();
            let mut map = LineMap::from_lines(&node.lines, &node.line_offsets);
            // shift the map so that position 0 corresponds to the trimmed start
            for e in map.entries.iter_mut() {
                e.0 = e.0.saturating_sub(lead);
            }
            if lead > 0 {
                if let Some(first) = map.entries.first_mut() {
                    first.1 += lead;
                }
            }
            parse_inlines(trimmed, ctx, events, false, &map);
            events.push((Event::End(TagEnd::Heading(level)), off));
        }
        Kind::ThematicBreak => events.push((Event::Rule, off)),
        Kind::IndentedCode => {
            let mut content = String::new();
            for l in &node.lines {
                content.push_str(l);
                content.push('\\n');
            }
            events.push((Event::Start(Tag::CodeBlock(CodeBlockKind::Indented)), off));
            events.push((Event::Text(content), off));
            events.push((Event::End(TagEnd::CodeBlock), off));
        }
        Kind::FencedCode { .. } => {
            let mut content = String::new();
            for l in &node.lines {
                content.push_str(l);
                content.push('\\n');
            }
            events.push((Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(node.info.clone()))), off));
            if !content.is_empty() {
                let coff = node.line_offsets.first().copied().unwrap_or(off);
                events.push((Event::Text(content), coff));
            }
            events.push((Event::End(TagEnd::CodeBlock), off));
        }
        Kind::HtmlBlock { .. } => {
            events.push((Event::Start(Tag::HtmlBlock), off));
            for (i, l) in node.lines.iter().enumerate() {
                let mut s = l.clone();
                s.push('\\n');
                let loff = node.line_offsets.get(i).copied().unwrap_or(off);
                events.push((Event::Html(s), loff));
            }
            events.push((Event::End(TagEnd::HtmlBlock), off));
        }
        Kind::Table {
            alignments,
            header,
            rows,
        } => {
            let ncols = alignments.len();
            let map = LineMap::single(off);
            events.push((Event::Start(Tag::Table(alignments.clone())), off));
            events.push((Event::Start(Tag::TableHead), off));
            for i in 0..ncols {
                events.push((Event::Start(Tag::TableCell), off));
                if let Some(cell) = header.get(i) {
                    parse_inlines(cell, ctx, events, false, &map);
                }
                events.push((Event::End(TagEnd::TableCell), off));
            }
            events.push((Event::End(TagEnd::TableHead), off));
            for row in rows {
                events.push((Event::Start(Tag::TableRow), off));
                for i in 0..ncols {
                    events.push((Event::Start(Tag::TableCell), off));
                    if let Some(cell) = row.get(i) {
                        parse_inlines(cell, ctx, events, false, &map);
                    }
                    events.push((Event::End(TagEnd::TableCell), off));
                }
                events.push((Event::End(TagEnd::TableRow), off));
            }
            events.push((Event::End(TagEnd::Table), off));
        }
    }
}

