/// Maps positions in the inline text back to source byte offsets.
pub struct LineMap {
    /// (text position of line start, source offset of line start)
    pub entries: Vec<(usize, usize)>,
}

impl LineMap {
    pub fn single(src_offset: usize) -> LineMap {
        LineMap {
            entries: vec![(0, src_offset)],
        }
    }

    /// Build a line map for `lines` joined with newlines.
    pub fn from_lines(lines: &[String], offsets: &[usize]) -> LineMap {
        let mut entries = Vec::with_capacity(lines.len());
        let mut pos = 0;
        for (i, l) in lines.iter().enumerate() {
            entries.push((pos, offsets.get(i).copied().unwrap_or(0)));
            pos += l.len() + 1;
        }
        if entries.is_empty() {
            entries.push((0, offsets.first().copied().unwrap_or(0)));
        }
        LineMap { entries }
    }

    pub fn src(&self, text_pos: usize) -> usize {
        let mut best = self.entries[0];
        for &(tp, so) in &self.entries {
            if tp <= text_pos {
                best = (tp, so);
            } else {
                break;
            }
        }
        best.1 + (text_pos - best.0)
    }
}''')

