//! The in-memory representation of a book and the top level `MDBook` type.

use crate::config::{Config, RustEdition};
use crate::errors::*;
use crate::preprocess::{self, Preprocessor, PreprocessorContext};
use crate::renderer::{self, RenderContext, Renderer};
use crate::summary::{parse_summary, Link, SectionNumber, Summary, SummaryItem};
use log::{debug, info, log_enabled, trace, warn};
use serde::{Deserialize, Serialize};
