//! A small Handlebars template engine supporting the subset of the language
//! used by mdBook themes (expressions, block helpers, partials, comments,
//! whitespace control and standalone line handling).

use crate::errors::*;
use serde_json::Value as Json;
use std::collections::HashMap;

// -------------------------------------------------------------------------
// AST

#[derive(Debug, Clone, PartialEq)]
pub enum Param {
    Path(String),
    Literal(Json),
    SubExpr(Box<Expr>),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Expr {
    pub name: String,
    pub params: Vec<Param>,
    pub hash: Vec<(String, Param)>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Node {
    Text(String),
    /// `{{expr}}` (escaped) or `{{{expr}}}` (raw)
    Expression { expr: Expr, raw: bool },
    Block {
        expr: Expr,
        inverted: bool,
        body: Vec<Node>,
        inverse: Option<Vec<Node>>,
    },
    Partial { expr: Expr, indent: Option<String> },
}

/// A compiled template.
#[derive(Debug, Clone)]
pub struct Template {
    pub nodes: Vec<Node>,
}

// -------------------------------------------------------------------------
// Tokenizer

#[derive(Debug, Clone)]
enum TokenKind {
    Text,
    Expression { raw: bool },
    BlockOpen { inverted: bool },
    BlockClose,
    Else,
    Partial,
    Comment,
}

#[derive(Debug, Clone)]
struct Token {
    kind: TokenKind,
    /// Text content (for Text) or tag inner content (for tags)
    content: String,
    strip_left: bool,
    strip_right: bool,
}

fn tokenize(src: &str) -> Result<Vec<Token>> {
    let mut tokens = Vec::new();
    let mut rest = src;
    let mut text = String::new();
    while let Some(pos) = rest.find("{{") {
        // handle escaped `\{{`
        if pos > 0 && rest.as_bytes()[pos - 1] == b'\\' {
            text.push_str(&rest[..pos - 1]);
            text.push_str("{{");
            rest = &rest[pos + 2..];
            continue;
        }
        text.push_str(&rest[..pos]);
        if !text.is_empty() {
            tokens.push(Token {
                kind: TokenKind::Text,
                content: std::mem::take(&mut text),
                strip_left: false,
                strip_right: false,
            });
        }
        let after = &rest[pos + 2..];
        // comment
        if after.starts_with("!--") {
            let end = after
                .find("--}}")
                .ok_or_else(|| anyhow!("Unterminated comment in template"))?;
            tokens.push(Token {
                kind: TokenKind::Comment,
                content: after[3..end].to_string(),
                strip_left: false,
                strip_right: false,
            });
            rest = &after[end + 4..];
            continue;
        }
        if after.starts_with('!') {
            let end = after
                .find("}}")
                .ok_or_else(|| anyhow!("Unterminated comment in template"))?;
            tokens.push(Token {
                kind: TokenKind::Comment,
                content: after[1..end].to_string(),
                strip_left: false,
                strip_right: false,
            });
            rest = &after[end + 2..];
            continue;
        }
        // raw triple-stash
        if after.starts_with('{') {
            let end = after
                .find("}}}")
                .ok_or_else(|| anyhow!("Unterminated expression in template"))?;
            let mut inner = &after[1..end];
            let mut strip_left = false;
            let mut strip_right = false;
            if inner.starts_with('~') {
                strip_left = true;
                inner = &inner[1..];
            }
            if inner.ends_with('~') {
                strip_right = true;
                inner = &inner[..inner.len() - 1];
            }
            tokens.push(Token {
                kind: TokenKind::Expression { raw: true },
                content: inner.trim().to_string(),
                strip_left,
                strip_right,
            });
            rest = &after[end + 3..];
            continue;
        }
        let end = find_tag_end(after).ok_or_else(|| anyhow!("Unterminated expression in template"))?;
        let mut inner = &after[..end];
        let mut strip_left = false;
        let mut strip_right = false;
        if inner.starts_with('~') {
            strip_left = true;
            inner = &inner[1..];
        }
        if inner.ends_with('~') {
            strip_right = true;
            inner = &inner[..inner.len() - 1];
        }
        let inner = inner.trim();
        let (kind, content) = if let Some(r) = inner.strip_prefix('#') {
            (TokenKind::BlockOpen { inverted: false }, r.trim().to_string())
        } else if let Some(r) = inner.strip_prefix('/') {
            (TokenKind::BlockClose, r.trim().to_string())
        } else if let Some(r) = inner.strip_prefix('>') {
            (TokenKind::Partial, r.trim().to_string())
        } else if inner == "else" || inner == "^" {
            (TokenKind::Else, String::new())
        } else if let Some(r) = inner.strip_prefix("else ") {
            // `{{else if x}}` chained else
            (TokenKind::Else, r.trim().to_string())
        } else if let Some(r) = inner.strip_prefix('^') {
            (TokenKind::BlockOpen { inverted: true }, r.trim().to_string())
        } else if let Some(r) = inner.strip_prefix('&') {
            // `{{& x}}` is an unescaped expression
            tokens.push(Token {
                kind: TokenKind::Expression { raw: true },
                content: r.trim().to_string(),
                strip_left,
                strip_right,
            });
            rest = &after[end + 2..];
            continue;
        } else {
            (TokenKind::Expression { raw: false }, inner.to_string())
        };
        tokens.push(Token {
            kind,
            content,
            strip_left,
            strip_right,
        });
        rest = &after[end + 2..];
    }
    text.push_str(rest);
    if !text.is_empty() {
        tokens.push(Token {
            kind: TokenKind::Text,
            content: text,
            strip_left: false,
            strip_right: false,
        });
    }
    Ok(tokens)
}

/// Find the end (`}}`) of a tag, skipping over string literals.
fn find_tag_end(s: &str) -> Option<usize> {
    let bytes = s.as_bytes();
    let mut i = 0;
    let mut quote: Option<u8> = None;
    while i < bytes.len() {
        let b = bytes[i];
        match quote {
            Some(q) => {
                if b == b'\\' {
                    i += 2;
                    continue;
                }
                if b == q {
                    quote = None;
                }
            }
            None => {
                if b == b'"' || b == b'\'' {
                    quote = Some(b);
                } else if b == b'}' && bytes.get(i + 1) == Some(&b'}') {
                    return Some(i);
                }
            }
        }
        i += 1;
    }
    None
}

/// Apply whitespace control (`~`) and standalone-line stripping.
fn process_whitespace(tokens: &mut Vec<Token>) -> Vec<Option<String>> {
    // returns per-token partial indentation (for standalone partials)
    let n = tokens.len();
    let mut indents: Vec<Option<String>> = vec![None; n];

    // `~` handling
    for i in 0..n {
        if tokens[i].strip_left && i > 0 {
            if let TokenKind::Text = tokens[i - 1].kind {
                let t = tokens[i - 1].content.trim_end().to_string();
                tokens[i - 1].content = t;
            }
        }
        if tokens[i].strip_right && i + 1 < n {
            if let TokenKind::Text = tokens[i + 1].kind {
                let t = tokens[i + 1].content.trim_start().to_string();
                tokens[i + 1].content = t;
            }
        }
    }

    // standalone handling
    for i in 0..n {
        let standalone_able = matches!(
            tokens[i].kind,
            TokenKind::BlockOpen { .. } | TokenKind::BlockClose | TokenKind::Else | TokenKind::Partial | TokenKind::Comment
        );
        if !standalone_able {
            continue;
        }
        // Check preceding text: from last newline to end must be whitespace (spaces/tabs)
        let (prev_ok, prev_ws_start) = if i == 0 {
            (true, 0)
        } else if let TokenKind::Text = tokens[i - 1].kind {
            let t = &tokens[i - 1].content;
            let line_start = t.rfind('\n').map(|p| p + 1).unwrap_or(0);
            let tail = &t[line_start..];
            if tail.chars().all(|c| c == ' ' || c == '\t') {
                // if there's no newline in the text and it's not the first token, then
                // the tag isn't at a line start
                if line_start == 0 && i - 1 != 0 {
                    (false, 0)
                } else {
                    (true, line_start)
                }
            } else {
                (false, 0)
            }
        } else {
            (false, 0)
        };
        if !prev_ok {
            continue;
        }
        // Check following text: up to and including first newline must be whitespace
        let (next_ok, next_cut) = if i + 1 >= n {
            (true, 0)
        } else if let TokenKind::Text = tokens[i + 1].kind {
            let t = &tokens[i + 1].content;
            match t.find('\n') {
                Some(p) => {
                    if t[..p].chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
                        (true, p + 1)
                    } else {
                        (false, 0)
                    }
                }
                None => {
                    if i + 1 == n - 1 && t.chars().all(|c| c == ' ' || c == '\t') {
                        (true, t.len())
                    } else {
                        (false, 0)
                    }
                }
            }
        } else {
            (false, 0)
        };
        if !next_ok {
            continue;
        }
        // strip
        if i > 0 {
            if let TokenKind::Text = tokens[i - 1].kind {
                let indent = tokens[i - 1].content[prev_ws_start..].to_string();
                if let TokenKind::Partial = tokens[i].kind {
                    if !indent.is_empty() {
                        indents[i] = Some(indent);
                    }
                }
                tokens[i - 1].content.truncate(prev_ws_start);
            }
        }
        if i + 1 < n {
            if let TokenKind::Text = tokens[i + 1].kind {
                let t = tokens[i + 1].content[next_cut..].to_string();
                tokens[i + 1].content = t;
            }
        }
    }
    indents
}

// -------------------------------------------------------------------------
// Expression parsing

fn parse_expr(s: &str) -> Result<Expr> {
    let parts = split_params(s)?;
    if parts.is_empty() {
        bail!("Empty expression in template");
    }
    let name = match &parts[0] {
        Param::Path(p) => p.clone(),
        Param::Literal(Json::String(s)) => s.clone(),
        other => bail!("Invalid helper name: {:?}", other),
    };
    let mut params = Vec::new();
    let mut hash = Vec::new();
    for p in parts.into_iter().skip(1) {
        match p {
            Param::Path(ref path) if path.contains('=') && !path.starts_with('=') => {
                // hash pair key=value (value may be literal or path)
                let (k, v) = path.split_once('=').unwrap();
                let v = parse_single_param(v)?;
                hash.push((k.to_string(), v));
            }
            other => params.push(other),
        }
    }
    Ok(Expr { name, params, hash })
}

fn parse_single_param(s: &str) -> Result<Param> {
    let s = s.trim();
    if s.is_empty() {
        bail!("Empty parameter");
    }
    if (s.starts_with('"') && s.ends_with('"') && s.len() >= 2) || (s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2) {
        let inner = &s[1..s.len() - 1];
        return Ok(Param::Literal(Json::String(unescape_string(inner))));
    }
    if s.starts_with('(') && s.ends_with(')') {
        let inner = &s[1..s.len() - 1];
        return Ok(Param::SubExpr(Box::new(parse_expr(inner)?)));
    }
    match s {
        "true" => return Ok(Param::Literal(Json::Bool(true))),
        "false" => return Ok(Param::Literal(Json::Bool(false))),
        "null" => return Ok(Param::Literal(Json::Null)),
        "undefined" => return Ok(Param::Literal(Json::Null)),
        _ => {}
    }
    if let Ok(n) = s.parse::<i64>() {
        return Ok(Param::Literal(Json::from(n)));
    }
    if let Ok(f) = s.parse::<f64>() {
        if s.contains('.') {
            return Ok(Param::Literal(serde_json::Number::from_f64(f).map(Json::Number).unwrap_or(Json::Null)));
        }
    }
    Ok(Param::Path(s.to_string()))
}

fn unescape_string(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(n) = chars.next() {
                out.push(n);
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Split an expression into whitespace separated parameters, respecting
/// quotes, parentheses and brackets.
fn split_params(s: &str) -> Result<Vec<Param>> {
    let mut parts = Vec::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }
        let start = i;
        let mut depth = 0i32;
        let mut quote: Option<u8> = None;
        while i < bytes.len() {
            let b = bytes[i];
            if let Some(q) = quote {
                if b == b'\\' {
                    i += 2;
                    continue;
                }
                if b == q {
                    quote = None;
                }
                i += 1;
                continue;
            }
            match b {
                b'"' | b'\'' => quote = Some(b),
                b'(' | b'[' => depth += 1,
                b')' | b']' => depth -= 1,
                _ if b.is_ascii_whitespace() && depth <= 0 => break,
                _ => {}
            }
            i += 1;
        }
        let piece = &s[start..i.min(s.len())];
        parts.push(parse_single_param(piece)?);
    }
    Ok(parts)
}

// -------------------------------------------------------------------------
// Compilation

impl Template {
    pub fn compile(src: &str) -> Result<Template> {
        let mut tokens = tokenize(src)?;
        let indents = process_whitespace(&mut tokens);
        let mut pos = 0;
        let nodes = parse_nodes(&tokens, &indents, &mut pos, None)?;
        if pos < tokens.len() {
            bail!("Unexpected closing tag in template");
        }
        Ok(Template { nodes })
    }
}

fn parse_nodes(tokens: &[Token], indents: &[Option<String>], pos: &mut usize, open: Option<&str>) -> Result<Vec<Node>> {
    let mut nodes = Vec::new();
    while *pos < tokens.len() {
        let tok = &tokens[*pos];
        match &tok.kind {
            TokenKind::Text => {
                if !tok.content.is_empty() {
                    nodes.push(Node::Text(tok.content.clone()));
                }
                *pos += 1;
            }
            TokenKind::Comment => {
                *pos += 1;
            }
            TokenKind::Expression { raw } => {
                let expr = parse_expr(&tok.content)?;
                nodes.push(Node::Expression { expr, raw: *raw });
                *pos += 1;
            }
            TokenKind::Partial => {
                let expr = parse_expr(&tok.content)?;
                nodes.push(Node::Partial {
                    expr,
                    indent: indents[*pos].clone(),
                });
                *pos += 1;
            }
            TokenKind::BlockOpen { inverted } => {
                let expr = parse_expr(&tok.content)?;
                let name = expr.name.clone();
                *pos += 1;
                let body = parse_nodes(tokens, indents, pos, Some(&name))?;
                let mut inverse = None;
                // handle else
                if *pos < tokens.len() {
                    if let TokenKind::Else = tokens[*pos].kind {
                        let else_content = tokens[*pos].content.clone();
                        *pos += 1;
                        if else_content.is_empty() {
                            inverse = Some(parse_nodes(tokens, indents, pos, Some(&name))?);
                        } else {
                            // chained `{{else if x}}`: treat as nested block in inverse
                            let chained_expr = parse_expr(&else_content)?;
                            let chained_body = parse_nodes(tokens, indents, pos, Some(&name))?;
                            let mut chained_inverse = None;
                            // nested else chains
                            let mut chain = vec![(chained_expr, chained_body)];
                            while *pos < tokens.len() {
                                if let TokenKind::Else = tokens[*pos].kind {
                                    let c = tokens[*pos].content.clone();
                                    *pos += 1;
                                    if c.is_empty() {
                                        chained_inverse = Some(parse_nodes(tokens, indents, pos, Some(&name))?);
                                        break;
                                    } else {
                                        let e = parse_expr(&c)?;
                                        let b = parse_nodes(tokens, indents, pos, Some(&name))?;
                                        chain.push((e, b));
                                    }
                                } else {
                                    break;
                                }
                            }
                            // build nested blocks from the end
                            let mut acc = chained_inverse;
                            while let Some((e, b)) = chain.pop() {
                                acc = Some(vec![Node::Block {
                                    expr: e,
                                    inverted: false,
                                    body: b,
                                    inverse: acc,
                                }]);
                            }
                            inverse = acc;
                        }
                    }
                }
                // expect close
                if *pos < tokens.len() {
                    if let TokenKind::BlockClose = tokens[*pos].kind {
                        if tokens[*pos].content != name && !tokens[*pos].content.is_empty() {
                            bail!(
                                "Mismatched closing tag: expected {{{{/{}}}}}, found {{{{/{}}}}}",
                                name,
                                tokens[*pos].content
                            );
                        }
                        *pos += 1;
                    } else {
                        bail!("Unclosed block {{{{#{}}}}}", name);
                    }
                } else {
                    bail!("Unclosed block {{{{#{}}}}}", name);
                }
                nodes.push(Node::Block {
                    expr,
                    inverted: *inverted,
                    body,
                    inverse,
                });
            }
            TokenKind::BlockClose | TokenKind::Else => {
                if open.is_none() {
                    bail!("Unexpected {{{{/{}}}}} in template", tok.content);
                }
                return Ok(nodes);
            }
        }
    }
    if let Some(name) = open {
        bail!("Unclosed block {{{{#{}}}}}", name);
    }
    Ok(nodes)
}

// -------------------------------------------------------------------------
// Rendering

/// Escape a string the way handlebars does.
pub fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#x27;"),
            '`' => out.push_str("&#x60;"),
            '=' => out.push_str("&#x3D;"),
            _ => out.push(c),
        }
    }
    out
}

/// Render a JSON value to a string like handlebars does.
pub fn render_json(v: &Json) -> String {
    match v {
        Json::Null => String::new(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => n.to_string(),
        Json::String(s) => s.clone(),
        Json::Array(_) | Json::Object(_) => serde_json::to_string(v).unwrap_or_default(),
    }
}

pub fn is_truthy(v: &Json, include_zero: bool) -> bool {
    match v {
        Json::Bool(b) => *b,
        Json::Number(n) => {
            if include_zero {
                n.as_f64().map(|f| !f.is_nan()).unwrap_or(false)
            } else {
                n.as_f64().map(|f| f.is_normal()).unwrap_or(false)
            }
        }
        Json::Null => false,
        Json::String(s) => !s.is_empty(),
        Json::Array(a) => !a.is_empty(),
        Json::Object(o) => !o.is_empty(),
    }
}

/// A frame in the context stack.
#[derive(Debug, Clone)]
pub struct Frame {
    pub value: Json,
    pub locals: HashMap<String, Json>,
}

/// The rendering context.
pub struct RenderCtx<'a> {
    pub root: &'a Json,
    pub stack: Vec<Frame>,
}

impl<'a> RenderCtx<'a> {
    pub fn new(root: &'a Json) -> Self {
        RenderCtx {
            root,
            stack: vec![Frame {
                value: root.clone(),
                locals: HashMap::new(),
            }],
        }
    }

    pub fn current(&self) -> &Json {
        &self.stack.last().unwrap().value
    }

    /// Resolve a path expression.
    pub fn lookup(&self, path: &str) -> Json {
        let mut path = path;
        // local variables
        if let Some(local) = path.strip_prefix('@') {
            let mut segs = local.splitn(2, |c| c == '.' || c == '/');
            let first = segs.next().unwrap_or("");
            let rest = segs.next();
            let base = if first == "root" {
                self.root.clone()
            } else {
                // search frames from the top for the local
                let mut found = Json::Null;
                for frame in self.stack.iter().rev() {
                    if let Some(v) = frame.locals.get(first) {
                        found = v.clone();
                        break;
                    }
                }
                found
            };
            return match rest {
                Some(r) => lookup_in(&base, r),
                None => base,
            };
        }
        let mut depth = self.stack.len() - 1;
        loop {
            if let Some(r) = path.strip_prefix("../") {
                path = r;
                depth = depth.saturating_sub(1);
            } else if let Some(r) = path.strip_prefix("./") {
                path = r;
            } else {
                break;
            }
        }
        let base = &self.stack[depth].value;
        if path == "this" || path == "." || path.is_empty() {
            return base.clone();
        }
        let path = path.strip_prefix("this.").or_else(|| path.strip_prefix("this/")).unwrap_or(path);
        lookup_in(base, path)
    }
}

fn split_path_segments(path: &str) -> Vec<String> {
    let mut segs = Vec::new();
    let mut cur = String::new();
    let mut chars = path.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '[' => {
                // literal segment
                let mut lit = String::new();
                for ch in chars.by_ref() {
                    if ch == ']' {
                        break;
                    }
                    lit.push(ch);
                }
                cur.push_str(&lit);
            }
            '.' | '/' => {
                segs.push(std::mem::take(&mut cur));
            }
            _ => cur.push(c),
        }
    }
    segs.push(cur);
    segs.into_iter().filter(|s| !s.is_empty()).collect()
}

fn lookup_in(base: &Json, path: &str) -> Json {
    let mut cur = base;
    for seg in split_path_segments(path) {
        cur = match cur {
            Json::Object(o) => match o.get(&seg) {
                Some(v) => v,
                None => return Json::Null,
            },
            Json::Array(a) => match seg.parse::<usize>() {
                Ok(i) => match a.get(i) {
                    Some(v) => v,
                    None => return Json::Null,
                },
                Err(_) => return Json::Null,
            },
            _ => return Json::Null,
        };
    }
    cur.clone()
}

/// A custom helper.
pub type HelperFn = Box<dyn Fn(&Registry, &Expr, &[Json], &HashMap<String, Json>, &mut RenderCtx<'_>, Option<&Block>, &mut String) -> Result<()>>;

/// A block body passed to block helpers.
pub struct Block<'b> {
    pub body: &'b [Node],
    pub inverse: Option<&'b [Node]>,
}

/// Template registry (templates, partials and helpers).
#[derive(Default)]
pub struct Registry {
    templates: HashMap<String, Template>,
    helpers: HashMap<String, HelperFn>,
}

impl Registry {
    pub fn new() -> Registry {
        Registry::default()
    }

    pub fn register_template_string(&mut self, name: &str, src: &str) -> Result<()> {
        let t = Template::compile(src).with_context(|| format!("Failed to compile the `{name}` template"))?;
        self.templates.insert(name.to_string(), t);
        Ok(())
    }

    pub fn register_helper(&mut self, name: &str, f: HelperFn) {
        self.helpers.insert(name.to_string(), f);
    }

    pub fn has_template(&self, name: &str) -> bool {
        self.templates.contains_key(name)
    }

    pub fn render(&self, name: &str, data: &Json) -> Result<String> {
        let t = self
            .templates
            .get(name)
            .ok_or_else(|| anyhow!("Template not found: {name}"))?;
        let mut ctx = RenderCtx::new(data);
        let mut out = String::new();
        self.render_nodes(&t.nodes, &mut ctx, &mut out)?;
        Ok(out)
    }

    pub fn render_nodes(&self, nodes: &[Node], ctx: &mut RenderCtx<'_>, out: &mut String) -> Result<()> {
        for node in nodes {
            self.render_node(node, ctx, out)?;
        }
        Ok(())
    }

    pub fn eval_param(&self, p: &Param, ctx: &mut RenderCtx<'_>) -> Result<Json> {
        match p {
            Param::Path(path) => Ok(ctx.lookup(path)),
            Param::Literal(v) => Ok(v.clone()),
            Param::SubExpr(e) => {
                let mut s = String::new();
                self.eval_expr(e, ctx, &mut s, None, true)?;
                Ok(Json::String(s))
            }
        }
    }

    fn eval_params(&self, expr: &Expr, ctx: &mut RenderCtx<'_>) -> Result<(Vec<Json>, HashMap<String, Json>)> {
        let mut params = Vec::new();
        for p in &expr.params {
            params.push(self.eval_param(p, ctx)?);
        }
        let mut hash = HashMap::new();
        for (k, v) in &expr.hash {
            hash.insert(k.clone(), self.eval_param(v, ctx)?);
        }
        Ok((params, hash))
    }

    /// Evaluate an expression (helper call or path lookup), writing output.
    /// When `block` is Some this is a block helper invocation.
    fn eval_expr(&self, expr: &Expr, ctx: &mut RenderCtx<'_>, out: &mut String, block: Option<&Block>, raw: bool) -> Result<()> {
        let name = expr.name.as_str();
        let (params, hash) = self.eval_params(expr, ctx)?;
        if let Some(helper) = self.helpers.get(name) {
            return helper(self, expr, &params, &hash, ctx, block, out);
        }
        match name {
            "if" | "unless" => {
                let cond = params.first().map(|v| is_truthy(v, hash.get("includeZero").map(|z| is_truthy(z, false)).unwrap_or(false))).unwrap_or(false);
                let cond = if name == "unless" { !cond } else { cond };
                if let Some(b) = block {
                    if cond {
                        self.render_nodes(b.body, ctx, out)?;
                    } else if let Some(inv) = b.inverse {
                        self.render_nodes(inv, ctx, out)?;
                    }
                }
                Ok(())
            }
            "each" => {
                let value = params.first().cloned().unwrap_or(Json::Null);
                if let Some(b) = block {
                    self.render_each(&value, b, ctx, out)?;
                }
                Ok(())
            }
            "with" => {
                let value = params.first().cloned().unwrap_or(Json::Null);
                if let Some(b) = block {
                    if is_truthy(&value, false) {
                        ctx.stack.push(Frame {
                            value,
                            locals: HashMap::new(),
                        });
                        let r = self.render_nodes(b.body, ctx, out);
                        ctx.stack.pop();
                        r?;
                    } else if let Some(inv) = b.inverse {
                        self.render_nodes(inv, ctx, out)?;
                    }
                }
                Ok(())
            }
            "lookup" => {
                let obj = params.first().cloned().unwrap_or(Json::Null);
                let key = params.get(1).cloned().unwrap_or(Json::Null);
                let v = match (&obj, &key) {
                    (Json::Object(o), Json::String(k)) => o.get(k).cloned().unwrap_or(Json::Null),
                    (Json::Array(a), Json::Number(n)) => n.as_u64().and_then(|i| a.get(i as usize).cloned()).unwrap_or(Json::Null),
                    (Json::Array(a), Json::String(k)) => k.parse::<usize>().ok().and_then(|i| a.get(i).cloned()).unwrap_or(Json::Null),
                    _ => Json::Null,
                };
                self.write_value(&v, out, raw);
                Ok(())
            }
            "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "and" | "or" | "not" | "len" => {
                let v = builtin_logic(name, &params);
                if let Some(b) = block {
                    if is_truthy(&v, false) {
                        self.render_nodes(b.body, ctx, out)?;
                    } else if let Some(inv) = b.inverse {
                        self.render_nodes(inv, ctx, out)?;
                    }
                } else {
                    self.write_value(&v, out, raw);
                }
                Ok(())
            }
            "raw" => {
                if let Some(b) = block {
                    // output body verbatim: we cannot reconstruct the exact source, so render text nodes
                    for n in b.body {
                        if let Node::Text(t) = n {
                            out.push_str(t);
                        }
                    }
                }
                Ok(())
            }
            "log" => Ok(()),
            _ => {
                // path lookup
                let value = if expr.params.is_empty() {
                    ctx.lookup(name)
                } else {
                    bail!("Helper not defined: {}", name);
                };
                match block {
                    Some(b) => {
                        // block with path: `with` for objects, `each` for arrays
                        match &value {
                            Json::Array(_) => self.render_each(&value, b, ctx, out),
                            v if is_truthy(v, false) => {
                                ctx.stack.push(Frame {
                                    value: value.clone(),
                                    locals: HashMap::new(),
                                });
                                let r = self.render_nodes(b.body, ctx, out);
                                ctx.stack.pop();
                                r
                            }
                            _ => {
                                if let Some(inv) = b.inverse {
                                    self.render_nodes(inv, ctx, out)?;
                                }
                                Ok(())
                            }
                        }
                    }
                    None => {
                        self.write_value(&value, out, raw);
                        Ok(())
                    }
                }
            }
        }
    }

    fn render_each(&self, value: &Json, b: &Block, ctx: &mut RenderCtx<'_>, out: &mut String) -> Result<()> {
        match value {
            Json::Array(arr) if !arr.is_empty() => {
                let len = arr.len();
                for (i, item) in arr.iter().enumerate() {
                    let mut locals = HashMap::new();
                    locals.insert("index".to_string(), Json::from(i));
                    locals.insert("first".to_string(), Json::Bool(i == 0));
                    locals.insert("last".to_string(), Json::Bool(i + 1 == len));
                    ctx.stack.push(Frame {
                        value: item.clone(),
                        locals,
                    });
                    let r = self.render_nodes(b.body, ctx, out);
                    ctx.stack.pop();
                    r?;
                }
                Ok(())
            }
            Json::Object(obj) if !obj.is_empty() => {
                let len = obj.len();
                for (i, (k, item)) in obj.iter().enumerate() {
                    let mut locals = HashMap::new();
                    locals.insert("index".to_string(), Json::from(i));
                    locals.insert("key".to_string(), Json::String(k.clone()));
                    locals.insert("first".to_string(), Json::Bool(i == 0));
                    locals.insert("last".to_string(), Json::Bool(i + 1 == len));
                    ctx.stack.push(Frame {
                        value: item.clone(),
                        locals,
                    });
                    let r = self.render_nodes(b.body, ctx, out);
                    ctx.stack.pop();
                    r?;
                }
                Ok(())
            }
            _ => {
                if let Some(inv) = b.inverse {
                    self.render_nodes(inv, ctx, out)?;
                }
                Ok(())
            }
        }
    }

    pub fn write_value(&self, v: &Json, out: &mut String, raw: bool) {
        let s = render_json(v);
        if raw {
            out.push_str(&s);
        } else {
            out.push_str(&html_escape(&s));
        }
    }

    fn render_node(&self, node: &Node, ctx: &mut RenderCtx<'_>, out: &mut String) -> Result<()> {
        match node {
            Node::Text(t) => {
                out.push_str(t);
                Ok(())
            }
            Node::Expression { expr, raw } => self.eval_expr(expr, ctx, out, None, *raw),
            Node::Block {
                expr,
                inverted,
                body,
                inverse,
            } => {
                if *inverted {
                    // `{{^x}}` renders body when x is falsy
                    let value = ctx.lookup(&expr.name);
                    if !is_truthy(&value, false) {
                        self.render_nodes(body, ctx, out)?;
                    } else if let Some(inv) = inverse {
                        self.render_nodes(inv, ctx, out)?;
                    }
                    return Ok(());
                }
                let block = Block {
                    body,
                    inverse: inverse.as_deref(),
                };
                self.eval_expr(expr, ctx, out, Some(&block), true)
            }
            Node::Partial { expr, indent } => {
                let name = &expr.name;
                let t = match self.templates.get(name) {
                    Some(t) => t,
                    None => bail!("Partial not found: {}", name),
                };
                let mut partial_out = String::new();
                // partials may receive a context param and hash
                let (params, hash) = self.eval_params(expr, ctx)?;
                let pushed = if let Some(p) = params.first() {
                    ctx.stack.push(Frame {
                        value: p.clone(),
                        locals: HashMap::new(),
                    });
                    true
                } else if !hash.is_empty() {
                    let mut v = ctx.current().clone();
                    if let Json::Object(ref mut o) = v {
                        for (k, val) in hash {
                            o.insert(k, val);
                        }
                    }
                    ctx.stack.push(Frame {
                        value: v,
                        locals: HashMap::new(),
                    });
                    true
                } else {
                    false
                };
                let r = self.render_nodes(&t.nodes, ctx, &mut partial_out);
                if pushed {
                    ctx.stack.pop();
                }
                r?;
                match indent {
                    Some(ind) if !partial_out.is_empty() => {
                        let mut at_line_start = true;
                        for c in partial_out.chars() {
                            if at_line_start {
                                out.push_str(ind);
                                at_line_start = false;
                            }
                            out.push(c);
                            if c == '\n' {
                                at_line_start = true;
                            }
                        }
                    }
                    _ => out.push_str(&partial_out),
                }
                Ok(())
            }
        }
    }
}

fn builtin_logic(name: &str, params: &[Json]) -> Json {
    let a = params.first().cloned().unwrap_or(Json::Null);
    let b = params.get(1).cloned().unwrap_or(Json::Null);
    let num = |v: &Json| v.as_f64();
    match name {
        "eq" => Json::Bool(a == b),
        "ne" => Json::Bool(a != b),
        "gt" => Json::Bool(matches!((num(&a), num(&b)), (Some(x), Some(y)) if x > y)),
        "gte" => Json::Bool(matches!((num(&a), num(&b)), (Some(x), Some(y)) if x >= y)),
        "lt" => Json::Bool(matches!((num(&a), num(&b)), (Some(x), Some(y)) if x < y)),
        "lte" => Json::Bool(matches!((num(&a), num(&b)), (Some(x), Some(y)) if x <= y)),
        "and" => Json::Bool(params.iter().all(|p| is_truthy(p, false))),
        "or" => Json::Bool(params.iter().any(|p| is_truthy(p, false))),
        "not" => Json::Bool(!is_truthy(&a, false)),
        "len" => match &a {
            Json::Array(arr) => Json::from(arr.len()),
            Json::Object(o) => Json::from(o.len()),
            Json::String(s) => Json::from(s.chars().count()),
            _ => Json::from(0),
        },
        _ => Json::Null,
    }
}
