//! `mdbook test` implementation: run rustdoc on the book's Rust code samples.

use crate::book::{BookItem, MDBook};
use crate::errors::*;
use crate::preprocess::PreprocessorContext;
use crate::renderer::{RenderContext, Renderer};
use crate::utils;
use log::{debug, error, info};
use std::ffi::OsString;
use std::io::{IsTerminal, Write};
use std::path::Path;
use std::process::Command;

struct TestRenderer;

impl Renderer for TestRenderer {
    fn name(&self) -> &str {
        "test"
    }

    fn render(&self, _: &RenderContext) -> Result<()> {
        Ok(())
    }
}

pub fn test_chapter(book: &mut MDBook, library_paths: Vec<&str>, chapter: Option<&str>) -> Result<()> {
    let cwd = std::env::current_dir()?;
    let library_args: Vec<OsString> = library_paths
        .into_iter()
        .flat_map(|path| {
            let path = Path::new(path);
            let path = if path.is_relative() {
                cwd.join(path).into_os_string()
            } else {
                path.to_path_buf().into_os_string()
            };
            [OsString::from("-L"), path]
        })
        .collect();

    let temp_dir = tempfile::Builder::new().prefix("mdbook-").tempdir()?;

    let mut chapter_found = false;

    // Run the preprocessors (except `index`, so chapter paths keep pointing at
    // the markdown files).
    let renderer = TestRenderer;
    let mut preprocessed_book = book.book.clone();
    let preprocess_ctx = PreprocessorContext::new(book.root.clone(), book.config.clone(), renderer.name().to_string());
    for preprocessor in book.preprocessors() {
        if preprocessor.name() == crate::preprocess::index::IndexPreprocessor::NAME {
            continue;
        }
        if crate::book::preprocessor_should_run_pub(&**preprocessor, &renderer, &book.config)? {
            debug!("Running the {} preprocessor.", preprocessor.name());
            preprocessed_book = preprocessor.run(&preprocess_ctx, preprocessed_book)?;
        }
    }

    let color_output = std::io::stderr().is_terminal();
    let mut failed = false;
    for item in preprocessed_book.iter() {
        if let BookItem::Chapter(ref ch) = *item {
            let chapter_path = match ch.path {
                Some(ref path) if !path.as_os_str().is_empty() => path,
                _ => continue,
            };

            if let Some(chapter) = chapter {
                if ch.name != chapter && chapter_path.to_str() != Some(chapter) {
                    if chapter == "?" {
                        info!("Skipping chapter '{}'...", ch.name);
                    }
                    continue;
                }
            }
            chapter_found = true;
            info!("Testing chapter '{}': {:?}", ch.name, chapter_path);

            // write preprocessed file to tempdir
            let path = temp_dir.path().join(chapter_path);
            let mut tmpf = utils::create_file(&path)?;
            tmpf.write_all(ch.content.as_bytes())?;

            let mut cmd = Command::new("rustdoc");
            cmd.current_dir(temp_dir.path())
                .arg(chapter_path)
                .arg("--test")
                .args(&library_args);

            if let Some(edition) = book.config.rust.edition {
                cmd.args(["--edition", edition.as_str()]);
            }
            if color_output {
                cmd.args(["--color", "always"]);
            }

            debug!("running {:?}", cmd);
            let output = cmd.output()?;

            if !output.status.success() {
                failed = true;
                error!(
                    "rustdoc returned an error:\n\
                    \n--- stdout\n{}\n--- stderr\n{}",
                    String::from_utf8_lossy(&output.stdout),
                    String::from_utf8_lossy(&output.stderr)
                );
            }
        }
    }
    if failed {
        bail!("One or more tests failed");
    }
