//! A minimal re-implementation of the parts of elasticlunr needed to build a
//! search index compatible with the elasticlunr.js client (version 0.9.5).

use once_cell::sync::Lazy;
use regex::Regex;
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;

/// The inverted index trie node.
#[derive(Debug, Default, Clone)]
pub struct IndexItem {
    pub docs: BTreeMap<String, f64>,
    pub children: BTreeMap<char, IndexItem>,
}

impl IndexItem {
    fn add_token(&mut self, doc_ref: &str, token: &str, term_freq: f64) {
        let mut node = self;
        for c in token.chars() {
            node = node.children.entry(c).or_default();
        }
        node.docs.insert(doc_ref.to_string(), term_freq);
    }

    fn to_json(&self) -> Value {
        let mut map = Map::new();
        map.insert("df".to_string(), json!(self.docs.len()));
        let mut docs = Map::new();
        for (k, v) in &self.docs {
            docs.insert(k.clone(), json!({ "tf": v }));
        }
        map.insert("docs".to_string(), Value::Object(docs));
        for (c, child) in &self.children {
            map.insert(c.to_string(), child.to_json());
        }
        Value::Object(map)
    }
}

/// The search index.
#[derive(Debug)]
pub struct Index {
    fields: Vec<String>,
    ref_field: String,
    index: BTreeMap<String, IndexItem>,
    // doc_ref -> field -> stored value
    docs: BTreeMap<String, BTreeMap<String, String>>,
    // doc_ref -> field -> token count
    doc_info: BTreeMap<String, BTreeMap<String, usize>>,
}

impl Index {
    /// Create a new index with the given fields.
    pub fn new(fields: &[&str]) -> Index {
        let mut index = BTreeMap::new();
        for f in fields {
            index.insert(f.to_string(), IndexItem::default());
        }
        Index {
            fields: fields.iter().map(|s| s.to_string()).collect(),
            ref_field: "id".to_string(),
            index,
            docs: BTreeMap::new(),
            doc_info: BTreeMap::new(),
        }
    }

    /// Add a document. `fields` must be in the same order as the index fields.
    ///
    /// Note: this intentionally reproduces the behaviour of the Rust
    /// elasticlunr port, where the token frequency table is shared between
    /// the fields of a single document (so later fields also index the tokens
    /// of earlier fields).
    pub fn add_doc<I, S>(&mut self, doc_ref: &str, fields: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut doc = BTreeMap::new();
        doc.insert(self.ref_field.clone(), doc_ref.to_string());

        let mut token_freq: BTreeMap<String, u64> = BTreeMap::new();
        for (field, value) in self.fields.iter().zip(fields) {
            let value = value.as_ref();
            doc.insert(field.clone(), value.to_string());

            if field == &self.ref_field {
                continue;
            }

            let raw_tokens = tokenize(value);
            let tokens = run_pipeline(raw_tokens);

            self.doc_info
                .entry(doc_ref.to_string())
                .or_default()
                .insert(field.clone(), tokens.len());

            for token in tokens {
                *token_freq.entry(token).or_insert(0) += 1;
            }

            for (token, count) in &token_freq {
                let freq = (*count as f64).sqrt();
                self.index
                    .get_mut(field)
                    .expect("field exists")
                    .add_token(doc_ref, token, freq);
            }
        }

        self.docs.insert(doc_ref.to_string(), doc);
    }

    pub fn to_json(&self) -> Value {
        let mut doc_info = Map::new();
        for (doc_ref, fields) in &self.doc_info {
            let mut m = Map::new();
            for (f, n) in fields {
                m.insert(f.clone(), json!(n));
            }
            doc_info.insert(doc_ref.clone(), Value::Object(m));
        }
        let mut docs = Map::new();
        for (doc_ref, fields) in &self.docs {
            let mut m = Map::new();
            for (f, v) in fields {
                m.insert(f.clone(), Value::String(v.clone()));
            }
            docs.insert(doc_ref.clone(), Value::Object(m));
        }
        let mut index = Map::new();
        for (field, item) in &self.index {
            index.insert(field.clone(), json!({ "root": item.to_json() }));
        }
        json!({
            "documentStore": {
                "docInfo": doc_info,
                "docs": docs,
                "length": self.docs.len(),
                "save": true,
            },
            "fields": self.fields,
            "index": index,
            "lang": "English",
            "pipeline": ["trimmer", "stopWordFilter", "stemmer"],
            "ref": self.ref_field,
            "version": "0.9.5",
        })
    }
}

/// Split text into lowercase tokens on whitespace and hyphens.
pub fn tokenize(text: &str) -> Vec<String> {
    text.split(|c: char| c.is_whitespace() || c == '-')
        .filter(|s| !s.is_empty())
        .map(|s| s.trim().to_lowercase())
        .collect()
}

fn run_pipeline(tokens: Vec<String>) -> Vec<String> {
    tokens
        .into_iter()
        .filter_map(trimmer)
        .filter_map(stop_word_filter)
        .filter_map(|t| Some(stem(&t)))
        .collect()
}

fn is_word_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Remove leading and trailing non-word characters.
pub fn trimmer(token: String) -> Option<String> {
    let trimmed = token.trim_matches(|c: char| !is_word_char(c));
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

