//! Handlebars helpers used by the HTML renderer: `toc`, `previous`, `next`,
//! `resource` and `theme_option`.

use crate::errors::*;
use crate::hbs::{Block, Expr, Frame, Registry, RenderCtx};
use crate::utils;
use log::{debug, trace};
use serde_json::{json, Map, Value as Json};
use std::cmp::Ordering;
use std::collections::{BTreeMap, HashMap};
use std::path::Path;

type StringMap = BTreeMap<String, String>;

fn chapters_from_root(ctx: &RenderCtx<'_>) -> Result<Vec<StringMap>> {
    let chapters = ctx.root.get("chapters").cloned().unwrap_or(Json::Null);
    serde_json::from_value::<Vec<StringMap>>(chapters).with_context(|| "Could not decode the JSON data")
}

fn root_path(ctx: &RenderCtx<'_>) -> Result<String> {
    ctx.root
        .get("path")
        .and_then(|p| p.as_str())
        .map(|p| p.replace('"', ""))
        .ok_or_else(|| anyhow!("Type error for `path`, string expected"))
}

/// Escape a chapter name for inclusion in the TOC.
pub fn bracket_escape(mut s: &str) -> String {
    let mut escaped = String::with_capacity(s.len());
    let needs_escape: &[char] = &['<', '>', '\'', '\\', '&', '"'];
    while let Some(next) = s.find(needs_escape) {
        escaped.push_str(&s[..next]);
        match s.as_bytes()[next] {
            b'<' => escaped.push_str("&lt;"),
            b'>' => escaped.push_str("&gt;"),
            b'\'' => escaped.push_str("&#39;"),
            b'\\' => escaped.push_str("&#92;"),
            b'&' => escaped.push_str("&amp;"),
            b'"' => escaped.push_str("&quot;"),
            _ => unreachable!(),
        }
        s = &s[next + 1..];
    }
    escaped.push_str(s);
    escaped
}

fn write_li_open_tag(out: &mut String, is_expanded: bool, is_affix: bool) {
    let mut li = String::from("<li class=\"chapter-item ");
    if is_expanded {
        li.push_str("expanded ");
    }
    if is_affix {
        li.push_str("affix ");
    }
    li.push_str("\">");
    out.push_str(&li);
}

/// Render the table of contents.
pub fn render_toc(no_section_label: bool, ctx: &RenderCtx<'_>, out: &mut String) -> Result<()> {
    let chapters = chapters_from_root(ctx)?;
    let is_toc_html = ctx
        .root
        .get("is_toc_html")
        .map(|v| crate::hbs::is_truthy(v, false))
        .unwrap_or(false);
    let fold_enable = ctx
        .root
        .get("fold_enable")
        .and_then(|v| v.as_bool())
        .ok_or_else(|| anyhow!("Type error for `fold_enable`, bool expected"))?;
    let fold_level = ctx
        .root
        .get("fold_level")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| anyhow!("Type error for `fold_level`, u64 expected"))?;

    out.push_str("<ol class=\"chapter\">");

    let mut current_level = 1;

    for item in chapters {
        let (section, level) = if let Some(s) = item.get("section") {
            (s.as_str(), s.matches('.').count())
        } else {
            ("", 1)
        };

        let is_expanded = if !fold_enable {
            // Expand if folding is disabled
            true
        } else {
            // Levels that are larger than this would be folded.
            level - 1 < fold_level as usize
        };
        let _ = section;

        match level.cmp(&current_level) {
            Ordering::Greater => {
                while level > current_level {
                    out.push_str("<li>");
                    out.push_str("<ol class=\"section\">");
                    current_level += 1;
                }
                write_li_open_tag(out, is_expanded, false);
            }
            Ordering::Less => {
                while level < current_level {
                    out.push_str("</ol>");
                    out.push_str("</li>");
                    current_level -= 1;
                }
                write_li_open_tag(out, is_expanded, false);
            }
            Ordering::Equal => {
                write_li_open_tag(out, is_expanded, item.get("section").is_none());
            }
        }

        // Spacer
        if item.get("spacer").is_some() {
            out.push_str("<li class=\"spacer\"></li>");
            continue;
        }

        // Part title
        if let Some(title) = item.get("part") {
            out.push_str("<li class=\"part-title\">");
            out.push_str(&bracket_escape(title));
            out.push_str("</li>");
            continue;
        }

        // Link
        let path_exists: bool;
        match item.get("path") {
            Some(path) if !path.is_empty() => {
                out.push_str("<a href=\"");

                let tmp = Path::new(path)
                    .with_extension("html")
                    .to_str()
                    .unwrap()
                    // Hack for windows who tends to use `\` as separator instead of `/`
                    .replace('\\', "/");

                // Add link
                out.push_str(&utils::normalize_path(Path::new(&tmp)).to_string_lossy());
                out.push('"');
                if is_toc_html {
                    out.push_str(" target=\"_parent\"");
                }
                out.push('>');
                path_exists = true;
            }
            _ => {
                out.push_str("<div>");
                path_exists = false;
            }
        }

        if !no_section_label {
            // Section does not necessarily exist for all chapters (e.g. introduction)
            if let Some(section) = item.get("section") {
                out.push_str("<strong aria-hidden=\"true\">");
                out.push_str(section);
                out.push_str("</strong> ");
            }
        }

        if let Some(name) = item.get("name") {
            out.push_str(&bracket_escape(name));
        }

        if path_exists {
            out.push_str("</a>");
        } else {
            out.push_str("</div>");
        }

        // Render expand/collapse toggle
        if let Some(flag) = item.get("has_sub_items") {
            let has_sub_items = flag.parse::<bool>().unwrap_or_default();
            if fold_enable && has_sub_items {
                out.push_str("<a class=\"toggle\"><div>❱</div></a>");
            }
        }
        out.push_str("</li>");
    }
    while current_level > 1 {
        out.push_str("</ol>");
        out.push_str("</li>");
        current_level -= 1;
    }

    out.push_str("</ol>");
    Ok(())
}

#[derive(Clone, Copy)]
enum Target {
    Previous,
    Next,
}

impl Target {
    fn find(
        &self,
        base_path: &str,
        current_path: &str,
        current_item: &StringMap,
        previous_item: &StringMap,
    ) -> Result<Option<StringMap>> {
        match *self {
            Target::Next => {
                let previous_path = previous_item
                    .get("path")
                    .ok_or_else(|| anyhow!("No path found for chapter in JSON data"))?;

                if previous_path == base_path {
                    return Ok(Some(current_item.clone()));
                }
            }

            Target::Previous => {
                if current_path == base_path {
                    return Ok(Some(previous_item.clone()));
                }
            }
        }

        Ok(None)
    }
}

fn find_chapter(ctx: &RenderCtx<'_>, target: Target) -> Result<Option<StringMap>> {
    debug!("Get data from context");

    let chapters = chapters_from_root(ctx)?;
    let base_path = root_path(ctx)?;

    if ctx.root.get("is_index").is_some() {
        // Special case for index.md which may be a synthetic page.
        // Target::find won't match because there is no page with the path
        // "index.md" (unless there really is an index.md in SUMMARY.md).
        match target {
            Target::Previous => return Ok(None),
            Target::Next => match chapters
                .iter()
                .filter(|chapter| {
                    // Skip things like "spacer"
                    chapter.contains_key("path")
                })
                .nth(1)
            {
                Some(chapter) => return Ok(Some(chapter.clone())),
                None => return Ok(None),
            },
        }
    }

    let mut previous: Option<StringMap> = None;

    debug!("Search for chapter");

    for item in chapters {
        match item.get("path") {
            Some(path) if !path.is_empty() => {
                if let Some(previous) = previous {
                    if let Some(item) = target.find(&base_path, path, &item, &previous)? {
                        return Ok(Some(item));
                    }
                }

                previous = Some(item.clone());
            }
            _ => continue,
        }
    }

    Ok(None)
}

fn render_navigation(
    registry: &Registry,
    ctx: &mut RenderCtx<'_>,
    block: Option<&Block>,
    out: &mut String,
    chapter: &StringMap,
) -> Result<()> {
    trace!("Creating BTreeMap to inject in context");

    let mut context = match ctx.root {
        Json::Object(o) => o.clone(),
        _ => Map::new(),
    };

    chapter
        .get("path")
        .ok_or_else(|| anyhow!("No path found for chapter in JSON data"))
        .and_then(|p| {
            Path::new(p)
                .with_extension("html")
                .to_str()
                .ok_or_else(|| anyhow!("Link could not be converted to str"))
                .map(|p| context.insert("link".to_owned(), json!(p.replace('\\', "/"))))
        })?;

    chapter
        .get("name")
        .ok_or_else(|| anyhow!("No title found for chapter in JSON data"))
        .map(|n| context.insert("title".to_owned(), json!(n)))?;

    trace!("Render template");

    if let Some(b) = block {
        ctx.stack.push(Frame {
            value: Json::Object(context),
            locals: HashMap::new(),
        });
        let r = registry.render_nodes(b.body, ctx, out);
        ctx.stack.pop();
        r?;
    }
    Ok(())
}

pub fn previous(registry: &Registry, ctx: &mut RenderCtx<'_>, block: Option<&Block>, out: &mut String) -> Result<()> {
    trace!("previous (handlebars helper)");

    if let Some(previous) = find_chapter(ctx, Target::Previous)? {
        render_navigation(registry, ctx, block, out, &previous)?;
    }

    Ok(())
}

pub fn next(registry: &Registry, ctx: &mut RenderCtx<'_>, block: Option<&Block>, out: &mut String) -> Result<()> {
    trace!("next (handlebars helper)");

    if let Some(next) = find_chapter(ctx, Target::Next)? {
        render_navigation(registry, ctx, block, out, &next)?;
    }

    Ok(())
}

/// The `{{ resource "x" }}` helper.
pub fn resource(hash_map: &HashMap<String, String>, params: &[Json], ctx: &RenderCtx<'_>, out: &mut String) -> Result<()> {
    let param = params
        .first()
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow!("Param 0 with String type is required for resource helper."))?;
    let base_path = root_path(ctx)?;
    let path_to_root = utils::path_to_root(base_path);
    out.push_str(&path_to_root);
    out.push_str(hash_map.get(param).map(|p| p.as_str()).unwrap_or(param));
    Ok(())
}

/// The `{{ theme_option "Name" }}` helper.
pub fn theme_option(params: &[Json], ctx: &RenderCtx<'_>, out: &mut String) -> Result<()> {
    trace!("theme_option (handlebars helper)");
    let param = params
        .first()
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow!("Param 0 with String type is required for theme_option helper."))?;
    let default_theme = ctx
        .root
        .get("default_theme")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow!("Type error for `default_theme`, string expected"))?;
    let default_theme_name = default_theme.to_lowercase();
    out.push_str(&crate::hbs::html_escape(param));
    if param.to_lowercase() == default_theme_name {
        out.push_str(" (default)");
    }
    Ok(())
}

/// Register all the mdBook helpers on a registry.
pub fn register_helpers(registry: &mut Registry, no_section_label: bool, hash_map: HashMap<String, String>) {
    registry.register_helper(
        "toc",
        Box::new(move |_reg: &Registry, _expr: &Expr, _params: &[Json], _hash: &HashMap<String, Json>, ctx: &mut RenderCtx<'_>, _block: Option<&Block>, out: &mut String| {
            debug!("Rendering helper: \"toc\", params: [], hash: {{}}");
            render_toc(no_section_label, ctx, out)
        }),
    );
    registry.register_helper(
        "previous",
        Box::new(|reg: &Registry, _expr: &Expr, _params: &[Json], _hash: &HashMap<String, Json>, ctx: &mut RenderCtx<'_>, block: Option<&Block>, out: &mut String| {
            previous(reg, ctx, block, out)
        }),
    );
    registry.register_helper(
        "next",
        Box::new(|reg: &Registry, _expr: &Expr, _params: &[Json], _hash: &HashMap<String, Json>, ctx: &mut RenderCtx<'_>, block: Option<&Block>, out: &mut String| {
            next(reg, ctx, block, out)
        }),
    );
    registry.register_helper(
        "theme_option",
        Box::new(|_reg: &Registry, _expr: &Expr, params: &[Json], _hash: &HashMap<String, Json>, ctx: &mut RenderCtx<'_>, _block: Option<&Block>, out: &mut String| {
            theme_option(params, ctx, out)
        }),
    );
    registry.register_helper(
        "resource",
        Box::new(move |_reg: &Registry, _expr: &Expr, params: &[Json], _hash: &HashMap<String, Json>, ctx: &mut RenderCtx<'_>, _block: Option<&Block>, out: &mut String| {
            resource(&hash_map, params, ctx, out)
        }),
    );
}
