        if !html_config.copy_fonts && theme.fonts_css.is_none() {
            warn!("output.html.copy-fonts is deprecated.");
            warn!("There is no longer any built-in fonts.");
            warn!(
                "Set output.html.copy-fonts to true, or put font files in the theme/fonts directory, \
                 or set up a theme/fonts/fonts.css file."
            );
        }
        for font_file in &theme.font_files {
            let contents = fs::read(theme_dir.join("fonts").join(font_file))?;
            this.add_owned_builtin(format!("fonts/{font_file}"), contents);
        }

        if html_config.playground.editable && html_config.playground.copy_js {
            this.add_builtin("editor.js", theme::playground_editor::JS);
            this.add_builtin("ace.js", theme::playground_editor::ACE_JS);
            this.add_builtin("mode-rust.js", theme::playground_editor::MODE_RUST_JS);
            this.add_builtin("theme-dawn.js", theme::playground_editor::THEME_DAWN_JS);
            this.add_builtin(
                "theme-tomorrow_night.js",
                theme::playground_editor::THEME_TOMORROW_NIGHT_JS,
            );
        }

        let search = html_config.search.clone().unwrap_or_default();
        if search.enable && search.copy_js {
            this.add_builtin("searcher.js", theme::searcher::JS);
            this.add_builtin("mark.min.js", theme::searcher::MARK_JS);
            this.add_builtin("elasticlunr.min.js", theme::searcher::ELASTICLUNR_JS);
        }

        let custom_files = html_config
            .additional_css
            .iter()
            .chain(html_config.additional_js.iter());
        for custom_file in custom_files {
            let input_location = root.join(custom_file);
            this.static_files.push(StaticFile::Additional {
                input_location,
                output_location: custom_file.to_owned(),
            });
        }

        Ok(this)
    }

    pub fn add_builtin(&mut self, filename: &str, data: &[u8]) {
        self.static_files.push(StaticFile::Builtin {
            filename: filename.to_string(),
            data: data.to_vec(),
        });
    }

    pub fn add_owned_builtin(&mut self, filename: String, data: Vec<u8>) {
        self.static_files.push(StaticFile::Builtin { filename, data });
    }

    /// Rename static files to include a hash of their content.
    pub fn hash_files(&mut self) -> Result<()> {
        use sha2::{Digest, Sha256};

        fn hashed_name(filename: &str, data: &[u8]) -> String {
            let hash = Sha256::digest(data);
            let hex: String = hash.iter().take(4).map(|b| format!("{b:02x}")).collect();
            let path = Path::new(filename);
            let parent = path.parent().map(|p| p.to_string_lossy().into_owned()).unwrap_or_default();
            let name = path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
            let new_name = match name.find('.') {
                Some(pos) => format!("{}-{}{}", &name[..pos], hex, &name[pos..]),
                None => format!("{name}-{hex}"),
            };
            if parent.is_empty() {
                new_name
            } else {
                format!("{parent}/{new_name}")
            }
        }

        for static_file in &mut self.static_files {
            match static_file {
                StaticFile::Builtin { filename, data } => {
                    if filename.starts_with("FontAwesome/fonts/") {
                        continue;
                    }
                    if theme::fonts::LICENSES.iter().any(|(n, _)| n == filename) {
                        continue;
                    }
                    let new_name = hashed_name(filename, data);
                    self.hash_map.insert(filename.clone(), new_name);
                }
                StaticFile::Additional {
                    input_location,
                    output_location,
                } => {
                    let data = fs::read(&*input_location).with_context(|| {
                        format!("Unable to read {}", input_location.display())
                    })?;
                    let name = output_location.to_string_lossy().replace('\\', "/");
                    let new_name = hashed_name(&name, &data);
                    self.hash_map.insert(name, new_name);
                }
            }
        }
        Ok(())
    }

    /// Returns the output filename for the given original name.
    pub fn output_name(&self, filename: &str) -> String {
        self.hash_map
            .get(filename)
            .cloned()
            .unwrap_or_else(|| filename.to_string())
    }

    /// Write all the static files into `destination`.
    pub fn write_files(self, destination: &Path) -> Result<HashMap<String, String>> {
        // The `{{ resource }}` directive in static resources look like
        // handlebars syntax, even if they technically aren't.
        static RESOURCE: Lazy<Regex> = Lazy::new(|| Regex::new(r#"\{\{ resource "([^"]+)" \}\}"#).unwrap());

        fn replace_all(hash_map: &HashMap<String, String>, data: &[u8], filename: &str) -> Vec<u8> {
            let replacer = |captures: &Captures<'_>| {
                let name = captures.get(1).expect("capture 1 in resource regex").as_bytes();
                let name = std::str::from_utf8(name).expect("resource name with invalid utf8");
                let resource_filename = hash_map.get(name).map(|s| &s[..]).unwrap_or(name);
                let path_to_root = utils::path_to_root(filename);
                format!("{path_to_root}{resource_filename}").into_bytes()
            };
            RESOURCE.replace_all(data, replacer).into_owned()
        }

        for static_file in self.static_files {
            match static_file {
                StaticFile::Builtin { filename, data } => {
                    debug!("Writing builtin -> {}", filename);
                    let output_filename = self.hash_map.get(&filename).cloned().unwrap_or_else(|| filename.clone());
                    let data = if filename.ends_with(".css") || filename.ends_with(".js") {
                        replace_all(&self.hash_map, &data, &filename)
                    } else {
                        data
                    };
                    utils::write_file(destination, &output_filename, &data)?;
                }
                StaticFile::Additional {
                    input_location,
                    output_location,
                } => {
                    let name = output_location.to_string_lossy().replace('\\', "/");
                    let output_name = self.hash_map.get(&name).cloned().unwrap_or(name.clone());
                    debug!(
                        "Copying {} -> {}",
                        input_location.display(),
                        output_name
                    );
                    let output_path = destination.join(&output_name);
                    if let Some(parent) = output_path.parent() {
                        fs::create_dir_all(parent)
                            .with_context(|| format!("Unable to create {}", parent.display()))?;
                    }
                    let is_text = name.ends_with(".css") || name.ends_with(".js");
                    if is_text {
                        let data = fs::read(&input_location).with_context(|| {
                            format!("Unable to read {}", input_location.display())
                        })?;
                        let data = replace_all(&self.hash_map, &data, &name);
                        fs::write(&output_path, data)
                            .with_context(|| format!("Unable to write {}", output_path.display()))?;
                    } else {
                        fs::copy(&input_location, &output_path).with_context(|| {
                            format!(
                                "Unable to copy {} to {}",
                                input_location.display(),
                                output_path.display()
                            )
                        })?;
                    }
                }
            }
        }

        Ok(self.hash_map)
    }
}
