//! Search index generation.

use super::elasticlunr::Index;
use crate::book::{Book, BookItem, Chapter};
use crate::config::{HtmlConfig, Search, SearchChapterSettings};
use crate::errors::*;
use crate::html::render_md;
use crate::markdown::{self, Event, Tag, TagEnd};
use crate::utils;
use log::{debug, warn};
use once_cell::sync::Lazy;
use regex::Regex;
use serde_json::{json, Map, Value};
use std::borrow::Cow;
use std::collections::{HashMap, HashSet};
use std::path::Path;

const MAX_WORD_LENGTH_TO_INDEX: usize = 80;

/// Tokenizes in the same way as elasticlunr-rs (for English), but also drops
/// long tokens.
fn tokenize(text: &str) -> Vec<String> {
    text.split(|c: char| c.is_whitespace() || c == '-')
        .filter(|s| !s.is_empty())
        .map(|s| s.trim().to_lowercase())
        .filter(|s| s.len() <= MAX_WORD_LENGTH_TO_INDEX)
        .collect()
}

/// Collapse runs of whitespace into a single space.
pub fn collapse_whitespace(text: &str) -> Cow<'_, str> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\s\s+").unwrap());
    RE.replace_all(text, " ")
}

/// Creates all files required for search.
pub fn create_files(search_config: &Search, destination: &Path, book: &Book) -> Result<()> {
    let _ = destination;
    let _ = book;
    let _ = search_config;
    Ok(())
}

/// Build the search index JSON (as a JS file content) for the book.
pub fn build_index(html_config: &HtmlConfig, search_config: &Search, book: &Book, chapter_configs: &HashMap<String, SearchChapterSettings>) -> Result<String> {
    let mut index = Index::new(&["title", "body", "breadcrumbs"]);
    let mut doc_urls = Vec::with_capacity(book.sections.len());

    for item in book.iter() {
        let chapter = match *item {
            BookItem::Chapter(ref ch) if !ch.is_draft_chapter() => ch,
            _ => continue,
        };
        if !chapter_enabled(chapter, chapter_configs) {
            continue;
        }
        render_item(&mut index, html_config, search_config, &mut doc_urls, chapter)?;
    }

    let index = write_to_json(index, search_config, doc_urls)?;
    debug!("Writing search index ✓");
    if index.len() > 10_000_000 {
        warn!("searchindex.json is very large ({} bytes)", index.len());
    }
    Ok(index)
}

fn chapter_enabled(chapter: &Chapter, configs: &HashMap<String, SearchChapterSettings>) -> bool {
    let path = match &chapter.source_path {
        Some(p) => p,
        None => return true,
    };
    // Find the most specific matching setting.
    let mut enabled = true;
    let mut best_len = 0usize;
    let path_str = path.to_string_lossy().replace('\\', "/");
    for (key, settings) in configs {
        let key_norm = key.trim_end_matches('/');
        let matches = path_str == key_norm || path_str.starts_with(&format!("{key_norm}/"));
        if matches && key_norm.len() >= best_len {
            if let Some(e) = settings.enable {
                enabled = e;
                best_len = key_norm.len();
            }
        }
    }
    enabled
}

/// Uses the given arguments to construct a search document, then inserts it to the given index.
fn add_doc(index: &mut Index, doc_urls: &mut Vec<String>, anchor_base: &str, section_id: &Option<String>, items: &[&str]) {
    let url = if let Some(ref id) = *section_id {
        Cow::Owned(format!("{anchor_base}#{id}"))
    } else {
        Cow::Borrowed(anchor_base)
    };
    let url = collapse_whitespace(url.trim());
    let doc_ref = doc_urls.len().to_string();
    doc_urls.push(url.into());

