fn render_item(index: &mut Index, html_config: &HtmlConfig, search_config: &Search, doc_urls: &mut Vec<String>, chapter: &Chapter) -> Result<()> {
    let chapter_path = chapter
        .path
        .as_ref()
        .expect("Checked that path exists above");
    let filepath = Path::new(&chapter_path).with_extension("html");
    let filepath = filepath
        .to_str()
        .with_context(|| "Could not convert HTML path to str")?;
    let anchor_base = utils::normalize_path(Path::new(filepath))
        .to_string_lossy()
        .replace('\\', "/");

