                in_heading = true;
            }
            Event::End(TagEnd::Heading(level)) if level.as_u8() as u32 <= max_section_depth => {
                in_heading = false;
                section_id = Some(match heading_id.take() {
                    Some(id) => id,
                    None => render_md::unique_id_from_content(&heading, &mut id_counter),
                });
                breadcrumbs.push(heading.clone());
            }
            Event::Start(Tag::FootnoteDefinition(name)) => {
                let number = footnote_numbers.len() + 1;
                footnote_numbers.entry(name).or_insert(number);
            }
            Event::Html(html) | Event::InlineHtml(html) => {
                let mut html_block = html;

                // Collect consecutive Html events into a block.
                while let Some(Event::Html(html)) = p.peek() {
                    html_block.push_str(html);
                    p.next();
