fn clean_html(html: &str) -> String {
    let mut out = String::with_capacity(html.len());
    let bytes = html.as_bytes();
    let mut i = 0;
    let mut text_start = 0;
    let lower = html.to_ascii_lowercase();
    while i < bytes.len() {
