//! The HTML renderer.

pub mod elasticlunr;
pub mod helpers;
pub mod render_md;
pub mod search;
pub mod static_files;

use crate::book::{Book, BookItem};
use crate::config::{BookConfig, Config, HtmlConfig, RustEdition};
use crate::errors::*;
use crate::hbs::Registry;
use crate::renderer::{RenderContext, Renderer};
use crate::theme::{self, Theme};
use crate::utils;
use log::{debug, info, trace, warn};
use serde_json::{json, Map, Value as Json};
use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::path::{Path, PathBuf};

/// The HTML backend.
#[derive(Default)]
pub struct HtmlHandlebars;

impl HtmlHandlebars {
    /// Create a new `HtmlHandlebars` renderer.
    pub fn new() -> Self {
        HtmlHandlebars
    }

    fn render_item(&self, item: &BookItem, mut ctx: RenderItemContext<'_>, print_content: &mut String) -> Result<()> {
        // FIXME: This should be made DRY-er and rely less on mutable state
        let (ch, path) = match item {
            BookItem::Chapter(ch) if !ch.is_draft_chapter() => (ch, ch.path.as_ref().unwrap()),
            _ => return Ok(()),
        };

        if let Some(ref edit_url_template) = ctx.html_config.edit_url_template {
            let full_path = ctx.book_config.src.to_str().unwrap_or_default().to_owned()
                + "/"
                + ch.source_path
                    .clone()
                    .unwrap_or_default()
                    .to_str()
                    .unwrap_or_default();

            let edit_url = edit_url_template.replace("{path}", &full_path);
            ctx.data
                .insert("git_repository_edit_url".to_owned(), json!(edit_url));
        }

        let content = render_md::render_markdown(&ch.content, ctx.html_config.smart_punctuation());

        let printed_item = render_md::render_markdown_with_path(&ch.content, ctx.html_config.smart_punctuation(), Some(path));

        if !ctx.is_index && ctx.html_config.print.page_break {
            // Add page break between chapters
            // See https://developer.mozilla.org/en-US/docs/Web/CSS/break-before and https://developer.mozilla.org/en-US/docs/Web/CSS/page-break-before
            // Add both two CSS properties because of the compatibility issue
            print_content.push_str(r#"<div style="break-before: page; page-break-before: always;"></div>"#);
        }
        print_content.push_str(&printed_item);

        // Update the context with data for this file
        let ctx_path = path
            .to_str()
            .with_context(|| "Could not convert path to str")?;
        let filepath = Path::new(&ctx_path).with_extension("html");

        // "print.html" is used for the print page.
        if path == Path::new("print.md") {
            bail!("{} is reserved for internal use", path.display());
        };

        let book_title = ctx
            .data
            .get("book_title")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("");

        let title = if let Some(title) = ctx.chapter_titles.get(path) {
            title.clone()
        } else if book_title.is_empty() {
            ch.name.clone()
        } else {
            ch.name.clone() + " - " + book_title
        };

        ctx.data.insert("path".to_owned(), json!(path));
        ctx.data.insert("content".to_owned(), json!(content));
        ctx.data.insert("chapter_title".to_owned(), json!(ch.name));
        ctx.data.insert("title".to_owned(), json!(title));
        ctx.data.insert(
            "path_to_root".to_owned(),
            json!(utils::path_to_root(path)),
        );
        if let Some(ref section) = ch.number {
            ctx.data
                .insert("section".to_owned(), json!(section.to_string()));
        }

        // fragment redirects for this page
        let fragment_key = format!("/{}", filepath.to_string_lossy().replace('\\', "/"));
        if let Some(fragments) = ctx.fragment_maps.get(&fragment_key) {
            ctx.data.insert("fragment_map".to_owned(), json!(serde_json::to_string(fragments)?));
        } else {
            ctx.data.remove("fragment_map");
        }

        // Render the handlebars template with the data
        debug!("Render template");
        let rendered = ctx.handlebars.render("index", &Json::Object(ctx.data.clone()))?;

        let rendered = self.post_process(
            rendered,
            &ctx.html_config.playground,
            &ctx.html_config.code,
            ctx.edition,
        );

        // Write to file
        debug!("Creating {}", filepath.display());
        utils::write_file(&ctx.destination, &filepath, rendered.as_bytes())?;

        if ctx.is_index {
            ctx.data.insert("path".to_owned(), json!("index.md"));
            ctx.data.insert("path_to_root".to_owned(), json!(""));
            ctx.data.insert("is_index".to_owned(), json!(true));
            let rendered_index = ctx.handlebars.render("index", &Json::Object(ctx.data.clone()))?;
            let rendered_index = self.post_process(
                rendered_index,
                &ctx.html_config.playground,
                &ctx.html_config.code,
                ctx.edition,
            );
            debug!("Creating index.html from {}", ctx_path);
            utils::write_file(&ctx.destination, "index.html", rendered_index.as_bytes())?;
        }

        Ok(())
    }

    fn render_404(
        &self,
        ctx: &RenderContext,
        html_config: &HtmlConfig,
        src_dir: &Path,
        handlebars: &Registry,
        data: &Map<String, Json>,
    ) -> Result<()> {
        let destination = &ctx.destination;
        let content_404 = if let Some(ref filename) = html_config.input_404 {
            let path = src_dir.join(filename);
            std::fs::read_to_string(&path)
                .with_context(|| format!("unable to open 404 input file {path:?}"))?
        } else {
            // 404 input not explicitly configured try the default file 404.md
            let default_404_location = src_dir.join("404.md");
            if default_404_location.exists() {
                std::fs::read_to_string(&default_404_location).with_context(|| {
                    format!("unable to open 404 input file {default_404_location:?}")
                })?
            } else {
                "# Document not found (404)\n\nThis URL is invalid, sorry. Please use the \
                 navigation bar or search to continue."
                    .to_string()
            }
        };
        let html_content_404 = render_md::render_markdown(&content_404, html_config.smart_punctuation());

        let mut data_404 = data.clone();
        let base_url = if let Some(site_url) = &html_config.site_url {
            site_url
        } else {
            debug!(
                "HTML 'site-url' parameter not set, defaulting to '/'. Please configure \
                 this to ensure the 404 page work correctly, especially if your site is hosted in a \
                 subdirectory on the HTTP server."
            );
            "/"
        };
        data_404.insert("base_url".to_owned(), json!(base_url));
        // Set a dummy path to ensure other paths (e.g. in the TOC) are generated correctly
        data_404.insert("path".to_owned(), json!("404.md"));
        data_404.insert("content".to_owned(), json!(html_content_404));

        let mut title = String::from("Page not found");
        if let Some(book_title) = &ctx.config.book.title {
            title.push_str(" - ");
            title.push_str(book_title);
        }
        data_404.insert("title".to_owned(), json!(title));
        let rendered = handlebars.render("index", &Json::Object(data_404))?;

        let rendered = self.post_process(
            rendered,
            &html_config.playground,
            &html_config.code,
            ctx.config.rust.edition,
        );
        let output_file = get_404_output_file(&html_config.input_404);
        utils::write_file(destination, output_file, rendered.as_bytes())?;
        debug!("Creating 404.html ✓");
        Ok(())
    }

    fn post_process(&self, rendered: String, playground_config: &crate::config::Playground, code_config: &crate::config::Code, edition: Option<RustEdition>) -> String {
        render_md::post_process(rendered, playground_config, code_config, edition)
    }

    /// Update the context with data for this file
    fn configure_print_version(&self, data: &mut Map<String, Json>, print_content: &str) {
        // Make sure that the Print chapter does not display the title from
        // the last rendered chapter by removing it from its context
        data.remove("title");
        data.insert("is_print".to_owned(), json!(true));
        data.insert("path".to_owned(), json!("print.md"));
        data.insert("content".to_owned(), json!(print_content));
        data.insert(
            "path_to_root".to_owned(),
            json!(utils::path_to_root(Path::new("print.md"))),
        );
    }

    fn emit_redirects(&self, root: &Path, handlebars: &Registry, redirects: &BTreeMap<String, RedirectTarget>) -> Result<()> {
        if redirects.is_empty() {
            return Ok(());
        }

        log::debug!("Emitting redirects");

        for (original, target) in redirects {
            // Note: all paths are relative to the build directory, so the
            // leading slash in an absolute path means nothing (and would mess
            // up `root.join(original)`).
            let original_trimmed = original.trim_start_matches('/');
            let filename = root.join(original_trimmed);
            let destination = match &target.default {
                Some(d) => d,
                None => {
                    bail!(
                        "redirect entry for `{}` only has source paths with `#` fragments\n\
                         There must be an entry without the `#` fragment to determine the default destination.",
                        original_trimmed
                    );
                }
            };
            log::debug!("Redirecting \"{}\" → \"{}\"", original_trimmed, destination);
            self.emit_redirect(handlebars, &filename, destination, &target.fragments)?;
        }

        Ok(())
    }

    fn emit_redirect(&self, handlebars: &Registry, original: &Path, destination: &str, fragments: &BTreeMap<String, String>) -> Result<()> {
        if original.exists() {
            // sanity check to avoid accidentally overwriting a real file.
            let msg = format!(
                "Not redirecting \"{}\" to \"{}\" because it already exists. Are you sure it needs to be redirected?",
                original.display(),
                destination,
            );
            return Err(Error::msg(msg));
        }

        if let Some(parent) = original.parent() {
            std::fs::create_dir_all(parent)
                .with_context(|| format!("Unable to ensure \"{}\" exists", parent.display()))?;
        }

        let ctx = json!({
            "url": destination,
            "fragment_map": serde_json::to_string(fragments)?,
        });
        let rendered = handlebars
            .render("redirect", &ctx)
            .with_context(|| format!("Unable to create a redirect file at \"{}\"", original.display()))?;
        fs::write(original, rendered)
            .with_context(|| format!("Unable to create a redirect file at \"{}\"", original.display()))?;

        Ok(())
    }
}

/// A grouped redirect target: the default destination plus fragment redirects.
#[derive(Debug, Default)]
struct RedirectTarget {
    default: Option<String>,
    fragments: BTreeMap<String, String>,
}

/// Group the redirect config by target page.
fn group_redirects(redirects: &HashMap<String, String>) -> BTreeMap<String, RedirectTarget> {
    let mut grouped: BTreeMap<String, RedirectTarget> = BTreeMap::new();
    for (original, dest) in redirects {
        match original.split_once('#') {
            Some((path, fragment)) => {
                grouped
                    .entry(path.to_string())
                    .or_default()
                    .fragments
                    .insert(format!("#{fragment}"), dest.clone());
            }
            None => {
                grouped.entry(original.clone()).or_default().default = Some(dest.clone());
            }
        }
    }
    grouped
}

// TODO(mattico): Remove some time after the 0.1.8 release
fn maybe_wrong_theme_dir(dir: &Path) -> Result<bool> {
    fn entry_is_maybe_book_file(entry: fs::DirEntry) -> Result<bool> {
        Ok(entry.file_type()?.is_file()
            && entry.path().extension().map_or(false, |ext| ext == "md"))
    }

    if dir.is_dir() {
        for entry in fs::read_dir(dir)? {
            if entry_is_maybe_book_file(entry?).unwrap_or(false) {
                return Ok(false);
            }
        }
        Ok(true)
    } else {
        Ok(false)
    }
}

impl Renderer for HtmlHandlebars {
    fn name(&self) -> &str {
        "html"
    }

    fn render(&self, ctx: &RenderContext) -> Result<()> {
        let book_config = &ctx.config.book;
        let html_config = ctx.config.html_config().unwrap_or_default();
        let src_dir = ctx.root.join(&ctx.config.book.src);
        let destination = &ctx.destination;
        let book = &ctx.book;
        let build_dir = ctx.root.join(&ctx.config.build.build_dir);

        if destination.exists() {
            utils::remove_dir_content(destination)
                .with_context(|| "Unable to remove stale HTML output")?;
        }

        trace!("render");
        let mut handlebars = Registry::new();

        let theme_dir = match html_config.theme {
            Some(ref theme) => {
                let dir = ctx.root.join(theme);
                if !dir.is_dir() {
                    bail!("theme dir {} does not exist", dir.display());
                }
                dir
            }
            None => ctx.root.join("theme"),
        };

        if html_config.theme.is_none()
            && maybe_wrong_theme_dir(&src_dir.join("theme")).unwrap_or(false)
        {
            warn!(
                "Previous versions of mdBook erroneously accepted `./src/theme` as an automatic \
                 theme directory"
            );
            warn!("Please move your theme files to `./theme` for them to continue being used");
        }

        let theme = Theme::new(theme_dir);

        debug!("Register the index handlebars template");
        handlebars.register_template_string("index", &String::from_utf8(theme.index.clone())?)?;

        debug!("Register the head handlebars template");
        handlebars.register_template_string("head", &String::from_utf8(theme.head.clone())?)?;

        debug!("Register the redirect handlebars template");
        handlebars.register_template_string("redirect", &String::from_utf8(theme.redirect.clone())?)?;

        debug!("Register the header handlebars template");
        handlebars.register_template_string("header", &String::from_utf8(theme.header.clone())?)?;

        debug!("Register the toc handlebars template");
        handlebars.register_template_string("toc_js", &String::from_utf8(theme.toc_js.clone())?)?;
        handlebars.register_template_string("toc_html", &String::from_utf8(theme.toc_html.clone())?)?;

        let mut static_files = static_files::StaticFiles::new(&theme, &html_config, &ctx.root)?;

        // Search index
        let search = html_config.search.clone().unwrap_or_default();
        let search_index = if search.enable {
            let index = search::build_index(&html_config, &search, book, &search.chapter)?;
            Some(index)
        } else {
            None
        };
        if let Some(ref index) = search_index {
            if search.copy_js {
                let js = format!(
                    "window.search = Object.assign(window.search, JSON.parse('{}'));",
                    index.replace('\\', "\\\\").replace('\'', "\\'")
                );
                static_files.add_owned_builtin("searchindex.js".to_string(), js.into_bytes());
            }
        }

        // Redirect validation
        let grouped_redirects = group_redirects(&html_config.redirect);
        let mut fragment_maps: HashMap<String, BTreeMap<String, String>> = HashMap::new();
        {
            // compute existing chapter output paths
            let mut chapter_paths: Vec<String> = Vec::new();
            for item in book.iter() {
                if let BookItem::Chapter(ch) = item {
                    if let Some(p) = &ch.path {
                        let html = Path::new(p).with_extension("html");
                        chapter_paths.push(html.to_string_lossy().replace('\\', "/"));
                    }
                }
            }
            for (original, target) in &grouped_redirects {
                let trimmed = original.trim_start_matches('/');
                if chapter_paths.iter().any(|p| p == trimmed) {
                    if target.default.is_some() {
                        bail!(
                            "redirect found for existing chapter at `{}`\n\
                             Either delete the redirect or remove the chapter.",
                            original
                        );
                    }
                    fragment_maps.insert(format!("/{trimmed}"), target.fragments.clone());
                }
            }
        }
        let grouped_redirects: BTreeMap<String, RedirectTarget> = grouped_redirects
            .into_iter()
            .filter(|(original, _)| !fragment_maps.contains_key(&format!("/{}", original.trim_start_matches('/'))))
            .collect();

        debug!("Register handlebars helpers");
        if html_config.hash_files {
            static_files.hash_files()?;
        }
        // toc.js is generated later but its hashed name must be known for the templates;
        // we compute it after rendering below.

        let mut data = make_data(&ctx.root, book, &ctx.config, &html_config, &theme)?;

        // Render toc js (needs the resource helper, so register helpers with a
        // provisional hash map, then re-register once toc.js is hashed).
        let mut hash_map = static_files.hash_map.clone();
        helpers::register_helpers(&mut handlebars, html_config.no_section_label, hash_map.clone());
        {
            debug!("Render toc js");
            let mut toc_data = data.clone();
            toc_data.insert("path".to_owned(), json!("toc.js"));
            let rendered_toc = handlebars.render("toc_js", &Json::Object(toc_data))?;
            static_files.add_owned_builtin("toc.js".to_string(), rendered_toc.into_bytes());
            if html_config.hash_files {
                static_files.hash_files()?;
                hash_map = static_files.hash_map.clone();
                helpers::register_helpers(&mut handlebars, html_config.no_section_label, hash_map.clone());
            }
            debug!("Creating toc.js ✓");
        }

        fs::create_dir_all(destination)
            .with_context(|| "Unexpected error when constructing destination path")?;

        debug!("Copy static files");
        static_files
            .write_files(destination)
            .with_context(|| "Unable to copy across static files")?;
        if search_index.is_some() {
            debug!("Copying search files ✓");
        }

        {
            debug!("Render toc html");
            let mut toc_data = data.clone();
            toc_data.insert("path".to_owned(), json!("toc.html"));
            toc_data.insert("is_toc_html".to_owned(), json!(true));
            let rendered_toc = handlebars.render("toc_html", &Json::Object(toc_data))?;
            utils::write_file(destination, "toc.html", rendered_toc.as_bytes())?;
            debug!("Creating toc.html ✓");
        }

        // Print version
        let mut print_content = String::new();

        let mut is_index = true;
        for item in book.iter() {
            let ctx = RenderItemContext {
                handlebars: &handlebars,
                destination: destination.to_path_buf(),
                data: data.clone(),
                is_index,
                book_config: book_config.clone(),
                html_config: html_config.clone(),
                edition: ctx.config.rust.edition,
                chapter_titles: &ctx.chapter_titles,
                fragment_maps: &fragment_maps,
            };
            self.render_item(item, ctx, &mut print_content)?;
            // Only the first non-draft chapter item should be treated as the "index"
            is_index &= !matches!(item, BookItem::Chapter(ch) if !ch.is_draft_chapter());
        }

        // Render 404 page
        if html_config.input_404 != Some("".to_string()) {
            self.render_404(ctx, &html_config, &src_dir, &handlebars, &data)?;
        }

        // Print version
        self.configure_print_version(&mut data, &print_content);
        if let Some(ref title) = ctx.config.book.title {
            data.insert("title".to_owned(), json!(title));
        }

        // Render the handlebars template with the data
        if html_config.print.enable {
            debug!("Render template");
            let rendered = handlebars.render("index", &Json::Object(data.clone()))?;

            let rendered = self.post_process(
                rendered,
                &html_config.playground,
                &html_config.code,
                ctx.config.rust.edition,
            );

            utils::write_file(destination, "print.html", rendered.as_bytes())?;
            debug!("Creating print.html ✓");
        }

        self.emit_redirects(&ctx.destination, &handlebars, &grouped_redirects)
            .context("Unable to emit redirects")?;

        // Copy all remaining files, avoid a recursive copy from/to the book build dir
        utils::copy_files_except_ext(&src_dir, destination, true, Some(&build_dir), &["md"])?;

        // .nojekyll and CNAME
        utils::write_file(destination, ".nojekyll", b"This file makes sure that Github Pages doesn't process mdBook's output.\n")?;
        if let Some(cname) = &html_config.cname {
            utils::write_file(destination, "CNAME", format!("{cname}\n").as_bytes())?;
        }

        info!("HTML book written to `{}`", destination.display());

        Ok(())
    }
}

fn make_data(root: &Path, book: &Book, config: &Config, html_config: &HtmlConfig, theme: &Theme) -> Result<Map<String, Json>> {
    trace!("make_data");

    let mut data = Map::new();
    data.insert(
        "language".to_owned(),
        json!(config.book.language.clone().unwrap_or_default()),
    );
    data.insert(
        "text_direction".to_owned(),
        json!(config.book.realized_text_direction().as_str()),
    );
    data.insert(
        "book_title".to_owned(),
        json!(config.book.title.clone().unwrap_or_default()),
    );
    data.insert(
        "description".to_owned(),
        json!(config.book.description.clone().unwrap_or_default()),
    );
    if theme.favicon_png.is_some() {
        data.insert("favicon_png".to_owned(), json!("favicon.png"));
    }
    if theme.favicon_svg.is_some() {
        data.insert("favicon_svg".to_owned(), json!("favicon.svg"));
    }
    if let Some(ref live_reload_endpoint) = html_config.live_reload_endpoint {
        data.insert(
            "live_reload_endpoint".to_owned(),
            json!(live_reload_endpoint),
        );
    }

    let default_theme = match html_config.default_theme {
        Some(ref theme) => theme.to_lowercase(),
        None => "light".to_string(),
    };
    data.insert("default_theme".to_owned(), json!(default_theme));

    let preferred_dark_theme = match html_config.preferred_dark_theme {
        Some(ref theme) => theme.to_lowercase(),
        None => "navy".to_string(),
    };
    data.insert(
        "preferred_dark_theme".to_owned(),
        json!(preferred_dark_theme),
    );

    // Add check to see if there is an additional style
    if !html_config.additional_css.is_empty() {
        let mut css = Vec::new();
        for style in &html_config.additional_css {
            match style.strip_prefix(root) {
                Ok(p) => css.push(p.to_str().expect("Could not convert to str")),
                Err(_) => css.push(style.to_str().expect("Could not convert to str")),
            }
        }
        data.insert("additional_css".to_owned(), json!(css));
    }

    // Add check to see if there is an additional script
    if !html_config.additional_js.is_empty() {
        let mut js = Vec::new();
        for script in &html_config.additional_js {
            match script.strip_prefix(root) {
                Ok(p) => js.push(p.to_str().expect("Could not convert to str")),
                Err(_) => js.push(script.to_str().expect("Could not convert to str")),
            }
        }
        data.insert("additional_js".to_owned(), json!(js));
    }

    if html_config.playground.editable && html_config.playground.copy_js {
        data.insert("playground_js".to_owned(), json!(true));
        if html_config.playground.line_numbers {
            data.insert("playground_line_numbers".to_owned(), json!(true));
        }
    }
    if html_config.playground.copyable {
        data.insert("playground_copyable".to_owned(), json!(true));
    }

    data.insert("print_enable".to_owned(), json!(html_config.print.enable));
    data.insert("fold_enable".to_owned(), json!(html_config.fold.enable));
    data.insert("fold_level".to_owned(), json!(html_config.fold.level));

    let search = html_config.search.clone().unwrap_or_default();
    data.insert("search_enabled".to_owned(), json!(search.enable));
    data.insert(
        "search_js".to_owned(),
        json!(search.enable && search.copy_js),
    );

    if html_config.mathjax_support {
        data.insert("mathjax_support".to_owned(), json!(true));
    }

    if let Some(ref git_repository_url) = html_config.git_repository_url {
        data.insert("git_repository_url".to_owned(), json!(git_repository_url));
    }

    let git_repository_icon = match html_config.git_repository_icon {
        Some(ref git_repository_icon) => git_repository_icon,
        None => "fa-github",
    };
    data.insert("git_repository_icon".to_owned(), json!(git_repository_icon));

    let mut chapters = vec![];

    for item in book.iter() {
        // Create the data to inject in the template
        let mut chapter = BTreeMap::new();

        match *item {
            BookItem::PartTitle(ref title) => {
                chapter.insert("part".to_owned(), json!(title));
            }
            BookItem::Chapter(ref ch) => {
                if let Some(ref section) = ch.number {
                    chapter.insert("section".to_owned(), json!(section.to_string()));
                }

                chapter.insert(
                    "has_sub_items".to_owned(),
                    json!((!ch.sub_items.is_empty()).to_string()),
                );

                chapter.insert("name".to_owned(), json!(ch.name));
                if let Some(ref path) = ch.path {
                    let p = path
                        .to_str()
                        .ok_or_else(|| Error::msg("Could not convert path to str"))?;
                    chapter.insert("path".to_owned(), json!(p));
                }
            }
            BookItem::Separator => {
                chapter.insert("spacer".to_owned(), json!("_spacer_"));
            }
        }

        chapters.push(chapter);
    }

    data.insert("chapters".to_owned(), json!(chapters));
    data.insert("copy_fonts".to_owned(), json!(html_config.copy_fonts));

    debug!("[*]: JSON constructed");
    Ok(data)
}

struct RenderItemContext<'a> {
    handlebars: &'a Registry,
    destination: PathBuf,
    data: Map<String, Json>,
    is_index: bool,
    book_config: BookConfig,
    html_config: HtmlConfig,
    edition: Option<RustEdition>,
    chapter_titles: &'a HashMap<PathBuf, String>,
    fragment_maps: &'a HashMap<String, BTreeMap<String, String>>,
}

/// Compute the output file name of the 404 page.
pub fn get_404_output_file(input_404: &Option<String>) -> String {
    input_404
        .as_ref()
        .unwrap_or(&"404.md".to_string())
        .replace(".md", ".html")
}

