        ))
        .arg(
            Arg::new("hostname")
                .short('n')
                .long("hostname")
                .num_args(1)
                .default_value("localhost")
                .value_name("hostname")
                .help("Hostname to listen on for HTTP connections"),
        )
        .arg(
            Arg::new("port")
                .short('p')
                .long("port")
                .num_args(1)
                .default_value("3000")
                .value_name("port")
                .help("Port to use for HTTP connections"),
        )
        .arg(open_arg())
        .arg(watcher_arg())
}

pub fn execute(args: &ArgMatches) -> Result<()> {
    let book_dir = get_book_dir(args);
    let mut book = MDBook::load(&book_dir)?;

    let port = args.get_one::<String>("port").unwrap();
    let hostname = args.get_one::<String>("hostname").unwrap();
    let open_browser = args.get_flag("open");

    let address = format!("{hostname}:{port}");

    let update_config = |book: &mut MDBook| {
        book.config
            .set("output.html.live-reload-endpoint", crate::serve::LIVE_RELOAD_ENDPOINT)
            .expect("live-reload-endpoint update failed");
        if let Some(dest_dir) = args.get_one::<PathBuf>("dest-dir") {
            book.config.build.build_dir = dest_dir.into();
        }
        // Override site-url for local serving of the 404 file
        book.config.set("output.html.site-url", "/").unwrap();
    };
    update_config(&mut book);
    book.build()?;

    let sockaddr: std::net::SocketAddr = match std::net::ToSocketAddrs::to_socket_addrs(&address)
        .ok()
        .and_then(|mut addrs| addrs.next())
    {
        Some(a) => a,
        None => bail!("no address found for {}", address),
    };
    let build_dir = book.build_dir_for("html");
    let input_404 = book
        .config
        .get_owned("output.html.input-404")
        .and_then(|v| v.as_str().map(ToString::to_string))
        .map(|s| s.replace(".md", ".html"))
        .unwrap_or_else(|| "404.html".to_string());
    let file_404 = build_dir.join(input_404);

    let serving_url = format!("http://{address}");
    info!("Serving on: {}", serving_url);

    let reload_tx = crate::serve::start_server(sockaddr, build_dir, file_404)?;

    if open_browser {
        super::open(serving_url);
    }

    let watcher = args.get_one::<String>("watcher").map(|s| s.as_str()).unwrap_or("poll");
    crate::watch::rebuild_on_change(watcher, &book_dir, &update_config, &move || {
        let _ = reload_tx.send(());
    });

    let _ = error!("Unable to start the server");
    Ok(())
}
