//! A small static file HTTP server with a websocket live-reload endpoint.

use crate::errors::*;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{channel, Sender};
use std::sync::{Arc, Mutex};
use std::thread;

/// The websocket endpoint used for live reloading.
pub const LIVE_RELOAD_ENDPOINT: &str = "__livereload";

struct Shared {
    clients: Vec<TcpStream>,
}

/// Start the HTTP server in background threads. Returns a sender used to
/// trigger a reload of all connected websocket clients.
pub fn start_server(addr: SocketAddr, build_dir: PathBuf, file_404: PathBuf) -> Result<Sender<()>> {
    let listener = TcpListener::bind(addr).with_context(|| format!("Unable to bind to {addr}"))?;
    let shared = Arc::new(Mutex::new(Shared { clients: Vec::new() }));
    let (tx, rx) = channel::<()>();

    // reload broadcaster
    {
        let shared = shared.clone();
        thread::spawn(move || {
            while rx.recv().is_ok() {
                let mut guard = shared.lock().unwrap();
                let mut alive = Vec::new();
                for mut c in guard.clients.drain(..) {
                    if send_ws_text(&mut c, "reload").is_ok() {
                        alive.push(c);
                    }
                }
                guard.clients = alive;
            }
        });
    }

    thread::spawn(move || {
        for stream in listener.incoming() {
            let stream = match stream {
                Ok(s) => s,
                Err(_) => continue,
            };
            let build_dir = build_dir.clone();
            let file_404 = file_404.clone();
            let shared = shared.clone();
            thread::spawn(move || {
                let _ = handle_connection(stream, &build_dir, &file_404, shared);
            });
        }
    });

    Ok(tx)
}

fn handle_connection(mut stream: TcpStream, build_dir: &Path, file_404: &Path, shared: Arc<Mutex<Shared>>) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut request_line = String::new();
    reader.read_line(&mut request_line)?;
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("").to_string();
    let target = parts.next().unwrap_or("/").to_string();

    let mut headers: Vec<(String, String)> = Vec::new();
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line)? == 0 {
            break;
        }
        let line = line.trim_end_matches(['\r', '\n']);
        if line.is_empty() {
            break;
        }
        if let Some((k, v)) = line.split_once(':') {
            headers.push((k.trim().to_ascii_lowercase(), v.trim().to_string()));
        }
    }
    let header = |name: &str| headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.as_str());

    let path_part = target.split(['?', '#']).next().unwrap_or("/");

    // websocket live reload
    if path_part.trim_start_matches('/') == LIVE_RELOAD_ENDPOINT {
        if header("upgrade").map(|u| u.eq_ignore_ascii_case("websocket")).unwrap_or(false) {
            if let Some(key) = header("sec-websocket-key") {
                let accept = ws_accept_key(key);
                let response = format!(
                    "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {accept}\r\n\r\n"
                );
                stream.write_all(response.as_bytes())?;
                shared.lock().unwrap().clients.push(stream.try_clone()?);
                // keep reading (and ignoring) frames until the client disconnects
                let mut buf = [0u8; 1024];
                loop {
                    match stream.read(&mut buf) {
                        Ok(0) | Err(_) => break,
                        Ok(_) => {}
                    }
                }
                return Ok(());
            }
        }
        return write_response(&mut stream, 400, "text/plain", b"Bad Request", &method);
    }

    let decoded = percent_decode(path_part);
    let rel = decoded.trim_start_matches('/');
    if rel.contains("..") {
        return write_response(&mut stream, 404, "text/html", &std::fs::read(file_404).unwrap_or_default(), &method);
    }
    let mut fs_path = build_dir.join(rel);
    if fs_path.is_dir() {
        if !path_part.ends_with('/') {
            let location = format!("{path_part}/");
            let response = format!("HTTP/1.1 301 Moved Permanently\r\nLocation: {location}\r\nContent-Length: 0\r\n\r\n");
            return stream.write_all(response.as_bytes());
        }
        fs_path = fs_path.join("index.html");
    }
    match std::fs::read(&fs_path) {
        Ok(data) => write_response(&mut stream, 200, mime_for(&fs_path), &data, &method),
        Err(_) => {
            let body = std::fs::read(file_404).unwrap_or_default();
            write_response(&mut stream, 404, "text/html", &body, &method)
        }
    }
}

fn write_response(stream: &mut TcpStream, status: u16, content_type: &str, body: &[u8], method: &str) -> std::io::Result<()> {
    let reason = match status {
        200 => "OK",
        301 => "Moved Permanently",
        400 => "Bad Request",
        404 => "Not Found",
        _ => "OK",
    };
    let header = format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    stream.write_all(header.as_bytes())?;
    if method != "HEAD" {
        stream.write_all(body)?;
    }
    stream.flush()
}

fn mime_for(path: &Path) -> &'static str {
    match path.extension().and_then(|e| e.to_str()).unwrap_or("") {
        "html" | "htm" => "text/html",
        "css" => "text/css",
        "js" => "text/javascript",
        "json" => "application/json",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "eot" => "application/vnd.ms-fontobject",
        "txt" | "md" => "text/plain",
        "xml" => "text/xml",
        "pdf" => "application/pdf",
        _ => "application/octet-stream",
    }
}

fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() + 0 && i + 2 <= bytes.len() - 1 {
            if let Ok(v) = u8::from_str_radix(&s[i + 1..i + 3], 16) {
                out.push(v);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn send_ws_text(stream: &mut TcpStream, text: &str) -> std::io::Result<()> {
    let payload = text.as_bytes();
    let mut frame = vec![0x81u8];
    if payload.len() < 126 {
        frame.push(payload.len() as u8);
    } else {
        frame.push(126);
        frame.extend_from_slice(&(payload.len() as u16).to_be_bytes());
    }
    frame.extend_from_slice(payload);
    stream.write_all(&frame)?;
    stream.flush()
}

fn ws_accept_key(key: &str) -> String {
    use base64::Engine;
    let mut data = key.trim().as_bytes().to_vec();
    data.extend_from_slice(b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
    let digest = sha1(&data);
    base64::engine::general_purpose::STANDARD.encode(digest)
}

/// Minimal SHA-1 implementation (used for the websocket handshake).
fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let mut msg = data.to_vec();
    let bit_len = (data.len() as u64) * 8;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h[0], h[1], h[2], h[3], h[4]);
        for (i, wi) in w.iter().enumerate() {
            let (f, k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A827999),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDC),
                _ => (b ^ c ^ d, 0xCA62C1D6),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(*wi);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut out = [0u8; 20];
    for (i, v) in h.iter().enumerate() {
        out[4 * i..4 * i + 4].copy_from_slice(&v.to_be_bytes());
    }
    out
}
