//! File watching for `watch` and `serve` (polling implementation).

use crate::book::MDBook;
use crate::errors::*;
use log::{error, info};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

/// Snapshot of (path -> mtime, len) for the watched locations.
type Snapshot = HashMap<PathBuf, (Option<SystemTime>, u64)>;

fn watched_paths(book: &MDBook) -> Vec<PathBuf> {
    let mut paths = vec![book.source_dir(), book.theme_dir()];
    let book_toml = book.root.join("book.toml");
    if book_toml.exists() {
        paths.push(book_toml);
    }
    for dir in &book.config.build.extra_watch_dirs {
        let path = book.root.join(dir);
        paths.push(path);
    }
    paths
}

fn snapshot(paths: &[PathBuf], ignore: &Option<ignore::gitignore::Gitignore>, root: &Path) -> Snapshot {
    let mut snap = Snapshot::new();
    for p in paths {
        if p.is_file() {
            if let Ok(meta) = std::fs::metadata(p) {
                snap.insert(p.clone(), (meta.modified().ok(), meta.len()));
            }
            continue;
        }
        if !p.exists() {
            continue;
        }
        for entry in walkdir::WalkDir::new(p).into_iter().filter_map(|e| e.ok()) {
            let path = entry.path();
            if let Some(gi) = ignore {
                let rel = path.strip_prefix(root).unwrap_or(path);
                if gi.matched_path_or_any_parents(rel, path.is_dir()).is_ignore() {
                    continue;
                }
            }
            if let Ok(meta) = entry.metadata() {
                snap.insert(path.to_path_buf(), (meta.modified().ok(), if meta.is_dir() { 0 } else { meta.len() }));
            }
        }
    }
    snap
}

fn load_gitignore(root: &Path) -> Option<ignore::gitignore::Gitignore> {
    let gitignore_path = root.join(".gitignore");
    if gitignore_path.exists() {
        let (gi, _err) = ignore::gitignore::Gitignore::new(&gitignore_path);
        Some(gi)
    } else {
        None
    }
}

/// Watch the book's files, rebuilding on change. Never returns.
pub fn rebuild_on_change(watcher: &str, book_dir: &Path, update_config: &dyn Fn(&mut MDBook), post_build: &dyn Fn()) {
    let _ = watcher;
    let mut book = match MDBook::load(book_dir) {
        Ok(b) => b,
        Err(e) => {
            error!("Unable to load the book: {}", e);
            return;
        }
    };
    update_config(&mut book);

    let mut paths = watched_paths(&book);
    let mut gitignore = load_gitignore(&book.root);
    let mut last = snapshot(&paths, &gitignore, &book.root);
    info!("Listening for changes...");

    loop {
        std::thread::sleep(Duration::from_secs(1));
        let current = snapshot(&paths, &gitignore, &book.root);
        if current != last {
            let mut changed: Vec<&PathBuf> = current
                .iter()
                .filter(|(k, v)| last.get(*k) != Some(v))
                .map(|(k, _)| k)
                .chain(last.keys().filter(|k| !current.contains_key(*k)))
                .collect();
            changed.sort();
            changed.dedup();
            for c in &changed {
                info!("File changed: {}", c.display());
            }
            info!("Building book...");
            // FIXME: This area is really ugly because we need to re-set livereload :(
            let result = MDBook::load(book_dir).and_then(|mut b| {
                update_config(&mut b);
                b.build()
            });
            match result {
                Ok(_) => {
                    post_build();
                }
                Err(e) => {
                    error!("Unable to load the book");
                    crate::utils::log_backtrace(&e);
                }
            }
            if let Ok(mut b) = MDBook::load(book_dir) {
                update_config(&mut b);
                paths = watched_paths(&b);
                gitignore = load_gitignore(&b.root);
            }
            last = snapshot(&paths, &gitignore, &book.root);
        }
    }
}

#[allow(dead_code)]
fn _unused() -> Result<()> {
    Ok(())
}
