//! The `clean` subcommand.

use super::{dest_dir_arg, dir_arg, get_book_dir};
use crate::book::MDBook;
use crate::errors::*;
use clap::{ArgMatches, Command};
use std::fs;
use std::path::{Path, PathBuf};

pub fn make_subcommand() -> Command {
    Command::new("clean")
        .about("Deletes a built book")
        .arg(dest_dir_arg())
        .arg(dir_arg(
            "Root directory for the book\n(Defaults to the current directory when omitted)",
        ))
}

pub fn execute(args: &ArgMatches) -> Result<()> {
    let book_dir = get_book_dir(args);
    let book = MDBook::load(book_dir)?;

    let dir_to_remove = match args.get_one::<PathBuf>("dest-dir") {
        Some(dest_dir) => dest_dir.into(),
        None => book.root.join(&book.config.build.build_dir),
    };

    let (files, dirs, bytes) = count_entries(&dir_to_remove);

    if dir_to_remove.exists() {
        fs::remove_dir_all(&dir_to_remove).with_context(|| "Unable to remove the build directory")?;
    }

    if files == 0 && dirs == 0 {
        println!("Removed 0 files");
    } else if files > 0 {
        println!(
            "Removed {} {}, {} total",
            files,
            if files == 1 { "file" } else { "files" },
            format_size(bytes)
        );
    } else {
        println!(
            "Removed {} {}, {} total",
            dirs,
            if dirs == 1 { "directory" } else { "directories" },
            format_size(bytes)
        );
    }

    Ok(())
}

/// Count the files and directories under `dir` (including `dir` itself) and
/// their total size.
fn count_entries(dir: &Path) -> (u64, u64, u64) {
    let mut files = 0;
    let mut dirs = 0;
    let mut bytes = 0;
    if !dir.exists() {
        return (0, 0, 0);
    }
    for entry in walkdir::WalkDir::new(dir).into_iter().filter_map(|e| e.ok()) {
        if let Ok(meta) = fs::metadata(entry.path()) {
            if meta.is_dir() {
                dirs += 1;
            } else if meta.is_file() {
                files += 1;
            }
            bytes += meta.len();
        }
    }
    (files, dirs, bytes)
}

fn format_size(bytes: u64) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    if bytes < 1024 {
        return format!("{bytes}B");
    }
    let mut size = bytes as f64;
    let mut unit = 0;
    while size >= 1024.0 && unit < UNITS.len() - 1 {
        size /= 1024.0;
        unit += 1;
    }
    format!("{size:.2}{}", UNITS[unit])
}
