pub fn open<P: AsRef<std::ffi::OsStr>>(path: P) {
    log::info!(target: "mdbook", "Opening web browser");
    let mut candidates: Vec<String> = Vec::new();
    if let Ok(browser) = std::env::var("BROWSER") {
        if !browser.is_empty() {
            candidates.push(browser);
        }
    }
    for c in ["xdg-open", "sensible-browser", "gio", "gnome-open", "kde-open", "wslview", "x-www-browser"] {
        candidates.push(c.to_string());
    }
    let mut last_err: Option<std::io::Error> = None;
    for c in candidates {
        let res = std::process::Command::new(&c)
            .arg(path.as_ref())
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn();
        match res {
            Ok(mut child) => {
                // Don't block on the browser process.
                std::thread::spawn(move || {
                    let _ = child.wait();
                });
                return;
            }
            Err(e) => last_err = Some(e),
        }
    }
    if let Some(e) = last_err {
        log::error!(target: "mdbook", "Error opening web browser: {}", e);
    }
}

