new='''/// Strip HTML tags from a string, keeping the text content.
fn clean_html(html: &str) -> String {
    let mut out = String::with_capacity(html.len());
    let bytes = html.as_bytes();
    let lower = html.to_ascii_lowercase();
    let mut i = 0;
    let mut text_start = 0;
    while i < bytes.len() {
        if bytes[i] != b'<' {
            i += 1;
            continue;
        }
        let next = bytes.get(i + 1).copied();
        let is_tag = matches!(next, Some(b) if b.is_ascii_alphabetic() || b == b'/' || b == b'!' || b == b'?');
        if !is_tag {
            i += 1;
            continue;
        }
        // flush text
        out.push_str(&decode_and_escape(&html[text_start..i]));
        let end;
        if html[i..].starts_with("<!--") {
            end = match html[i + 4..].find("-->") {
                Some(e) => i + 4 + e + 3,
                None => html.len(),
            };
        } else {
            // scan the tag, respecting quoted attribute values
            let mut j = i + 1;
            let mut quote: Option<u8> = None;
            let mut found = None;
            while j < bytes.len() {
                let b = bytes[j];
                match quote {
                    Some(q) => {
                        if b == q {
                            quote = None;
                        }
                    }
                    None => {
                        if b == b'"' || b == b'\\'' {
                            quote = Some(b);
                        } else if b == b'>' {
                            found = Some(j + 1);
                            break;
                        }
                    }
                }
                j += 1;
            }
            end = match found {
                Some(e) => e,
                None => html.len(),
            };
        }
        // script/style: drop content
        let skip_tag = ["script", "style"]
            .iter()
            .find(|t| {
                lower[i + 1..].starts_with(*t)
                    && !lower
                        .as_bytes()
                        .get(i + 1 + t.len())
                        .map(|b| b.is_ascii_alphanumeric())
                        .unwrap_or(false)
            })
            .copied();
        i = end;
        if let Some(tag) = skip_tag {
            let close = format!("</{tag}");
            if let Some(c) = lower[i..].find(&close) {
                let after = i + c;
                i = match html[after..].find('>') {
                    Some(e) => after + e + 1,
                    None => html.len(),
                };
            } else {
                i = html.len();
            }
        }
        text_start = i;
    }
    if text_start < html.len() {
        out.push_str(&decode_and_escape(&html[text_start..]));
    }
    out
}

